var e=JSON.parse("[[2801,\"Next.js — це React-фреймворк для створення повнофункціональних вебзастосунків. Він надає вбудовані рішення для маршрутизації, рендерингу на стороні сервера й оптимізації. Досвід роботи з ним включає створення сторінок та API-маршрутів і використання різних стратегій рендерингу.\",\"Next.js — потужний фреймворк над React, який розв'язує багато поширених задач веброзробки «із коробки».\\nОсновні аспекти роботи з Next.js:\\n\\n- Структура проєкту: чітка файлова структура, де сторінки створюють у теці `pages` або `app` (у Next.js 13+)\\n\\n- Маршрутизація: автоматична маршрутизація на основі файлової системи\\n\\n- API Routes: можливість створювати серверні API-ендпоїнти в тій самій кодовій базі\\n\\nПриклад створення сторінки:\\n\\nПриклад API-маршруту:\\n\\nВисновок: досвід роботи з Next.js включає розуміння його архітектури, вбудованих можливостей та оптимальних практик розробки.\",\"// pages/about.js\\nexport default function About() {\\n  return <h1>About us</h1>\\n}\\n\\n// pages/api/users.js\\nexport default function handler(req, res) {\\n  res.status(200).json({ users: [] })\\n}\"],[2802,\"Next.js пропонує три основні види генерації сторінок: SSG (статична генерація), SSR (рендеринг на сервері) та ISR (інкрементальна статична регенерація). SSG створює сторінки на етапі збирання, SSR — під час кожного запиту, а ISR дозволяє оновлювати статичні сторінки без повного перезбирання.\",\"Next.js надає гнучкі можливості рендерингу для різних сценаріїв використання.\\nТипи генерації сторінок:\\n\\n- SSG (Static Site Generation)\\n\\n- Сторінки генеруються під час збирання застосунку\\n\\n- Ідеально для контенту, який рідко змінюється\\n\\n- Максимальна продуктивність і дружність до SEO\\n\\n- SSR (Server-Side Rendering)\\n\\n- Сторінки рендеряться на сервері під час кожного запиту\\n\\n- Підходить для динамічного контенту, який часто змінюється\\n\\n- Гарантує актуальність даних\\n\\n- ISR (Incremental Static Regeneration)\\n\\n- Гібридний підхід: статичні сторінки з можливістю оновлення\\n\\n- Можна вказати інтервал, через який сторінки регенеруються\\n\\n- Ідеально для контенту, який часто змінюється й великий за обсягом\\n\\nКоли що використовувати:\\n\\n- SSG: блоги, документація, лендинги\\n\\n- SSR: персоналізований контент, динамічні дані\\n\\n- ISR: каталоги товарів, новинні сайти\",null],[2803,\"`getStaticProps` отримує дані для статичних сторінок на етапі збирання. `getServerSideProps` отримує дані під час кожного запиту, на сервері. `getStaticPaths` визначає, які динамічні шляхи потрібно згенерувати заздалегідь для статичних сторінок.\",\"Ці функції — основні інструменти для роботи з даними в Next.js.\\nВідмінності й призначення:\\n\\n- getStaticProps\\n\\n- Використовують для SSG (статичної генерації)\\n\\n- Виконується під час збирання застосунку\\n\\n- Дані кешуються й використовуються для кожного запиту\\n\\n- getServerSideProps\\n\\n- Використовують для SSR (рендерингу на сервері)\\n\\n- Виконується під час кожного запиту\\n\\n- Дані завжди актуальні\\n\\n- getStaticPaths\\n\\n- Використовують разом із `getStaticProps` для динамічних маршрутів\\n\\n- Визначає, які саме шляхи потрібно згенерувати статично\\n\\nВисновок: вибір функції залежить від вимог до актуальності даних і до продуктивності.\",\"export async function getStaticProps() {\\n  const data = await fetchData()\\n  return { props: { data } }\\n}\\n\\nexport async function getServerSideProps(context) {\\n  const userData = await fetchUserData(context.req)\\n  return { props: { userData } }\\n}\\n\\nexport async function getStaticPaths() {\\n  const paths = await getAllPostIds()\\n  return { paths, fallback: false }\\n}\"],[2804,\"Middleware в Next.js — це функції, які виконуються перед обробкою запиту. Їх використовують для аутентифікації, логування, перенаправлень і модифікації відповідей. Middleware працює на edge-серверах і може обробляти запити, перед тим як вони досягнуть застосунку.\",\"Middleware надає потужний механізм для перехоплення й обробки запитів, перед тим як вони досягнуть сторінок або API-маршрутів.\\nОсновні випадки використання middleware:\\n\\n- Аутентифікація й авторизація: перевірка прав доступу користувача\\n\\n- Геолокація: перенаправлення користувачів на основі їхнього розташування\\n\\n- Логування: збирання аналітики й моніторинг запитів\\n\\n- Модифікація заголовків: додавання або зміна HTTP-заголовків\\n\\nПриклад middleware для аутентифікації:\\n\\nОсобливості роботи:\\n\\n- Виконується на edge-серверах (ближче до користувача)\\n\\n- Може працювати із запитами до сторінок і до API-маршрутів\\n\\n- Підтримує умовну логіку на основі шляху запиту\\n\\nВисновок: middleware — потужний інструмент для централізованої обробки запитів і реалізації перехресних аспектів.\",\"// middleware.js\\nimport { NextResponse } from 'next/server'\\n\\nexport function middleware(request) {\\n  const token = request.cookies.get('auth-token')\\n  \\n  if (!token) {\\n    return NextResponse.redirect(new URL('/login', request.url))\\n  }\\n  \\n  return NextResponse.next()\\n}\\n\\nexport const config = {\\n  matcher: '/dashboard/:path*'\\n}\"],[2805,\"Під час SSR HTML формує сервер, який виконує код застосунку в серверному середовищі. Браузер отримує готовий HTML, швидко показує розмітку, а потім завантажує JavaScript і «оживляє» сторінку, зв'язуючи обробники й стан. Це дає швидший перший показ і краще SEO, але додає навантаження на сервер.\",\"Під час SSR важливо розділяти два етапи: «згенерувати HTML» і «зробити інтерфейс інтерактивним».\\n1) Хто саме генерує HTML\\nВизначення: SSR (Server-Side Rendering) — підхід, за якого HTML сторінки генерується на сервері, а не збирається цілком у браузері з JavaScript.\\n\\n- HTML рендерить сервер:\\n\\n- сервер виконує код застосунку (наприклад, рендеринг React-компонентів у рядок HTML)\\n\\n- підставляє дані (часто отримані до рендеру)\\n\\n- На цьому етапі браузер просто отримує HTML і розбирає його, як звичайну сторінку.\\n\\n2) Що робить браузер, отримавши SSR-HTML\\nБраузер спочатку відображає сторінку «як є», але без повної інтерактивності.\\n\\n- Розбирає HTML, будує DOM і відображає контент.\\n\\n- Завантажує JS-бандли застосунку.\\n\\n- Виконує «оживлення» (гідратацію).\\n\\nВизначення: гідратація — процес, у якому клієнтський JavaScript «підхоплює» вже відрендерений HTML, зв'язує його з компонентами й додає обробники подій.\\n3) Чому SSR не дорівнює «усе готово»\\nSSR прискорює появу контенту, але інтерактивність з'являється, коли JS завантажиться.\\n\\n- До гідратації:\\n\\n- елементи видимі\\n\\n- обробники клацань/введення можуть не працювати або працювати частково (це залежить від фреймворку й режиму)\\n\\n- Після гідратації:\\n\\n- React/Next «зіставляє» наявний DOM із віртуальним деревом\\n\\n- підключаються події, стан та ефекти\\n\\n4) Мініприклад: ідея SSR + гідратації\\n\\n5) Практичне значення для фронтенду\\n\\n- Плюси:\\n\\n- контент з'являється швидше (перший показ)\\n\\n- він краще індексується (SEO)\\n\\n- Мінуси:\\n\\n- більше роботи на сервері\\n\\n- кешування й діагностика складніші\\n\\n- можливі помилки невідповідності, якщо сервер і клієнт рендерять по-різному\\n\\nВисновок: під час SSR HTML рендерить сервер. Потім браузер виконує гідратацію, щоб сторінка стала інтерактивною, і саме тому SSR зазвичай дає виграш у «першому показі», але не знімає потреби в клієнтському JS.\",\"// The server: generates the HTML out of the components (notionally)\\nconst html = renderToString(<App />); // An HTML string\\n// The client: \\\"brings the HTML to life\\\" (notionally)\\nhydrateRoot(document.getElementById('root'), <App />);\"],[2806,\"Серверний рендеринг дозволяє сформувати HTML на сервері й надіслати його браузерові вже готовим. Це прискорює перше завантаження сторінки й покращує SEO. Користувач бачить контент швидше. Такий підхід активно використовують у Next.js.\",\"За звичайного клієнтського рендерингу браузер спочатку завантажує JavaScript, а потім будує інтерфейс.\\nВизначення:\\nServer-Side Rendering (`SSR`) — це процес генерації HTML на сервері, перед тим як сторінку буде надіслано користувачеві.\\nЯк це працює\\n\\n- Користувач робить запит.\\n\\n- Сервер формує HTML.\\n\\n- Браузер отримує готову розмітку.\\n\\n- React виконує гідратацію.\\n\\nПриклад у Next.js\\n\\nПереваги\\n\\n- Швидкий перший показ.\\n\\n- Покращення SEO.\\n\\n- Підходить для динамічних сторінок.\\n\\nНедоліки\\n\\n- Навантаження на сервер.\\n\\n- Складніша архітектура.\\n\\nВисновок\\nSSR застосовують, коли мають значення швидкість першого завантаження й індексація сторінок пошуковими системами.\",\"export async function getServerSideProps() {\\n  return {\\n    props: { data: \\\"example\\\" }\\n  };\\n}\"],[2807,\"У Next.js динамічні маршрути створюють за допомогою файлів у квадратних дужках — наприклад, `[id].js`. Значення параметра можна отримати через `router.query` або через параметри функції завантаження даних. Такий підхід дозволяє створювати сторінки для різних сутностей — наприклад, користувачів або товарів. Маршрути формуються автоматично на основі структури файлів.\",\"Next.js використовує файлову систему, щоб визначати маршрути, включно з динамічними.\\nВизначення:\\nДинамічний маршрут — це маршрут, у якому частина URL є змінною й визначається під час виконання.\\nПриклад структури\\n\\nТакий файл обробляє маршрути вигляду:\\n\\nОтримання параметра\\n\\nАльтернативний варіант (SSR або SSG)\\n\\nКоли це використовують\\n\\n- Сторінки користувачів.\\n\\n- Сторінки товарів.\\n\\n- Детальні сторінки для контенту.\\n\\nВисновок\\nДинамічні маршрути в Next.js реалізовано через файлову систему, і вони дозволяють обробляти параметри URL автоматично.\",\"pages/\\n  users/\\n    [id].js\\n\\n/users/1\\n/users/25\\n\\nimport { useRouter } from \\\"next/router\\\";\\n\\nconst router = useRouter();\\nconst { id } = router.query;\\n\\nexport async function getServerSideProps(context) {\\n  const { id } = context.params;\\n  return { props: { id } };\\n}\"],[2808,\"У Next.js SSR роблять через серверний рендеринг сторінки: дані отримують на сервері, а клієнт отримує готовий HTML. Для SEO важливо, щоб ключовий контент і метадані (title, description, canonical, OG) були вже відрендерені на сервері. Залежно від задачі вибирають SSR, SSG або ISR, щоб збалансувати свіжість даних і швидкість. Для динамічних сторінок часто використовують SSR або ISR. Також важливо налаштувати robots/sitemap, коректні canonical і структуровані дані там, де це потрібно.\",\"У Next.js SEO зазвичай досягають не «магією», а правильним вибором режиму рендерингу й уважною роботою з метаданими.\\nВизначення\\nВизначення: SSR (Server-Side Rendering) — генерація HTML сторінки на сервері під час кожного запиту (або за стратегією), щоб користувач і пошукова система відразу отримували готову розмітку.\\nСтратегії рендерингу в Next.js і коли що вибирати\\n\\n- SSR\\n\\n- Потрібен для: персоналізації, даних, що часто змінюються, залежності від запиту\\n\\n- SSG\\n\\n- Потрібен для: статичних сторінок, максимальної швидкості, рідких змін\\n\\n- ISR\\n\\n- Потрібен для: «майже статичних», але таких, що періодично оновлюються без повного деплою\\n\\nРеалізація SSR (концептуально)\\n\\n- Дані завантажують на сервері\\n\\n- Сервер повертає HTML із контентом\\n\\n- Гідратація відбувається на клієнті (React «оживляє» сторінку)\\n\\nПриклад (pages router): SSR через `getServerSideProps`\\n\\nSEO-оптимізація: що потрібно робити\\n\\n- Метадані\\n\\n- `title`, `description`\\n\\n- `canonical`\\n\\n- Open Graph / Twitter cards (для попередніх переглядів)\\n\\n- Індексований контент\\n\\n- Важливі тексти й заголовки мусять бути в HTML у відповіді сервера\\n\\n- Швидкість\\n\\n- Правильний вибір SSR/SSG/ISR\\n\\n- Оптимізація зображень (next/image), мінімізація блокуючих ресурсів\\n\\n- Технічні файли\\n\\n- `robots.txt` і `sitemap.xml`\\n\\n- Семантика\\n\\n- Коректні `h1-h2`, списки, посилання, alt на зображеннях\\n\\nМетадані в Next.js (app router)\\n\\nТипові помилки, які ламають SEO\\n\\n- Контент з'являється лише після клієнтського fetch (порожній HTML на початку)\\n\\n- Однакові `title`/`description` для кожної сторінки\\n\\n- Немає `canonical` там, де URL дублюються (параметри/фільтри)\\n\\n- Рендеринг «усього в div» без семантики чи заголовків\\n\\nВисновок\\nДля SEO в Next.js ключове — віддати пошуковим системам готовий HTML із контентом і коректними метаданими; SSR/SSG/ISR вибирають за свіжістю даних і вимогами до швидкості.\",\"export async function getServerSideProps() {\\n  const res = await fetch(\\\"https://api.example.com/products\\\"); // an example\\n  const products = await res.json();\\n  return { props: { products } };\\n}\\n\\nexport const metadata = {\\n  title: \\\"A catalogue of products\\\",\\n  description: \\\"A selection of products with delivery\\\",\\n};\"],[2809,\"Серверні запити в Next.js — це запити до API або бази даних, які виконуються на сервері, перед тим як HTML буде надіслано клієнтові. Їх використовують, щоб відразу повернути користувачеві готову сторінку з даними. Такі запити недоступні з браузера й можуть безпечно використовувати секрети. В app router серверні запити зазвичай виконують прямо в серверних компонентах. Це покращує SEO й зменшує обсяг клієнтського JavaScript.\",\"У Next.js запити можна виконувати на різних етапах життєвого циклу сторінки, і серверні запити — ключовий механізм для SSR, SSG та ISR.\\nВизначення\\nВизначення: серверний запит — це запит даних, який виконується в середовищі Node.js (або на краю мережі), а не в браузері користувача.\\nДе виконуються серверні запити\\n\\n- SSR\\n\\n- Під час кожного HTTP-запиту від користувача\\n\\n- SSG\\n\\n- На етапі збирання\\n\\n- ISR\\n\\n- За таймером або під час револідації\\n\\n- Server Components (app router)\\n\\n- Коли компонент рендериться на сервері\\n\\nПриклад серверного запиту в app router\\n\\nВідмінності від клієнтських запитів\\n\\n- Серверні\\n\\n- Немає доступу з DevTools браузера\\n\\n- Можна використовувати ключі API\\n\\n- Дані відразу потрапляють у HTML\\n\\n- Клієнтські\\n\\n- Виконуються після завантаження сторінки\\n\\n- Видимі в мережі браузера\\n\\n- Часто погіршують SEO за неналежного використання\\n\\nПрактичні сценарії\\n\\n- Каталоги, статті, лендинги → серверні запити\\n\\n- Фільтри, інтерактивність, дії користувача → клієнтські запити\\n\\nВисновок\\nСерверні запити в Next.js застосовують для безпечного й дружнього до SEO завантаження даних, і вони є базовим інструментом серверного рендерингу.\",\"const products = await fetch(\\\"https://api.example.com/products\\\", {\\n  cache: \\\"no-store\\\" // switches the caching off\\n}).then(r => r.json());\"],[2810,\"Серверний рендеринг (SSR) генерує HTML на сервері й надсилає браузерові готову сторінку, що покращує SEO й час до першого показу. Клієнтський рендеринг (CSR) завантажує мінімальний HTML і JavaScript, який потім будує інтерфейс у браузері, забезпечуючи швидкі переходи після завантаження. Щоб узгодити їх, використовують гідратацію, коли React «оживляє отриманий від сервера статичний HTML». Вибір підходу залежить від вимог до SEO, швидкості завантаження й інтерактивності.\",\"Серверний рендеринг (SSR) і клієнтський рендеринг (CSR) — два фундаментальні підходи до відображення вебконтенту, кожен зі своїми компромісами. SSR означає, що сервер генерує повний HTML-документ для кожного запиту й надсилає його клієнтові. Це традиційний спосіб, який використовують у багатосторінкових застосунках. CSR, характерний для односторінкових застосунків (SPA), завантажує каркас сторінки й JavaScript-бандл, який потім динамічно рендерить інтерфейс у браузері, керуючи маршрутизацією й станом на стороні клієнта.\\n\\nКлючові відмінності й наслідки\\n\\n- SEO й індексація: пошукові боти легко сканують HTML, згенерований сервером (SSR). За CSR початковий HTML часто порожній, що ускладнює індексацію, хоча сучасні боти можуть виконувати JavaScript.\\n\\n- Відчутна продуктивність: SSR забезпечує швидке відображення першого контенту (FCP), оскільки користувач відразу бачить HTML. CSR може показувати індикатор завантаження, доки великий JS-бандл не завантажиться й не виконається.\\n\\n- Інтерактивність: після завантаження CSR забезпечує плавні, швидкі переходи без перезавантаження сторінки. За SSR кожна навігація вимагає нового запиту до сервера, хоча це можна оптимізувати.\\n\\n- Навантаження на сервер: SSR створює навантаження на сервер для кожного рендеру, що може вимагати масштабування. CSR переносить обчислювальне навантаження на клієнтські пристрої.\\n\\nСучасні гібридні підходи й гідратація\\n\\nФреймворки, як-от Next.js, пропонують гібридні моделі. Наприклад, можна використовувати статичну генерацію (SSG) для сторінок, які рідко змінюються, і SSR для динамічних даних. Ключовий процес — гідратація. Сервер надсилає заздалегідь відрендерений HTML. Потім завантажується той самий React-код JavaScript, який «підхоплює» (гідратує) цей DOM, зв'язуючи обробники подій і роблячи сторінку інтерактивною.\\n\\nПриклад коду з Next.js (App Router)\\n\\nУ цьому прикладі `HomePage` рендериться на сервері з даними, забезпечуючи добре SEO й швидке завантаження. Компонент `ClientCounter`, позначений директивою 'use client', гідратується на клієнті й додає інтерактивність.\\n\\nПрактичні рекомендації щодо обробки відмінностей\\n\\n- Використовуйте SSR або SSG для публічних, критичних для SEO сторінок (лендингів, блогів, каталогів).\\n\\n- Застосовуйте CSR для адмінпанелей або сильно інтерактивних частин застосунку, де SEO не має значення.\\n\\n- Для універсальних застосунків використовуйте фреймворки (Next.js, Nuxt, SvelteKit), які абстрагують складність, дозволяючи змішувати підходи.\\n\\n- Враховуйте «мерехтіння» під час гідратації: якщо початковий стан клієнта (наприклад, тема) не відповідає рендеру сервера, сторінка може блимнути. Рішення — синхронізація через скрипти або зберігання стану в cookie.\\n\\n- Уникайте безпосередніх маніпуляцій із DOM у компонентах, які можуть рендеритися на сервері; використовуйте хуки на кшталт `useEffect` або перевірку `typeof window !== 'undefined'`.\\n\\nВисновок: вибір між SSR і CSR — компроміс між швидкістю початкового завантаження, SEO й багатою інтерактивністю. Гібридні підходи з гідратацією, які надають сучасні метафреймворки, дозволяють отримати найкраще з обох світів: швидкий початковий рендер для SEO й подальшу плавну роботу SPA.\",\"// app/page.js — A server component by default in Next.js 13+\\nexport default async function HomePage() {\\n  // The data is requested on the server\\n  const data = await fetchData();\\n\\n  return (\\n    <div>\\n      <h1>The home page (SSR)</h1>\\n      <p>The data: {data.message}</p>\\n      {/* A client component for the interactivity */}\\n      <ClientCounter />\\n    </div>\\n  );\\n}\\n\\n// app/components/ClientCounter.js\\n'use client'; // Indicates that this is a client component\\nimport { useState } from 'react';\\n\\nexport default function ClientCounter() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <p>The counter: {count}</p>\\n      <button onClick={() => setCount(c => c + 1)}>Increase</button>\\n    </div>\\n  );\\n}\"],[2811,\"Гідрація стану — це процес передавання даних від сервера до клієнта, щоб уникнути повторних запитів. Сервер рендерить сторінку з початковими даними й вбудовує ці дані в HTML — наприклад, у тег `<script>`. На клієнті застосунок читає цей стан і використовує його як початковий замість того, щоб робити новий запит. Це прискорює перший показ і дозволяє уникнути мерехтіння інтерфейсу.\",\"Гідрація стану — ключова техніка в архітектурі сучасних вебзастосунків, особливо тих, що використовують серверний рендеринг (SSR) або статичну генерацію (SSG). Її мета — уникнути ситуації, у якій клієнтський застосунок, отримавши від сервера статичний HTML, змушений знову запитувати ті самі дані через API, що призводить до затримок і до мерехтіння інтерфейсу.\\n\\nЯк це працює\\n\\nПроцес можна розділити на кілька етапів:\\n\\n- Серверна підготовка: код застосунку виконується на сервері (наприклад, у React із Next.js або Nuxt.js для Vue). Застосунок запитує потрібні йому дані (з бази даних або API) і рендерить компоненти в HTML, використовуючи цей стан.\\n\\n- Вбудовування стану: отриманий стан (зазвичай об'єкт JavaScript) серіалізують у JSON-рядок і вбудовують безпосередньо в HTML-документ, який надсилають клієнтові. Найчастіше це роблять усередині тега `<script>` із певним ідентифікатором.\\n\\n- Клієнтська гідрація: браузер отримує HTML і відображає його (швидкий показ), потім завантажує JavaScript-бандл застосунку. Код застосунку «монтується» на вже наявну структуру DOM. На цьому етапі він читає вбудований стан із тега `<script>` і використовує його як початковий стан, замість того щоб ініціалізувати стан порожнім або робити новий запит.\\n\\nПрактичний приклад (Next.js із React)\\n\\nУ Next.js для цього часто використовують метод `getServerSideProps` або `getStaticProps`.\\n\\nНа клієнті фреймворк підхопить ці дані автоматично. В інших екосистемах (наприклад, Vue з Nuxt) принцип той самий, але реалізація може відрізнятися синтаксисом.\\n\\nДе і для чого це використовують\\n\\nЦей підхід критично важливий для:\\n\\n- Продуктивності: він знімає непотрібний мережевий запит, прискорюючи час до інтерактивності.\\n\\n- SEO: пошукові боти бачать повністю сформовану сторінку з її даними.\\n\\n- Користувацького досвіду: він виключає мерехтіння або стан завантаження під час переходів між сторінками SPA.\\n\\nВисновок: гідрацію стану варто застосовувати в будь-якому застосунку, де мають значення швидкість першого завантаження й SEO, особливо в інтернет-магазинах, медіасайтах і каталогах, де початкові дані відомі в момент рендеру сторінки.\",\"// The page pages/product/[id].js\\nexport async function getServerSideProps(context) {\\n  const { id } = context.params;\\n  // The data request on the server\\n  const res = await fetch(`https://api.example.com/products/${id}`);\\n  const product = await res.json();\\n\\n  // We return the props, which will reach the page\\n  return {\\n    props: {\\n      product // This state will be passed to the client\\n    },\\n  };\\n}\\n\\n// The page component will receive product as a prop\\nfunction ProductPage({ product }) {\\n  // On the client product is already available without a request\\n  return (\\n    <div>\\n      <h1>{product.name}</h1>\\n      <p>{product.description}</p>\\n    </div>\\n  );\\n}\\n\\n// Next.js serializes the `product` object automatically\\n// and inserts it into the HTML inside __NEXT_DATA__.\"],[2812,\"Next.js — це фреймворк на основі React, який додає серверний рендеринг (SSR), статичну генерацію (SSG), маршрутизацію на основі файлової системи й API-маршрути. На відміну від чистого React, який є лише клієнтською бібліотекою для UI, Next.js надає готову архітектуру для full-stack застосунків. Він полегшує SEO, покращує продуктивність завдяки завантаженню даних заздалегідь і автоматично оптимізує бандли.\",\"Призначення Next.js\\nNext.js — готовий до продакшну фреймворк для React, який розв'язує задачі, що лежать за межами клієнтської бібліотеки. Він надає вбудовані рішення для серверного рендерингу (SSR), статичної генерації (SSG), інкрементальної статичної регенерації (ISR), маршрутизації, оптимізації зображень і API-маршрутів. Це дозволяє створювати і повноцінні вебзастосунки з серверною логікою, і високопродуктивні статичні сайти.\\nКлючові відмінності від чистого React\\n\\n- Маршрутизація: у React використовують React Router, який працює на клієнті. Next.js використовує файлову систему, щоб визначати маршрути (pages/ або app/), що полегшує навігацію й підтримує динамічні шляхи.\\n- Рендеринг: React рендерить усе на клієнті (CSR). Next.js дозволяє вибирати між CSR, SSR, SSG та ISR для кожної сторінки, що покращує SEO й час завантаження.\\n- API-маршрути: Next.js дозволяє створювати серверні ендпоїнти всередині проєкту (pages/api), що знімає потребу в окремому бекенді для простих задач.\\n- Оптимізація: вбудована оптимізація зображень, шрифтів і скриптів, а також автоматичне розбиття коду — у React це вимагає додаткових бібліотек.\\nПриклад коду: сторінка з SSR у Next.js\\n\\nУ цьому прикладі дані завантажують на сервері, перед тим як HTML буде надіслано клієнтові, що покращує SEO й час до першого контенту (FCP). У чистому React довелося б використовувати useEffect і обробляти стан завантаження.\\nВисновок\\nNext.js варто застосовувати, коли потрібна SEO-оптимізація, швидке завантаження сторінок, вбудована серверна логіка або статична генерація контенту. Для простих односторінкових застосунків без потреби в SEO чистий React може бути легшим рішенням.\",\"// pages/posts/[id].js\\nexport async function getServerSideProps(context) {\\n  const { id } = context.params;\\n  const res = await fetch(`https://api.example.com/posts/${id}`);\\n  const post = await res.json();\\n  return { props: { post } };\\n}\\n\\nexport default function Post({ post }) {\\n  return <div><h1>{post.title}</h1><p>{post.body}</p></div>;\\n}\"],[2813,\"Маршрутизація в Next.js базується на файловій системі. Кожен файл у теках pages або app автоматично стає маршрутом. Наприклад, файл pages/about.js відповідає шляху /about. Динамічні маршрути підтримуються за допомогою квадратних дужок — наприклад, [id].js. У версії 13 з'явився App Router із підтримкою вкладених розкладок і серверних компонентів.\",\"Основи маршрутизації в Next.js\\nNext.js використовує файлову систему, щоб визначати маршрути. Це означає, що структура тек і файлів у каталогах `pages` (Pages Router) або `app` (App Router) безпосередньо відображається на URL застосунку. Такий підхід полегшує створення й підтримку навігації, оскільку розробникові не потрібно налаштовувати маршрути вручну.\\nPages Router (класичний підхід)\\nУ Pages Router кожен файл JavaScript або TypeScript у теці `pages` стає маршрутом. Наприклад:\\n\\nДинамічні сегменти позначають квадратними дужками — наприклад, `[id].js`. До параметрів звертаються через хук `useRouter` або через `getServerSideProps`.\\nApp Router (новий підхід із Next.js 13)\\nApp Router використовує теку `app` і підтримує вкладені розкладки, серверні компоненти й покращену продуктивність. Структура схожа, але додано спеціальні файли:\\n\\nФайл `layout.js` визначає обгортку для групи сторінок, що дозволяє повторно використовувати інтерфейс (наприклад, шапку й підвал).\\nПрактичний приклад\\nСтворимо простий блог із динамічними маршрутами:\\n\\nТепер URL `/blog/my-post` відобразить заголовок «Post: my-post», а `/blog` — список блога.\\nВисновок\\nФайлова маршрутизація Next.js прискорює розробку, роблячи навігацію інтуїтивною й передбачуваною. Вона особливо корисна для проєктів із чіткою ієрархією сторінок, як-от блогів, документації чи інтернет-магазинів.\",\"pages/\\n  index.js       -> /\\n  about.js       -> /about\\n  blog/\\n    index.js     -> /blog\\n    [slug].js    -> /blog/:slug\\n\\napp/\\n  page.js        -> /\\n  layout.js      -> the common layout for every child route\\n  about/\\n    page.js      -> /about\\n  blog/\\n    [slug]/\\n      page.js    -> /blog/:slug\\n\\n// app/blog/[slug]/page.js\\nexport default function BlogPost({ params }) {\\n  return <h1>Post: {params.slug}</h1>;\\n}\\n\\n// app/blog/page.js\\nexport default function BlogList() {\\n  return <h1>Blog list</h1>;\\n}\"],[2814,\"Waterfall-проблема виникає, коли запити даних виконуються послідовно, чекаючи завершення попереднього, що збільшує загальний час завантаження. У Next.js це часто трапляється під час використання async/await у getServerSideProps або в серверних компонентах без паралелізації. Щоб цього уникнути, незалежні запити потрібно запускати одночасно за допомогою Promise.all або паралельних викликів.\",\"Що таке waterfall-проблема?\\nWaterfall-проблема (або каскадна проблема) у Next.js виникає, коли кілька запитів даних виконуються послідовно, а не паралельно. Кожен наступний запит чекає завершення попереднього, що призводить до накопичення часу очікування. Це особливо критично на стороні сервера, де затримка кожного запиту збільшує час рендеру сторінки.\\nПриклад проблеми\\nРозглянемо типовий випадок у getServerSideProps:\\n\\nЗагальний час — 600 мс, хоча запити незалежні.\\nЯк цього уникнути\\nВикористовуйте Promise.all для паралельного виконання незалежних запитів:\\n\\nТепер усі три запити виконуються одночасно, і загальний час дорівнює найдовшому з них (200 мс).\\nДе це ще зустрічається\\nWaterfall може виникати в серверних компонентах React під час використання async/await усередині компонентів, які залежать один від одного. У таких випадках виносьте незалежні запити на верхній рівень або використовуйте Suspense для потокового завантаження.\\nВисновок: waterfall-проблема погіршує продуктивність Next.js-застосунків. Її уникають паралелізацією незалежних запитів через Promise.all або схожі механізми, що особливо важливо для серверного рендерингу й покращення користувацького досвіду.\",\"export async function getServerSideProps() {\\n  const user = await fetch('/api/user'); // 200ms\\n  const posts = await fetch('/api/posts'); // waits for user, another 200ms\\n  const comments = await fetch('/api/comments'); // waits for posts, another 200ms\\n  return { props: { user, posts, comments } };\\n}\\n\\nexport async function getServerSideProps() {\\n  const [user, posts, comments] = await Promise.all([\\n    fetch('/api/user'),\\n    fetch('/api/posts'),\\n    fetch('/api/comments')\\n  ]);\\n  return { props: { user, posts, comments } };\\n}\"],[2815,\"Серверні компоненти рендеряться на сервері, не потребують JavaScript на клієнті й не можуть використовувати хуки чи обробники подій. Клієнтські компоненти рендеряться на клієнті, підтримують інтерактивність і використовують хуки. Гідратація — це процес, у якому React додає інтерактивність до статичного HTML, надісланого із сервера, підключаючи обробники подій і стан.\",\"Основні відмінності між серверними й клієнтськими компонентами\\nУ Next.js App Router компоненти типово є серверними. Серверні компоненти виконуються на сервері, генерують статичний HTML і не надсилають JavaScript клієнтові. Вони ідеальні для відображення даних, які не потребують інтерактивності — наприклад, контенту з бази даних. Клієнтські компоненти, навпаки, виконуються в браузері й можуть використовувати хуки React (useState, useEffect), обробники подій і браузерні API.\\nЩо таке гідратація?\\nГідратація — це процес, у якому React бере статичний HTML, надісланий із сервера, і перетворює його на інтерактивний застосунок. React додає обробники подій, відновлює стан і підключає віртуальний DOM. Це дозволяє покращити продуктивність завантаження, оскільку користувач бачить контент, перш ніж JavaScript повністю завантажиться.\\nПриклад коду\\n\\nВисновок\\nВикористовуйте серверні компоненти для статичного контенту й даних, а клієнтські — для інтерактивних елементів. Гідратація автоматично робить серверний HTML інтерактивним, що покращує користувацький досвід і SEO.\",\"// A server component (the default)\\nexport default function ServerComponent() {\\n  const data = fetchDataFromDB(); // runs on the server\\n  return <div>{data}</div>;\\n}\\n\\n// A client component\\n'use client';\\nimport { useState } from 'react';\\nexport default function ClientComponent() {\\n  const [count, setCount] = useState(0);\\n  return <button onClick={() => setCount(count + 1)}>{count}</button>;\\n}\"],[2816,\"Гідратація — це процес, у якому React бере вже відрендерений на сервері HTML і «оживляє» його, підключаючи обробники подій і стан. Це дозволяє сторінці бути інтерактивною без повного перемалювання. У Next.js гідратація відбувається автоматично після завантаження JS-бандла.\",\"Що таке гідратація?\\nГідратація — ключовий механізм у React і Next.js, який зв'язує серверний рендеринг (SSR) із клієнтським. Коли сервер надсилає HTML-розмітку, вона вже містить увесь контент, але не є інтерактивною. Гідратація — це процес, у якому React «оживляє цю статичну розмітку», прив'язуючи до неї віртуальне дерево компонентів, стан і обробники подій.\\nЯк це працює?\\nУ Next.js під час першого запиту сервер генерує HTML і надсилає його клієнтові. Браузер миттєво відображає контент, що покращує SEO й час до першого байта. Потім завантажується JavaScript-бандл, і React виконує гідратацію: він зіставляє наявний DOM із віртуальним деревом і додає інтерактивність. Якщо розмітка збігається, React не перемальовує сторінку, а лише підключає слухачі подій.\\n\\nЧому це має значення?\\nГідратація дозволяє поєднати переваги SSR (швидкий перший відгук, SEO) із перевагами SPA (інтерактивність, плавні переходи). Без неї сторінка була б статичною; з нею — повноцінним застосунком. У Next.js гідратація автоматична, але важливо уникати розбіжностей між серверним і клієнтським рендерингом, інакше React може видавати попередження.\\nВисновок\\nГідратація — міст між серверним і клієнтським рендерингом. Вона необхідна для створення швидких, інтерактивних застосунків на Next.js. Розуміння цього процесу допомагає уникати помилок під час роботи з SSR і оптимізувати продуктивність.\",\"// An example: a component with useState\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n  return <button onClick={() => setCount(count + 1)}>{count}</button>\\n}\\n\\n// The server renders the HTML: <button>0</button>\\n// After the hydration React adds the onClick and the state\"],[2817,\"Клієнтські компоненти в Next.js рендеряться на сервері, щоб згенерувати початковий HTML, а потім гідратуються в браузері. Це означає, що їхня HTML-розмітка створюється на сервері, але інтерактивність і обробка подій працюють лише після завантаження JavaScript у браузері.\",\"Як працюють клієнтські компоненти в Next.js\\nУ Next.js клієнтські компоненти — це компоненти, позначені директивою `'use client'`. Вони беруть участь у серверному рендерингу: сервер генерує їхню HTML-розмітку, яку надсилають клієнтові. Це важливо для SEO й для швидкого початкового завантаження, оскільки користувач бачить контент, перш ніж виконається JavaScript.\\nПісля завантаження HTML у браузері Next.js виконує гідратацію: JavaScript-код компонента завантажується й прив'язується до наявної розмітки, додаючи інтерактивність (обробники подій, стан, ефекти). До гідратації клієнтський компонент відображається як статичний HTML.\\nПриклад\\n\\nЦей компонент рендериться на сервері як `<button>Count: 0</button>`, а потім стає інтерактивним у браузері.\\nВисновок\\nКлієнтські компоненти не виконуються лише в браузері — їх рендерять на сервері для початкового HTML, але їхня логіка й інтерактивність працюють виключно на клієнті. Таке поєднання забезпечує швидке завантаження й повноцінну взаємодію.\",\"// app/counter.tsx\\n'use client';\\nimport { useState } from 'react';\\n\\nexport default function Counter() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <button onClick={() => setCount(count + 1)}>\\n      Count: {count}\\n    </button>\\n  );\\n}\"],[2818,\"Якщо розмістити в кореневому layout багато клієнтських компонентів, увесь layout стане клієнтським. Це збільшить розмір JavaScript-бандла, вповільнить початкове завантаження й погіршить SEO, оскільки серверний рендеринг буде обмежений. Краще тримати layout серверним і переносити клієнтські компоненти ближче до місця їхнього використання.\",\"Що відбувається, коли 'use client' використовують у layout\\nУ Next.js (App Router) кореневий layout типово є серверним компонентом. Коли ви додаєте до нього клієнтські компоненти з директивою 'use client', увесь layout і всі його дочірні компоненти стають частиною клієнтського бандла. Це означає, що JavaScript для цих компонентів буде надіслано браузерові, збільшуючи розмір завантажуваного коду.\\nВплив на продуктивність\\nВелика кількість клієнтських компонентів у layout призводить до таких проблем:\\n\\n- Збільшення часу початкового завантаження (TTI) через більший обсяг JS.\\n- Зниження швидкості індексації пошуковими системами, оскільки частина контенту рендериться на клієнті.\\n- Ускладнення кешування й оптимізації на сервері.\\nПриклад\\n\\nЗамість цього краще залишити layout серверним і перенести клієнтські компоненти в конкретні сторінки або дочірні компоненти, де вони справді потрібні.\\nВисновок\\nВикористовуйте 'use client' лише там, де потрібна інтерактивність (обробники подій, хуки стану). Тримайте layout і статичні частини серверними, щоб мінімізувати бандл і покращити продуктивність.\",\"// app/layout.tsx\\nimport ClientComponent from './ClientComponent';\\n\\nexport default function RootLayout({ children }) {\\n  return (\\n    <html>\\n      <body>\\n        <ClientComponent /> {/* makes the layout a client one */}\\n        {children}\\n      </body>\\n    </html>\\n  );\\n}\"],[2819,\"Так, такі ситуації бувають. Якщо застосунок — це внутрішній інструмент, адмінпанель або дашборд із закритим доступом, де SEO не має значення, а користувачі вже авторизовані, звичайне SPA на React буде простішим і дешевшим. Next.js додає складності з серверним рендерингом, розгортанням і налаштуванням, що не виправдано без публічного контенту й вимог до швидкості першого завантаження.\",\"Коли Next.js надмірний\\nNext.js — фреймворк на основі React, який додає серверний рендеринг (SSR), статичну генерацію (SSG) та інші можливості. Проте ці функції потрібні не завжди. Якщо ваш застосунок — внутрішня панель керування, аналітичний дашборд або інструмент для працівників, де доступ обмежено авторизацією, пошукові системи не індексують сторінки, а користувачі не залежать від SEO. У такому разі класичне SPA на React із Create React App або Vite буде простішим: менше залежностей, швидше збирання, простіший деплой на статичний хостинг.\\nКлючові критерії вибору\\n\\n- Публічний контент і SEO — Next.js потрібен.\\n- Висока швидкість першого завантаження для маркетингових сторінок — корисний SSG.\\n- Дані, що часто оновлюються, і динаміка — SPA може бути зручнішим.\\n- Команда й інфраструктура — якщо немає досвіду з серверним кодом, SPA знижує поріг входу.\\nПриклад: коли SPA достатньо\\n\\nТут немає потреби в SSR, оскільки дані приходять після входу, а SEO не потрібне. Такий застосунок можна розгорнути на Netlify або Vercel як статичні файли.\\nВисновок\\nВикористовуйте Next.js, коли потрібні SEO, швидка доставка публічного контенту або ізоморфні застосунки. Для внутрішніх інструментів, адмінпанелей і застосунків із закритим доступом звичайне SPA на React — раціональніший вибір: його простіше розробляти й підтримувати.\",\"// A React SPA (Vite) - a simple application for internal use\\nimport React, { useState } from 'react';\\n\\nfunction Dashboard() {\\n  const [data, setData] = useState([]);\\n  // loading the data from the API after the authorization\\n  return <div>The control panel</div>;\\n}\\n\\nexport default Dashboard;\"],[2820,\"У Next.js дані можна завантажувати на сервері в Server Components, використовуючи async/await, або на клієнті в Client Components за допомогою хука useEffect чи бібліотек. Для кешування застосовують fetch з опціями cache і next.revalidate, а також статичну генерацію (SSG) та інкрементальну регенерацію (ISR).\",\"У Next.js завантаження даних залежить від того, де виконується код: на сервері чи на клієнті. Server Components виконуються лише на сервері, що дозволяє звертатися до баз даних або API напряму без додаткових шарів. Client Components працюють у браузері й вимагають інших підходів — наприклад, використання хуків або бібліотек для керування станом.\\nЗавантаження даних у серверних компонентах\\nУ Server Components можна використовувати async-функції й await, щоб отримати дані. Це спрощує код, оскільки немає потреби обробляти стани завантаження й помилок на клієнті. Приклад:\\n\\nТипово fetch у Next.js кешує результати, що прискорює повторні запити. Кешуванням можна керувати за допомогою опцій.\\nЗавантаження даних у клієнтських компонентах\\nДля Client Components, які позначають директивою 'use client', завантаження даних зазвичай відбувається в useEffect або за допомогою бібліотек, як-от SWR чи TanStack Query. Це потрібно, коли дані залежать від дій користувача або вимагають інтерактивності.\\n\\nСтратегії кешування\\nNext.js пропонує кілька стратегій кешування для оптимізації продуктивності:\\n\\n- Статична генерація (SSG) — дані завантажують один раз під час збирання й кешують. Підходить для контенту, який рідко змінюється.\\n- Інкрементальна статична регенерація (ISR) — дозволяє оновлювати статичні сторінки у фоні через заданий інтервал часу, використовуючи опцію `next: { revalidate: 60 }`.\\n- Динамічне завантаження — якщо дані мусять бути свіжими завжди, кешування можна вимкнути, задавши `cache: 'no-store'` у fetch.\\nПриклад використання ISR:\\n\\nВибір стратегії залежить від частоти оновлення даних і вимог до їхньої актуальності. Для статичного контенту краще використовувати SSG; для даних, що часто змінюються, — динамічне завантаження або ISR.\\nПідсумовуючи: розуміння відмінностей між серверними й клієнтськими компонентами та вміння застосовувати стратегії кешування дозволяють створювати швидкі, масштабовані застосунки на Next.js, мінімізуючи навантаження на сервер і покращуючи користувацький досвід.\",\"// app/page.tsx (a Server Component)\\nexport default async function Page() {\\n  const res = await fetch('https://api.example.com/data');\\n  const data = await res.json();\\n  return <div>{data.title}</div>;\\n}\\n\\n// app/dashboard.tsx (a Client Component)\\n'use client';\\nimport { useEffect, useState } from 'react';\\n\\nexport default function Dashboard() {\\n  const [data, setData] = useState(null);\\n  useEffect(() => {\\n    fetch('/api/dashboard')\\n      .then(res => res.json())\\n      .then(setData);\\n  }, []);\\n  return <div>{data?.message}</div>;\\n}\\n\\nconst res = await fetch('https://api.example.com/posts', {\\n  next: { revalidate: 60 } // update every 60 seconds\\n});\"],[2821,\"Redux допомагає керувати станом застосунку, зберігаючи його в одному місці (глобальному сховищі). Він працює з React через контекст і провайдери, даючи компонентам доступ до спільного стану. React-Redux полегшує використання Redux у React, надаючи хуки на кшталт `useSelector` і `useDispatch`.\",\"Redux — бібліотека, щоб керувати станом, яку спроєктували, аби полегшити роботу зі станом у складних застосунках. Вона пропонує єдине місце, у якому зберігають стан (глобальне сховище), що полегшує передавання даних між компонентами, не прокидаючи їх через безліч рівнів.\\nRedux складається з трьох ключових елементів:\\n\\n- Сховище: це об'єкт, який містить увесь стан застосунку.\\n\\n- Actions: це об'єкти, які описують, що має змінитися у стані. Вони завжди містять тип дії (`type`) й можуть містити додаткові дані (`payload`).\\n\\n- Редюсери: це функції, які приймають поточний стан й action і повертають новий стан.\\n\\nВін інтегрується з React через бібліотеку React-Redux, яка надає:\\n\\n- `Provider`: компонент, який робить сховище доступним усьому дереву React-компонентів.\\n\\n- Хуки `useSelector` й `useDispatch`: щоб отримувати дані зі стану й щоб надсилати actions відповідно.\\n\\nПриклад:\\n\\nRedux корисний у великих застосунках із безліччю частин стану, які треба синхронізувати між компонентами. Однак для малих проєктів він може бути надмірно складним. Альтернативи на кшталт React Context або Zustand можуть бути простішими в деяких випадках.\",\"// The action\\nconst increment = { type: 'INCREMENT' };\\n// The reducer\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n}\\n// Creating the store\\nimport { createStore } from 'redux';\\nconst store = createStore(counterReducer);\\n// The React component\\nimport React from 'react';\\nimport { Provider, useSelector, useDispatch } from 'react-redux';\\nfunction Counter() {\\n  const count = useSelector((state) => state);\\n  const dispatch = useDispatch();\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => dispatch(increment)}>Increment</button>\\n    </div>\\n  );\\n}\\nfunction App() {\\n  return (\\n    <Provider store={store}>\\n      <Counter />\\n    </Provider>\\n  );\\n}\"],[2822,\"Ключові принципи Redux:\\n\\n- Єдине сховище: увесь стан зберігають в одному об'єкті.\\n\\n- Стан лише для читання: стан можна змінити лише через actions.\\n\\n- Зміни роблять чисті функції: редюсери — чисті функції, які приймають поточний стан й action і повертають новий стан.\",\"Redux засновано на трьох ключових принципах:\\n\\n- Єдине джерело істини:\\nУвесь стан застосунку зберігають в одному об'єкті, який називають сховищем. Це полегшує зневадження, адже всі дані застосунку в одному місці. Наприклад:\\n\\n- Стан лише для читання:\\nСтан не можна змінювати напряму. Замість цього створюють actions, які описують зміни. Це робить зміни передбачуваними й легкими для відстежування. Наприклад:\\n\\n- Зміни роблять чисті функції:\\nЩоб обробляти actions і змінювати стан, використовують редюсери — функції, які не мають побічних ефектів і завжди повертають те саме значення для тих самих вхідних даних. Приклад редюсера:\\n\\nЦі принципи роблять Redux передбачуваним і зручним задля роботи в команді. Наприклад, якщо застосунок поводиться некоректно, ви можете легко відстежити, який action спричинив зміни, й відновити попередній стан.\",\"const store = {\\n  user: { name: 'Alice', loggedIn: true },\\n  cart: [{ id: 1, name: 'Item A', quantity: 2 }]\\n};\\n\\nconst action = { type: 'ADD_ITEM', payload: { id: 2, name: 'Item B' } };\\n\\nfunction cartReducer(state = [], action) {\\n  switch (action.type) {\\n    case 'ADD_ITEM':\\n      return [...state, action.payload];\\n    default:\\n      return state;\\n  }\\n}\"],[2823,\"Redux зручний, щоб працювати з глобальним станом у великих застосунках, де дані мають бути доступні в різних частинах дерева компонентів. Він полегшує керування станом, усуває «прокидання пропсів» і робить зміни передбачуваними. Локальний стан компонентів простіший, але його важко масштабувати, якщо дані потрібні в кількох місцях застосунку.\",\"Redux має кілька переваг порівняно з локальним станом, особливо у складних застосунках:\\n\\n- Єдине джерело істини:\\nУ Redux увесь стан застосунку зберігають в одному місці. Це полегшує зневадження, адже ви можете швидко зрозуміти, як стан змінюється, переглянувши actions і редюсери. Натомість локальний стан зберігають окремо в кожному компоненті, що робить керування даними складнішим.\\n\\n- Усунення прокидання пропсів:\\nКоли дані треба передати через кілька рівнів компонентів, це спричиняє труднощі. Redux дає компонентам змогу отримувати потрібний їм стан напряму через `useSelector` або `connect`, не прокидаючи пропси через проміжні рівні.\\n\\n- Підтримка передбачуваності:\\nRedux робить зміни стану передбачуваними завдяки принципу немутабельності й зрозумілій структурі (actions -> редюсери -> новий стан). Локальний стан можна змінити напряму, що ускладнює відстежування джерела зміни.\\n\\n- Інструменти задля зневадження:\\nRedux DevTools дають змогу легко відстежувати, які actions відбулися, й повертатися до попереднього стану, що значно полегшує розробку.\\n\\nПриклад порівняння:\\n\\nRedux особливо корисний у великих застосунках із багатокомпонентними залежностями. Але в простих застосунках локальний стан може бути зручнішим і не потребувати додаткового налаштування.\",\"// Local state\\nfunction ParentComponent() {\\n  const [data, setData] = useState(\\\"Initial Data\\\");\\n  return <ChildComponent data={data} setData={setData} />;\\n}\\n// Redux\\nimport { useSelector, useDispatch } from 'react-redux';\\nfunction Component() {\\n  const data = useSelector((state) => state.data);\\n  const dispatch = useDispatch();\\n  return (\\n    <div>\\n      <p>{data}</p>\\n      <button onClick={() => dispatch({ type: \\\"UPDATE_DATA\\\", payload: \\\"New Data\\\" })}>\\n        Update Data\\n      </button>\\n    </div>\\n  );\\n}\"],[2824,\"Немутабельність означає, що стан Redux ніколи не змінюють напряму — замість цього створюють новий стан. Це дає змогу легко відстежувати зміни, оглядати попередні версії даних й уникати помилок, пов'язаних із неочікуваними модифікаціями стану\",\"Немутабельність — ключовий принцип Redux, який передбачає, що стан не можна змінювати напряму. Замість цього, коли дані оновлюють, створюють новий об'єкт стану. Це має кілька переваг:\\n\\n- Передбачуваність:\\nЯкщо стан залишається незмінним, зміни завжди відбуваються однаково — через редюсери. Це полегшує тестування й зневадження.\\n\\n- Історія змін:\\nЗавдяки немутабельності ви можете легко зберігати попередні стани й повертатися до них, що використовують, наприклад, у Redux DevTools.\\n\\n- Уникання неочікуваних змін:\\nКоли стан змінюють напряму, це може призводити до помилок, які важко виявити. Наприклад, у роботі з посилальним типом (об'єктами або масивами) зміна стану в одному місці може випадково зачепити інше місце. Немутабельність усуває цю проблему.\\n\\nПриклад:\\n\\nRedux використовує бібліотеку Immer, щоб полегшити роботу з немутабельністю, яка дає змогу писати код у «мутабельному» стилі, зберігаючи немутабельність:\\n\\nНемутабельність робить Redux потужним інструментом для масштабованих застосунків, адже вона дає змогу тримати контроль над станом й уникати неочікуваних побічних ефектів.\",\"// A violation of the principle of immutability\\nfunction reducer(state = { count: 0 }, action) {\\n  if (action.type === 'INCREMENT') {\\n    state.count++; // Changing the original object\\n    return state;  // Wrong\\n  }\\n  return state;\\n}\\n// Observing the principle of immutability\\nfunction reducer(state = { count: 0 }, action) {\\n  if (action.type === 'INCREMENT') {\\n    return { ...state, count: state.count + 1 }; // Creating a new object\\n  }\\n  return state;\\n}\\n\\nimport produce from 'immer';\\nconst reducer = produce((draft, action) => {\\n  if (action.type === 'INCREMENT') {\\n    draft.count++;\\n  }\\n});\"],[2825,\"Чисті функції — функції, які завжди повертають те саме значення для тих самих вхідних даних і не мають побічних ефектів. У Redux редюсери мають бути чистими функціями, щоб зміни стану були передбачуваними й легкими задля тестування.\",\"Чисті функції — функції, які задовольняють два основні критерії:\\n\\n- Детермінованість: для тих самих вхідних даних результат завжди однаковий.\\n\\n- Відсутність побічних ефектів: функція не змінює зовнішніх даних і не викликає зовнішніх дій, як-от запитів до API або змін DOM.\\n\\nУ Redux редюсери — чисті функції, які відповідають за оновлення стану застосунку. Вони приймають поточний стан й action і повертають новий стан, не змінюючи наявного. Це дає змогу:\\n\\n- Гарантувати передбачуваність змін стану.\\n\\n- Легко тестувати редюсери, перевіряючи, що для заданого входу вони завжди повертають очікуваний вихід.\\n\\n- Працювати з інструментами на кшталт Redux DevTools, щоб відстежувати й відтворювати зміни стану.\\n\\nПриклад:\\n\\nЧистота редюсерів полегшує роботу в командній розробці й допомагає дотримуватися основних принципів Redux. Наприклад, побічні ефекти (як-от запити до API) виносять у middleware — наприклад, `redux-thunk` або `redux-saga`.\",\"// A pure function: predictable behaviour and no side effects\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    case 'DECREMENT':\\n      return state - 1;\\n    default:\\n      return state;\\n  }\\n}\\n// An impure function: causes side effects\\nfunction impureReducer(state = 0, action) {\\n  if (action.type === 'INCREMENT') {\\n    console.log('Incrementing count'); // A side effect\\n    return state + 1;\\n  }\\n  return state;\\n}\"],[2826,\"Потік даних у Redux однонапрямлений. Компоненти надсилають actions, які передають у редюсери через сховище. Редюсери оновлюють стан, а компоненти отримують оновлення через свої підписки.\",\"Потік даних у Redux являє собою однонапрямлену архітектуру, що робить його простим і передбачуваним. Ось типовий цикл:\\n\\n- Action:\\nКомпонент ініціює action — об'єкт, який описує, що має відбутися. Наприклад:\\n\\n- Надсилання action:\\nAction передають у сховище за допомогою методу `dispatch`:\\n\\n- Редюсер:\\nСховище передає action у редюсери, які приймають поточний стан й action і повертають новий стан:\\n\\n- Оновлення стану:\\nСховище зберігає новий стан і сповіщає підписані компоненти, що він змінився.\\n\\n- Відображення в компоненті:\\nКомпоненти, підписані на стан через `useSelector` або `connect`, отримують нове значення й перемальовуються:\\n\\nПриклад повного циклу:\\n\\nТака однонапрямлена структура полегшує розуміння потоку даних і дає змогу уникати заплутаних взаємозв'язків між компонентами. Це також робить Redux зручним задля роботи у великих командах.\",\"const incrementAction = { type: 'INCREMENT' };\\n\\nstore.dispatch(incrementAction);\\n\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n}\\n\\nconst count = useSelector((state) => state.count);\\n\\nimport { createStore } from 'redux';\\nimport { Provider, useDispatch, useSelector } from 'react-redux';\\n// The reducer\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    case 'DECREMENT':\\n      return state - 1;\\n    default:\\n      return state;\\n  }\\n}\\n// The store\\nconst store = createStore(counterReducer);\\n// The components\\nfunction Counter() {\\n  const count = useSelector((state) => state);\\n  const dispatch = useDispatch();\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => dispatch({ type: 'INCREMENT' })}>Increment</button>\\n      <button onClick={() => dispatch({ type: 'DECREMENT' })}>Decrement</button>\\n    </div>\\n  );\\n}\\n// The application\\nfunction App() {\\n  return (\\n    <Provider store={store}>\\n      <Counter />\\n    </Provider>\\n  );\\n}\"],[2827,\"`connect` пов'язує React-компоненти зі станом й actions Redux. Він приймає дві функції: `mapStateToProps`, щоб під'єднати стан, й `mapDispatchToProps`, щоб передати actions у компонент. У результаті компонент отримує доступ до потрібних йому даних і до змоги змінювати стан.\",\"Функція `connect` із бібліотеки React Redux — HOC (Higher-Order Component), який пов'язує компонент зі сховищем Redux. Вона дає змогу передати стан й actions Redux у компонент через пропси.\\n`connect` приймає два основні параметри:\\n\\n- `mapStateToProps`:\\nЦе функція, яка визначає, які дані зі стану Redux треба передати в компонент. Вона приймає поточний стан сховища як свій аргумент і повертає об'єкт, який додадуть до пропсів компонента.\\n\\n- `mapDispatchToProps`:\\nЦе функція, яка передає в компонент методи, щоб надсилати actions (`dispatch`). Вона може бути функцією або об'єктом:\\n\\nПриклад використання:\\n\\nУ сучасному React частіше використовують хуки `useSelector` й `useDispatch`, які виконують ті самі функції, що й `connect`, але через функційні компоненти. Проте `connect` залишається корисним, особливо в класових компонентах.\",\"const mapStateToProps = (state) => ({\\n  count: state.counter\\n});\\n\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' }),\\n});\\n\\nimport React from 'react';\\nimport { connect } from 'react-redux';\\nfunction Counter({ count, increment }) {\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={increment}>Increment</button>\\n    </div>\\n  );\\n}\\nconst mapStateToProps = (state) => ({\\n  count: state.counter,\\n});\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' }),\\n});\\nexport default connect(mapStateToProps, mapDispatchToProps)(Counter);\"],[2828,\"`dispatch` — функція, яка надсилає actions у сховище Redux. Ці actions обробляють редюсери, які оновлюють стан. `dispatch` використовують, щоб взаємодіяти з глобальним станом і спричиняти зміни.\",\"`dispatch` — центральний метод у Redux, який дає змогу ініціювати зміни стану. Він приймає об'єкт action і передає його у сховище, де редюсери обробляють цей action і повертають оновлений стан.\\nПриклад action:\\n\\nКоли `dispatch` викликають, відбувається таке:\\n\\n- Action передають у сховище.\\n\\n- Сховище надсилає action кожному редюсерові.\\n\\n- Редюсери оновлюють стан на основі типу action.\\n\\n- Компоненти, підписані на сховище, отримують оновлений стан і перемальовуються.\\n\\nУ React Redux `dispatch` можна використовувати напряму через хук `useDispatch`:\\n\\nАбо через функцію `mapDispatchToProps` із `connect`:\\n\\n`dispatch` також підтримує middleware на кшталт `redux-thunk` або `redux-saga`, що дає змогу надсилати асинхронні actions (наприклад, запити до API) або обробляти складні ланцюжки actions. Це робить `dispatch` універсальним інструментом, щоб керувати станом застосунку.\",\"const incrementAction = { type: 'INCREMENT' };\\nstore.dispatch(incrementAction);\\n\\nimport { useDispatch } from 'react-redux';\\nfunction Counter() {\\n  const dispatch = useDispatch();\\n  return (\\n    <button onClick={() => dispatch({ type: 'INCREMENT' })}>\\n      Increment\\n    </button>\\n  );\\n}\\n\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' }),\\n});\"],[2829,\"Компоненти-контейнери — React-компоненти, які під'єднуються до сховища Redux, щоб керувати станом. Вони отримують дані зі стану через `mapStateToProps` і передають actions через `mapDispatchToProps`. У результаті вони працюють як посередники між Redux і презентаційними компонентами.\",\"Концепція компонентів-контейнерів у React Redux заснована на поділі відповідальності:\\n\\n- Контейнери зосереджені на під'єднанні до сховища Redux. Вони отримують дані з глобального стану й передають їх своїм дочірнім компонентам.\\n\\n- Презентаційні компоненти відповідають за відображення даних і не взаємодіють із Redux напряму. Вони отримують дані через пропси й викликають функції, щоб надсилати actions.\\n\\nКонтейнери часто створюють за допомогою функції `connect`, яка пов'язує компонент зі станом й actions. Приклад:\\n\\nКонтейнери полегшують повторне використання логіки, адже вони ізолюють роботу з Redux. У сучасному React популярні хуки `useSelector` й `useDispatch`, які виконують ту саму задачу, але знімають потребу створювати окремі контейнери:\\n\\nОтже, компоненти-контейнери зручні, щоб керувати станом, але їхня концепція стає менш актуальною завдяки сучасним хукам.\",\"import React from 'react';\\nimport { connect } from 'react-redux';\\nfunction Counter({ count, increment }) {\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={increment}>Increment</button>\\n    </div>\\n  );\\n}\\n// Linking with the state and the actions\\nconst mapStateToProps = (state) => ({ count: state.counter });\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' }),\\n});\\n// Exporting the container\\nexport default connect(mapStateToProps, mapDispatchToProps)(Counter);\\n\\nimport React from 'react';\\nimport { useSelector, useDispatch } from 'react-redux';\\nfunction Counter() {\\n  const count = useSelector((state) => state.counter);\\n  const dispatch = useDispatch();\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => dispatch({ type: 'INCREMENT' })}>Increment</button>\\n    </div>\\n  );\\n}\"],[2830,\"У Redux actions описують, що має відбутися, редюсери визначають, як стан змінюється у відповідь на actions, а сховище керує всім станом застосунку. Ці три елементи працюють разом, щоб підтримувати передбачуваний потік даних.\",\"Redux побудовано на трьох основних елементах: actions, редюсерах і сховищі. Кожний із них виконує власну унікальну роль.\\nActions:\\nAction — об'єкт, який описує, що має відбутися в застосунку. Він завжди містить поле `type` (тип action), яке визначає, яку операцію треба виконати. Action також може містити додаткові дані (`payload`):\\n\\nРедюсери:\\nРедюсер — чиста функція, яка приймає поточний стан й action і повертає новий стан. Він оновлює лише ту частину стану, за яку відповідає:\\n\\nСховище:\\nСховище керує станом усього застосунку. Його створюють за допомогою функції `createStore`, яка приймає редюсери й повертає об'єкт із методами, щоб працювати зі станом:\\n\\nПотік даних у Redux виглядає так:\\n\\n- Компонент надсилає action через `dispatch`.\\n\\n- Action передають редюсерам через сховище.\\n\\n- Редюсери повертають оновлений стан.\\n\\n- Сховище сповіщає підписані компоненти про нові дані.\\n\\nПриклад повного циклу:\\n\\nСпільна робота actions, редюсерів і сховища забезпечує зрозумілу архітектуру й передбачуваність змін стану в застосунку. Це робить Redux потужним інструментом, щоб керувати станом у великих застосунках.\",\"const incrementAction = { type: 'INCREMENT' };\\nconst addTodoAction = { type: 'ADD_TODO', payload: { text: 'Learn Redux' } };\\n\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n}\\n\\nimport { createStore } from 'redux';\\n\\nconst store = createStore(counterReducer);\\nconsole.log(store.getState()); // Obtaining the current state\\nstore.dispatch({ type: 'INCREMENT' }); // Dispatching an action\\n\\n// The reducer\\nfunction todoReducer(state = [], action) {\\n  switch (action.type) {\\n    case 'ADD_TODO':\\n      return [...state, action.payload];\\n    default:\\n      return state;\\n  }\\n}\\n// The store\\nconst store = createStore(todoReducer);\\n// Dispatching the action\\nstore.dispatch({ type: 'ADD_TODO', payload: { text: 'Learn Redux' } });\\nconsole.log(store.getState()); // [{ text: 'Learn Redux' }]\"],[2831,\"Actions у Redux — звичайні JavaScript-об'єкти, які описують, що має відбутися в застосунку. Вони обов'язково містять поле `type`, яке визначає тип action, і можуть включати додаткові дані в полі `payload`. Actions використовують, щоб ініціювати зміни стану через редюсери.\",\"Actions — ключові елементи в Redux, які описують намір змінити стан застосунку. Їх передають через функцію `dispatch`, а обробляють редюсери.\\nМінімальна структура action:\\n\\n`type`: поле `type` обов'язкове; воно визначає тип action і повідомляє редюсерам, як обробити цей action.\\n`payload`: додаткові дані, які передають разом із action. Це можуть бути параметри, значення або інші особливості, потрібні, щоб оновити стан.\\n\\nПриклад використання action:\\nНадсилання action:\\n\\nРедюсер обробляє цей action:\\n\\nЩоб полегшити роботу з actions, часто створюють action creators — функції, які повертають об'єкт action:\\n\\nActions забезпечують однаковий спосіб описувати події, що робить код передбачуваним і легким задля тестування.\",\"const action = { type: 'INCREMENT' };\\n\\nconst addTodoAction = {\\n  type: 'ADD_TODO',\\n  payload: { text: 'Learn Redux', completed: false },\\n};\\n\\nstore.dispatch({ type: 'INCREMENT' });\\n\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n}\\n\\nconst increment = () => ({ type: 'INCREMENT' });\\nconst addTodo = (text) => ({\\n  type: 'ADD_TODO',\\n  payload: { text, completed: false },\\n});\\nstore.dispatch(increment());\\nstore.dispatch(addTodo('Learn Redux'));\"],[2832,\"Сховище в Redux керує станом усього застосунку. Воно надає методи, щоб отримати поточний стан (`getState`), надіслати actions (`dispatch`) і підписатися на зміни (`subscribe`). Сховище пов'язує редюсери з actions, щоб оновлювати стан.\",\"Сховище — об'єкт, який містить стан усього застосунку й надає API, щоб працювати з цим станом. Його створюють за допомогою функції `createStore`, і воно приймає редюсер як свій аргумент.\\nОсновні методи сховища:\\n\\n- `getState`:\\nПовертає поточний стан застосунку.\\n\\n- `dispatch`:\\nВикористовують, щоб надсилати actions. Після того як `dispatch` викликали, редюсери обробляють action і повертають оновлений стан.\\n\\n- `subscribe`:\\nДає змогу підписатися на зміни стану. Щоразу, коли стан оновлюють, викликають передану функцію.\\n\\nПриклад повного використання сховища:\\n\\nСховище забезпечує:\\n\\n- Централізований стан: усі дані зберігають в одному місці.\\n\\n- Передбачуваність: зміни стану відбуваються лише через actions і редюсери.\\n\\n- Змогу відстежувати: завдяки методу `subscribe` й інструментам на кшталт Redux DevTools.\\n\\nРобота сховища дає змогу керувати станом ефективно, навіть у великих застосунках із численними компонентами.\",\"const state = store.getState();\\nconsole.log(state);\\n\\nstore.dispatch({ type: 'INCREMENT' });\\n\\nconst unsubscribe = store.subscribe(() => {\\n  console.log('State updated:', store.getState());\\n});\\n// To cancel the subscription:\\nunsubscribe();\\n\\nimport { createStore } from 'redux';\\n// The reducer\\nfunction counterReducer(state = 0, action) {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    case 'DECREMENT':\\n      return state - 1;\\n    default:\\n      return state;\\n  }\\n}\\n// Creating the store\\nconst store = createStore(counterReducer);\\n// Subscribing to the changes\\nstore.subscribe(() => {\\n  console.log('The current state:', store.getState());\\n});\\n// Dispatching the actions\\nstore.dispatch({ type: 'INCREMENT' });\\nstore.dispatch({ type: 'DECREMENT' });\"],[2833,\"Middleware в Redux — функції, які обгортають метод `dispatch`, додаючи до нього додаткову поведінку. Їх використовують, щоб працювати з асинхронними операціями, журналювати, обробляти помилки й задля інших задач. Приклади популярних middleware — `redux-thunk` і `redux-saga`.\",\"Middleware в Redux діє як шар між надсиланням action (`dispatch`) й його обробкою в редюсері. Воно перехоплює кожний action, даючи змогу виконати додаткову логіку, перш ніж action дійде до редюсера. Це корисно, щоб:\\n\\n- Обробляти асинхронні операції (наприклад, запити до API).\\n\\n- Журналювати actions задля зневадження.\\n\\n- Обробляти побічні ефекти.\\n\\n- Валідувати дані або модифікувати actions.\\n\\nПриклад стандартного middleware:\\n\\nПід'єднання middleware до сховища роблять через функцію `applyMiddleware`:\\n\\nПопулярні приклади middleware:\\n\\n- `redux-thunk`: дає змогу надсилати функції, а не об'єкти, щоб працювати з асинхронним кодом.\\n\\n- `redux-saga`: використовує генератори, щоб керувати складними потоками асинхронних операцій.\\n\\n- Логери: показують послідовність actions і зміни стану.\\n\\nMiddleware робить Redux потужним інструментом задля роботи з реальними проєктами, додаючи гнучкість і даючи змогу легко обробляти складні сценарії.\",\"const loggerMiddleware = (store) => (next) => (action) => {\\n  console.log('Dispatching:', action);\\n  const result = next(action); // Passing the action further on\\n  console.log('Next state:', store.getState());\\n  return result;\\n};\\n\\nimport { createStore, applyMiddleware } from 'redux';\\n// A simple reducer\\nconst reducer = (state = {}, action) => state;\\n// Creating the store with the middleware\\nconst store = createStore(reducer, applyMiddleware(loggerMiddleware));\\n// An example of an action\\nstore.dispatch({ type: 'TEST_ACTION' });\"],[2834,\"`redux-thunk` — middleware, яке дає змогу надсилати в Redux функції, а не об'єкти. Такі функції можуть виконувати асинхронний код — наприклад, запити до API — а потім надсилати звичайні actions із результатами цих операцій. Це корисно, щоб керувати станом, який залежить від зовнішніх даних.\",\"За замовчуванням Redux працює лише із синхронними actions, які є звичайними об'єктами. Однак у реальних застосунках часто доводиться виконувати асинхронні операції, як-от запити до сервера. Задля цього використовують `redux-thunk`.\\nЯк працює redux-thunk?\\n\\n- `redux-thunk` перехоплює actions, надіслані через `dispatch`.\\n\\n- Якщо action — функція, middleware викликає цю функцію, передаючи в неї `dispatch` і `getState` як аргументи.\\n\\n- Усередині цієї функції можна виконувати асинхронні операції й надсилати звичайні actions.\\n\\nУстановлення:\\n\\nПід'єднання:\\n\\nМи створюємо функцію action:\\n\\nМи надсилаємо цей action:\\n\\nРедюсер обробляє звичайні actions:\\n\\nВикористання `redux-thunk` дає змогу ефективно керувати асинхронними процесами, роблячи код організованішим і передбачуванішим. Це особливо важливо в застосунках, де стан залежить від зовнішніх джерел даних.\",\"npm install redux-thunk\\n\\nimport { createStore, applyMiddleware } from 'redux';\\nimport thunk from 'redux-thunk';\\n// A simple reducer\\nconst reducer = (state = { data: null }, action) => {\\n  switch (action.type) {\\n    case 'SET_DATA':\\n      return { ...state, data: action.payload };\\n    default:\\n      return state;\\n  }\\n};\\n// The store with redux-thunk connected\\nconst store = createStore(reducer, applyMiddleware(thunk));\\n\\nconst fetchData = () => {\\n  return async (dispatch) => {\\n    dispatch({ type: 'FETCH_START' });\\n    try {\\n      const response = await fetch('https://api.example.com/data');\\n      const data = await response.json();\\n      dispatch({ type: 'SET_DATA', payload: data });\\n    } catch (error) {\\n      dispatch({ type: 'FETCH_ERROR', error });\\n    }\\n  };\\n};\\n\\nstore.dispatch(fetchData());\\n\\nconst reducer = (state = { loading: false, data: null, error: null }, action) => {\\n  switch (action.type) {\\n    case 'FETCH_START':\\n      return { ...state, loading: true, error: null };\\n    case 'SET_DATA':\\n      return { ...state, loading: false, data: action.payload };\\n    case 'FETCH_ERROR':\\n      return { ...state, loading: false, error: action.error };\\n    default:\\n      return state;\\n  }\\n};\"],[2835,\"`redux-saga` — middleware для Redux, яке використовує генератори JavaScript, щоб керувати асинхронними actions. Замість того щоб надсилати функції, як у `redux-thunk`, ви описуєте ефекти в «сагах», які слідкують за actions і виконують побічні ефекти (наприклад, запити до API). Це робить асинхронний код структурованішим і передбачуванішим.\",\"`redux-saga` допомагає обробляти побічні ефекти, як-от запити до API, затримки або взаємодії із зовнішніми ресурсами, не переповнюючи логіку в компонентах або в редюсерах. Воно засноване на концепції «саг» — функцій-генераторів, які відповідають на actions Redux і виконують ефекти.\\nУстановлення:\\n\\nСтворення редюсера:\\n\\nСтворення саги: сага — функція-генератор, яка слідкує за actions і виконує ефекти:\\n\\nПід'єднання саги до сховища:\\n\\nНадсилання actions:\\n\\nПереваги `redux-saga`:\\n\\n- Зручна організація складних асинхронних операцій.\\n\\n- Змога тестувати генератори.\\n\\n- Підтримка контролю потоків (наприклад, `takeLatest`, щоб виконати лише найновіший action).\",\"npm install redux-saga\\n\\nconst initialState = { data: null, loading: false, error: null };\\nconst reducer = (state = initialState, action) => {\\n  switch (action.type) {\\n    case 'FETCH_START':\\n      return { ...state, loading: true, error: null };\\n    case 'FETCH_SUCCESS':\\n      return { ...state, loading: false, data: action.payload };\\n    case 'FETCH_ERROR':\\n      return { ...state, loading: false, error: action.error };\\n    default:\\n      return state;\\n  }\\n};\\n\\nimport { call, put, takeEvery } from 'redux-saga/effects';\\nfunction* fetchDataSaga() {\\n  try {\\n    yield put({ type: 'FETCH_START' }); // We notify that the loading has begun\\n    const data = yield call(() => fetch('https://api.example.com/data').then(res => res.json()));\\n    yield put({ type: 'FETCH_SUCCESS', payload: data }); // A successful result\\n  } catch (error) {\\n    yield put({ type: 'FETCH_ERROR', error }); // Handling the error\\n  }\\n}\\n// We watch for particular actions\\nfunction* watchFetchData() {\\n  yield takeEvery('FETCH_DATA', fetchDataSaga);\\n}\\n\\nimport createSagaMiddleware from 'redux-saga';\\nimport { createStore, applyMiddleware } from 'redux';\\nimport { all } from 'redux-saga/effects';\\nconst sagaMiddleware = createSagaMiddleware();\\n// The root saga\\nfunction* rootSaga() {\\n  yield all([watchFetchData()]); // Starting every \\\"watcher\\\"\\n}\\nconst store = createStore(reducer, applyMiddleware(sagaMiddleware));\\nsagaMiddleware.run(rootSaga); // Starting the sagas\\n\\nstore.dispatch({ type: 'FETCH_DATA' });\"],[2836,\"Селектори — функції, які приймають стан Redux і повертають потрібні дані. Вони допомагають уникати повторення коду й покращують читність. Для складних обчислень над станом можна використати бібліотеки на кшталт `reselect`, щоб мемоїзувати результати й підняти продуктивність.\",\"Селектори в Redux використовують, щоб видобути з глобального стану дані, які далі передають компонентам. Замість того щоб звертатися до стану напряму через `state.someProperty`, селектори надають абстрактний спосіб отримати дані, який можна використовувати повторно.\\nПростий приклад селектора:\\n\\nКоли стан стає складним, селектори можуть поєднувати дані:\\n\\nЗадля оптимізації й щоб запобігти повторним обчисленням, використовують бібліотеку `reselect`:\\nУстановлення:\\n\\nСтворення мемоїзованого селектора:\\n\\nПереваги використання `reselect`:\\n\\n- Мемоїзація: результати селектора обчислюють заново лише тоді, коли вхідні дані змінюються.\\n\\n- Зручна робота з вкладеними станами.\\n\\n- Підвищення продуктивності, особливо у великих застосунках.\\n\\nБібліотеки, щоб працювати із селекторами:\\n\\n- `reselect`: найпопулярніша бібліотека, щоб створювати мемоїзовані селектори.\\n\\n- `re-reselect`: розширення `reselect`, яке дає змогу створювати селектори з кешуванням на основі параметрів.\\n\\n- `redux-toolkit`: включає вбудовану підтримку мемоїзованих селекторів через API `createSelector`.\\n\\nСелектори забезпечують простий, продуктивний й організований доступ до даних у Redux, особливо в застосунках із великим обсягом стану.\",\"const selectTodos = (state) => state.todos;\\n\\n// Using it:\\nconst todos = selectTodos(store.getState());\\n\\nconst selectCompletedTodos = (state) =>\\n  state.todos.filter((todo) => todo.completed);\\n\\nconst completedTodos = selectCompletedTodos(store.getState());\\n\\nnpm install reselect\\n\\nimport { createSelector } from 'reselect';\\n// The primitive selectors\\nconst selectTodos = (state) => state.todos;\\nconst selectFilter = (state) => state.filter;\\n// The combined selector\\nconst selectFilteredTodos = createSelector(\\n  [selectTodos, selectFilter],\\n  (todos, filter) => {\\n    switch (filter) {\\n      case 'completed':\\n        return todos.filter((todo) => todo.completed);\\n      case 'active':\\n        return todos.filter((todo) => !todo.completed);\\n      default:\\n        return todos;\\n    }\\n  }\\n);\\nconst filteredTodos = selectFilteredTodos(store.getState());\"],[2837,\"`Reselect` — бібліотека, щоб створювати селектори, які видобувають й обробляють дані зі стану Redux. Вона забезпечує мемоїзацію, що запобігає непотрібним обчисленням, якщо вхідні дані не змінилися. Це особливо корисно для складних обчислень, які залежать від стану.\",\"`Reselect` — бібліотека, яка полегшує створення селекторів задля роботи з Redux. Селектори — функції, які видобувають дані зі стану. Прості селектори повертають дані напряму, але задля складніших обчислень може бути потрібно поєднати кілька частин стану. У таких випадках без мемоїзації ті самі обчислення повторюватимуть щоразу, коли селектор викликають, навіть якщо дані не змінилися.\\nМемоїзація — ключова особливість `reselect`. Вона зберігає результат селектора й обчислює його заново лише тоді, коли вхідні дані змінилися. Це підвищує продуктивність застосунку.\\nПриклад використання `reselect`:\\nУстановлення:\\n\\nСтворення селекторів:\\n\\nПереваги:\\n\\n- Оптимізація: уникає повторного виконання складних обчислень.\\n\\n- Організація: покращує читність коду, абстрагуючи логіку доступу до даних.\\n\\n- Повторне використання: один селектор можна використовувати в кількох компонентах.\\n\\n`Reselect` часто використовують у великих застосунках, у яких є складні обчислення над станом. Це дає змогу оптимізувати продуктивність і полегшити керування станом.\",\"npm install reselect\\n\\nimport { createSelector } from 'reselect';\\n// The primitive selectors\\nconst selectTodos = (state) => state.todos;\\nconst selectFilter = (state) => state.filter;\\n// The memoized selector\\nconst selectFilteredTodos = createSelector(\\n  [selectTodos, selectFilter],\\n  (todos, filter) => {\\n    switch (filter) {\\n      case 'completed':\\n        return todos.filter((todo) => todo.completed);\\n      case 'active':\\n        return todos.filter((todo) => !todo.completed);\\n      default:\\n        return todos;\\n    }\\n  }\\n);\\n// Using it:\\nconst filteredTodos = selectFilteredTodos(store.getState());\"],[2838,\"`combineReducers` — функція Redux, яка поєднує кілька редюсерів в один. Це зручно, коли стан застосунку поділено на логічні частини (наприклад, користувачів, задачі, фільтри). Кожний редюсер керує власною частиною стану, а `combineReducers` поєднує їх в єдину структуру.\",\"Коли застосунок стає складним, поділ стану на окремі частини (або зрізи) допомагає організувати код. Кожним зрізом може керувати власний редюсер. Функція `combineReducers` дає змогу поєднати ці редюсери в єдиний кореневий редюсер, який передають у сховище Redux.\\nПриклад використання:\\n\\n- Окремі редюсери для кожного зрізу стану:\\n\\n- Поєднання редюсерів:\\n\\n- Створення сховища:\\n\\n- Приклад стану: після того як `combineReducers` використали, стан виглядатиме так:\\n\\n- Доступ до даних: компоненти можуть видобувати дані з відповідних частин стану:\\n\\nДля чого потрібний combineReducers?\\n\\n- Спрощення структури: поділ логіки на окремі редюсери робить код читнішим і таким, що легше підтримувати.\\n\\n- Масштабованість: простіше додавати нові редюсери, коли застосунок зростає.\\n\\n- Гнучкість: він дає кожному редюсерові змогу зосередитися лише на власній частині стану.\\n\\nУ великих застосунках використання `combineReducers` стає стандартом, адже воно допомагає тримати порядок у коді й полегшує роботу зі станом.\",\"const todosReducer = (state = [], action) => {\\n  switch (action.type) {\\n    case 'ADD_TODO':\\n      return [...state, action.payload];\\n    case 'REMOVE_TODO':\\n      return state.filter((todo) => todo.id !== action.payload);\\n    default:\\n      return state;\\n  }\\n};\\nconst filterReducer = (state = 'all', action) => {\\n  switch (action.type) {\\n    case 'SET_FILTER':\\n      return action.payload;\\n    default:\\n      return state;\\n  }\\n};\\n\\nimport { combineReducers } from 'redux';\\nconst rootReducer = combineReducers({\\n  todos: todosReducer,\\n  filter: filterReducer,\\n});\\nexport default rootReducer;\\n\\nimport { createStore } from 'redux';\\nimport rootReducer from './reducers';\\nconst store = createStore(rootReducer);\\n\\n{\\n  todos: [{ id: 1, text: 'Learn Redux' }],\\n  filter: 'all',\\n}\\n\\nconst todos = store.getState().todos;\\nconst filter = store.getState().filter;\"],[2839,\"Щоб під'єднати компонент до сховища Redux, використовують бібліотеку React Redux. Хук `useSelector` застосовують, щоб отримати дані зі стану, а `useDispatch` — щоб надіслати actions. Ці інструменти дають змогу інтегрувати логіку Redux у React-компоненти без потреби в додатковому налаштуванні.\",\"Пов'язування React-компонента зі сховищем Redux здійснюють через бібліотеку React Redux, яка надає хуки `useSelector` й `useDispatch`.\\nКроки, щоб його під'єднати:\\nПереконайтеся, що сховище Redux передали в застосунок через компонент `<Provider>`:\\n\\nВикористайте `useSelector`, щоб отримати доступ до стану:\\n\\nВикористайте `useDispatch`, щоб надсилати actions:\\n\\nКлючові аспекти:\\n\\n- `useSelector`: дає змогу «підписатися» на зміни у стані Redux й отримувати його дані.\\n\\n- `useDispatch`: надає функцію, щоб надсилати actions, аби змінити стан.\\n\\nАльтернативний підхід — connect (класичне API): у старіших версіях React Redux використовували функцію `connect`:\\n\\n`useSelector` й `useDispatch` — сучасніший і зручніший спосіб працювати з Redux у функційних компонентах.\",\"import { Provider } from 'react-redux';\\nimport { store } from './store';\\nconst App = () => (\\n  <Provider store={store}>\\n    <YourComponent />\\n  </Provider>\\n);\\n\\nimport { useSelector } from 'react-redux';\\nconst YourComponent = () => {\\n  const todos = useSelector((state) => state.todos);\\n  return (\\n    <ul>\\n      {todos.map((todo) => (\\n        <li key={todo.id}>{todo.text}</li>\\n      ))}\\n    </ul>\\n  );\\n};\\n\\nimport { useDispatch } from 'react-redux';\\nconst YourComponent = () => {\\n  const dispatch = useDispatch();\\n  const addTodo = () => {\\n    dispatch({ type: 'ADD_TODO', payload: { text: 'New Task' } });\\n  };\\n  return <button onClick={addTodo}>Add Todo</button>;\\n};\\n\\nimport { connect } from 'react-redux';\\nconst mapStateToProps = (state) => ({\\n  todos: state.todos,\\n});\\nconst mapDispatchToProps = (dispatch) => ({\\n  addTodo: () => dispatch({ type: 'ADD_TODO', payload: { text: 'New Task' } }),\\n});\\nconst YourComponent = ({ todos, addTodo }) => (\\n  <div>\\n    <ul>\\n      {todos.map((todo) => (\\n        <li key={todo.id}>{todo.text}</li>\\n      ))}\\n    </ul>\\n    <button onClick={addTodo}>Add Todo</button>\\n  </div>\\n);\\nexport default connect(mapStateToProps, mapDispatchToProps)(YourComponent);\"],[2840,\"Redux Toolkit — офіційна бібліотека від розробників Redux, яка полегшує налаштування сховища й створення редюсерів й actions. Вона усуває повторюваний код і надає інструменти, щоб працювати з асинхронними операціями. Це рекомендований спосіб використовувати Redux у сучасних застосунках.\",\"Redux Toolkit (RTK) — надбудова над Redux, яку спроєктували, щоб зробити роботу з ним простішою й стандартизованішою. У традиційному Redux розробники часто стикаються з великою кількістю шаблонного коду: ручним створенням actions і редюсерів, налаштуванням middleware тощо. Redux Toolkit розв'язує ці проблеми, надаючи набір утиліт, щоб створити застосунок швидко й ефективно.\\nКлючові особливості Redux Toolkit:\\n\\n- `configureStore`: полегшує створення сховища й під'єднує корисне middleware автоматично (наприклад, щоб працювати з асинхронністю).\\n\\n- `createSlice`: дає змогу поєднати редюсер й actions в одному місці, усуваючи потребу визначати типи actions вручну.\\n\\n- `createAsyncThunk`: полегшує роботу з асинхронними actions, обробляючи їхній стан (завантаження, успіх, помилка) автоматично.\\n\\nМемоїзація й зручні інструменти: інтеграція з інструментами зневадження на кшталт Redux DevTools.\\nПриклад використання Redux Toolkit:\\n\\nАсинхронні actions із `createAsyncThunk`:\\n\\nЧому Redux Toolkit корисний?\\n\\n- Менше шаблонного коду: ви пишете лише те, що важливо задля бізнес-логіки.\\n\\n- Зручність: інструменти на кшталт `createSlice` обробляють створення actions і редюсерів автоматично.\\n\\n- Безпека: він включає найкращі практики за замовчуванням — наприклад, використання `Immer`, щоб працювати з немутабельними станами.\\n\\n- Інтеграція: він легко працює з React, Redux DevTools і middleware.\\n\\nRedux Toolkit став стандартом задля розробки на Redux, і його рекомендують використовувати в усіх нових проєктах.\",\"import { configureStore, createSlice } from '@reduxjs/toolkit';\\n// Creating a slice\\nconst todosSlice = createSlice({\\n  name: 'todos',\\n  initialState: [],\\n  reducers: {\\n    addTodo: (state, action) => {\\n      state.push(action.payload);\\n    },\\n    removeTodo: (state, action) => {\\n      return state.filter((todo) => todo.id !== action.payload);\\n    },\\n  },\\n});\\n// Exporting the actions\\nexport const { addTodo, removeTodo } = todosSlice.actions;\\n// Creating the store\\nconst store = configureStore({\\n  reducer: {\\n    todos: todosSlice.reducer,\\n  },\\n});\\nexport default store;\\n\\nimport { createAsyncThunk } from '@reduxjs/toolkit';\\nexport const fetchTodos = createAsyncThunk('todos/fetchTodos', async () => {\\n  const response = await fetch('/api/todos');\\n  return response.json();\\n});\"],[2841,\"`createSlice` — утиліта з Redux Toolkit, яка дає змогу поєднати редюсери й actions в єдиному об'єкті. Це полегшує створення редюсерів, знімає потребу писати типи actions вручну й покращує читність коду. Action creators і редюсери для цих actions генерують автоматично.\",\"`createSlice` — функція з Redux Toolkit, яка полегшує створення редюсерів й actions задля роботи зі станом. Звичайно в Redux доводилося створювати actions (типи actions) і редюсери вручну, що призводило до великої кількості шаблонного коду. `createSlice` усуває цю проблему, даючи змогу описати редюсери й actions в одному місці.\\nЯк використовувати `createSlice`:\\nУ `createSlice` передають об'єкт із кількома ключами:\\n\\n- `name`: ім'я зрізу стану, яке використовуватимуть, щоб згенерувати префікс типів actions.\\n\\n- `initialState`: початковий стан.\\n\\n- `reducers`: об'єкт, який містить функції-редюсери, що оновлюють стан.\\n\\nПриклад використання `createSlice`:\\n\\nПереваги `createSlice`:\\n\\n- Спрощення коду: `createSlice` поєднує створення редюсерів й actions в одному місці.\\n\\n- Автоматичне створення actions: для кожного редюсера відповідний action створюють автоматично (наприклад, `addTodo`).\\n\\n- Читність і легкість підтримки: менше повторюваного коду й краща структура.\\n\\n- Вбудована підтримка немутабельності: використовують бібліотеку Immer, яка дає змогу змінювати стан «мутабельно», тимчасом як він фактично залишається незмінним.\\n\\nПриклад використання:\\n\\nОтже, `createSlice` значно полегшує розробку, покращує читність коду й прискорює процес розробки, знімаючи потребу виписувати типи actions і редюсери вручну.\",\"import { createSlice } from '@reduxjs/toolkit';\\nconst todosSlice = createSlice({\\n  name: 'todos', // The name of the slice of state\\n  initialState: [], // The initial state (an empty list of tasks)\\n  reducers: {\\n    addTodo: (state, action) => {\\n      state.push(action.payload); // Adding a task\\n    },\\n    removeTodo: (state, action) => {\\n      return state.filter(todo => todo.id !== action.payload); // Removing a task\\n    }\\n  }\\n});\\n// The automatically generated actions\\nexport const { addTodo, removeTodo } = todosSlice.actions;\\n// The reducer\\nexport default todosSlice.reducer;\\n\\nimport { configureStore } from '@reduxjs/toolkit';\\nimport todosReducer from './todosSlice';\\nconst store = configureStore({\\n  reducer: {\\n    todos: todosReducer\\n  }\\n});\"],[2842,\"`createReducer` — функція з Redux Toolkit, яка допомагає створювати редюсери без потреби визначати типи actions вручну. Вона приймає об'єкт зі станом й actions, і кожний редюсер оновлює стан залежно від типу action. Це дає змогу писати редюсери компактніше й ефективніше.\",\"`createReducer` — функція, яку надає Redux Toolkit, яка дає змогу створювати редюсери, не зазначаючи типів actions явно. Замість традиційного підходу з ручним створенням типу action й обробкою кожного з них у редюсері `createReducer` дає змогу одразу прив'язати actions до зміни стану за допомогою об'єкта, у якому ключі — типи actions, а значення — редюсери.\\nЯк працює `createReducer`:\\n`createReducer` приймає два аргументи:\\n\\n- Початковий стан.\\n\\n- Об'єкт, у якому ключі — типи actions, а значення — функції, які змінюють стан.\\n\\n- Для кожного типу action редюсер викличе відповідну функцію.\\n\\nПриклад використання `createReducer`:\\n\\nПереваги `createReducer`:\\n\\n- Чистота коду: редюсери виглядають компактніше, адже немає потреби зазначати `switch` і типи actions явно.\\n\\n- Автоматична немутабельність: усередині редюсера застосовують бібліотеку Immer, яка дає змогу змінювати стан «мутабельно», тимчасом як він фактично залишається незмінним.\\n\\n- Гнучкість: ви можете додати будь-які actions і змінювати стан в єдиній функції, що полегшує підтримку.\\n\\nЯк використовувати це у сховищі:\\n\\n`createReducer` ідеальний для випадків, коли редюсер треба створити, не зазначаючи типів actions явно, і ви хочете позбутися шаблонного коду. Це робить код простішим, чистішим і легшим у підтримці, особливо для великих проєктів.\",\"import { createReducer } from '@reduxjs/toolkit';\\nconst initialState = [];\\nconst todosReducer = createReducer(initialState, {\\n  ADD_TODO: (state, action) => {\\n    state.push(action.payload); // Adding a task\\n  },\\n  REMOVE_TODO: (state, action) => {\\n    return state.filter(todo => todo.id !== action.payload); // Removing a task\\n  }\\n});\\nexport default todosReducer;\\n\\nimport { configureStore } from '@reduxjs/toolkit';\\nimport todosReducer from './todosReducer';\\nconst store = configureStore({\\n  reducer: {\\n    todos: todosReducer\\n  }\\n});\"],[2843,\"`createAsyncThunk` — утиліта з Redux Toolkit, щоб працювати з асинхронними actions. Вона допомагає створювати асинхронні actions, генеруючи три стани автоматично: pending, успіх і помилку. Ви описуєте асинхронну функцію, а Redux Toolkit керує станом завантаження й помилки автоматично, оновлюючи сховище на основі результату action.\",\"`createAsyncThunk` — функція з Redux Toolkit, призначена, щоб полегшити роботу з асинхронними actions у Redux. Вона створює три actions автоматично для кожного асинхронного запиту: один для початку запиту, один для його успішного завершення й один для помилки. Ці actions допомагають тримати стан завантаження й помилок у застосунку під контролем, не потребуючи додаткового коду.\\nЯк використовувати `createAsyncThunk`:\\n\\n- Перший аргумент — рядок, який визначає тип action.\\n\\n- Другий аргумент — асинхронна функція, яка повертає проміс або виконує асинхронну операцію — наприклад, запит до API.\\n\\nПриклад:\\n\\nЯк це працює з асинхронним станом: під час роботи `createAsyncThunk` три actions створюють автоматично:\\n\\n- pending — коли запит надіслали, але він ще не завершився.\\n\\n- fulfilled — коли запит завершився успішно.\\n\\n- rejected — коли запит завершився з помилкою.\\n\\nПриклад:\\n\\nПереваги `createAsyncThunk`:\\n\\n- Вона керує станом завантаження й помилки автоматично.\\n\\n- Вона зменшує обсяг коду, який треба писати вручну, щоб обробляти асинхронні операції.\\n\\n- Вона полегшує керування асинхронними запитами, покращуючи читність і легкість підтримки коду.\",\"import { createAsyncThunk } from '@reduxjs/toolkit';\\nconst fetchData = createAsyncThunk('data/fetchData', async () => {\\n  const response = await fetch('/api/data');\\n  return response.json(); // returns the data\\n});\\n\\nimport { createSlice } from '@reduxjs/toolkit';\\nconst dataSlice = createSlice({\\n  name: 'data',\\n  initialState: { data: [], loading: false, error: null },\\n  reducers: {},\\n  extraReducers: (builder) => {\\n    builder\\n      .addCase(fetchData.pending, (state) => {\\n        state.loading = true;\\n        state.error = null;\\n      })\\n      .addCase(fetchData.fulfilled, (state, action) => {\\n        state.data = action.payload;\\n        state.loading = false;\\n      })\\n      .addCase(fetchData.rejected, (state, action) => {\\n        state.loading = false;\\n        state.error = action.error.message;\\n      });\\n  }\\n});\"],[2844,\"RTK (Redux Toolkit) полегшує роботу з асинхронними запитами й побічними ефектами за допомогою `createAsyncThunk`, який керує станом запитів автоматично. Він створює три стани для кожного асинхронного action (pending, успіх, помилка) й оновлює сховище залежно від результату. RTK також полегшує обробку побічних ефектів, як-от викликів API, через зручні механізми, щоб працювати з асинхронними даними.\",\"RTK надає інструменти, щоб працювати з асинхронними запитами й побічними ефектами, через функції на кшталт `createAsyncThunk` і вбудовані можливості обробляти ці ефекти в `extraReducers`. На відміну від звичайного Redux, де станом і типами actions доводилося керувати вручну, щоб працювати з асинхронними actions, RTK пропонує простіший і зручніший спосіб.\\nОсновні механізми:\\n\\n- `createAsyncThunk`: це зручний спосіб обробляти асинхронні запити. Він генерує три actions автоматично (pending, fulfilled, rejected), щоб працювати зі станом завантаження, даних і помилки. Це спрощує код й усуває потребу відстежувати перебіг запитів вручну.\\n\\nЯк RTK керує побічними ефектами: коли треба виконати асинхронні операції, як-от запити до сервера, RTK дає змогу обробити їх за допомогою `createAsyncThunk`. У відповідь на успішне завершення запиту (fulfilled) дані оновлюють у стані автоматично. На помилці (rejected) інформацію про помилку зберігають у стані.\\nПриклад:\\n\\nОбробка побічних ефектів в `extraReducers`: у RTK побічні ефекти можна обробляти в `extraReducers`, де ви описуєте, як стан змінюється залежно від кожного типу асинхронного action.\\n\\nПереваги RTK задля асинхронних запитів:\\n\\n- Спрощення коду: менша потреба обробляти стан завантаження й помилки вручну.\\n\\n- Автоматичне створення actions, щоб виконувати асинхронні операції.\\n\\n- Підтримка роботи з асинхронними операціями через `createAsyncThunk`, що значно покращує легкість підтримки й читність коду.\\n\\nОтже, RTK допомагає розробникам заощаджувати час, покращувати якість свого коду й легко працювати з асинхронними запитами й побічними ефектами в Redux.\",\"const fetchData = createAsyncThunk('data/fetchData', async () => {\\n  const response = await fetch('/api/data');\\n  return response.json();\\n});\\n\\nconst dataSlice = createSlice({\\n  name: 'data',\\n  initialState: { data: [], loading: false, error: null },\\n  reducers: {},\\n  extraReducers: (builder) => {\\n    builder\\n      .addCase(fetchData.pending, (state) => {\\n        state.loading = true;\\n        state.error = null;\\n      })\\n      .addCase(fetchData.fulfilled, (state, action) => {\\n        state.data = action.payload;\\n        state.loading = false;\\n      })\\n      .addCase(fetchData.rejected, (state, action) => {\\n        state.loading = false;\\n        state.error = action.error.message;\\n      });\\n  }\\n});\"],[2845,\"`createEntityAdapter` — утиліта Redux Toolkit, призначена, щоб полегшити роботу з колекціями об'єктів. Вона надає набір методів, щоб додавати, вилучати, оновлювати й сортувати об'єкти в масиві. Це дає змогу керувати станом ефективніше, особливо коли доводиться працювати з великою кількістю об'єктів, як-от записами з бази даних.\",\"`createEntityAdapter` надає набір інструментів, щоб працювати з колекціями даних у Redux. Цей інструмент допомагає керувати станом, який містить безліч об'єктів, роблячи простішими їхнє додавання, оновлення й вилучення без написання великої кількості коду.\\nЯк працює `createEntityAdapter`:\\nВона надає методи, щоб працювати з колекціями — наприклад, `addOne`, `removeOne`, `updateOne`, — які полегшують оновлення стану.\\nЗамість того щоб зберігати масив об'єктів, можна використати ефективнішу структуру з ключем й об'єктами, що прискорює операції пошуку й оновлення.\\nПриклад використання:\\n\\nПереваги:\\n\\n- Вона дає змогу легко працювати з великими списками даних.\\n\\n- Вона використовує оптимізованішу структуру, щоб зберігати дані (ключі й значення), що полегшує операції пошуку й оновлення.\",\"import { createEntityAdapter, createSlice } from '@reduxjs/toolkit';\\n// We create the adapter\\nconst usersAdapter = createEntityAdapter();\\n// Initializing the state\\nconst initialState = usersAdapter.getInitialState({\\n  loading: false,\\n  error: null\\n});\\n// We create the slice\\nconst usersSlice = createSlice({\\n  name: 'users',\\n  initialState,\\n  reducers: {\\n    setUsers: usersAdapter.setAll,\\n    addUser: usersAdapter.addOne,\\n  }\\n});\\nexport const { setUsers, addUser } = usersSlice.actions;\\nexport default usersSlice.reducer;\"],[2846,\"`createSelector` із бібліотеки `reselect` дає змогу створювати мемоїзовані селектори, які ефективно видобувають й обчислюють дані зі стану Redux. Із RTK його використовують, щоб створити продуктивні селектори, які уникають непотрібних повторних обчислень, якщо дані не змінилися.\",\"`createSelector` — функція з бібліотеки `reselect`, яка допомагає створювати мемоїзовані селектори. Це означає, що селектори обчислюватимуть лише тоді, коли дані, які вони використовують, змінюються, що підвищує продуктивність застосунку.\\nЯк використовувати це з RTK:\\nЩоб створити селектор за допомогою `createSelector`, треба передати функції, які видобувають дані зі стану Redux, а потім виконати додаткові обчислення, якщо це потрібно.\\nПриклад використання з RTK:\\n\\nПереваги:\\n\\n- Селектори з мемоїзацією дають змогу уникати надлишкових повторних обчислень і покращувати продуктивність застосунку.\\n\\n- Ви можете поєднувати селектори задля складніших обчислень, залишаючись ефективними.\",\"import { createSelector } from 'reselect';\\n// A selector for obtaining every user\\nconst selectUsers = (state) => state.users.entities;\\n// A memoized selector for obtaining the active users\\nconst selectActiveUsers = createSelector(\\n  [selectUsers],\\n  (users) => users.filter(user => user.active)\\n);\"],[2847,\"RTK Query — потужний інструмент із Redux Toolkit, призначений, щоб полегшити роботу із запитами до API й кешуванням даних. Він генерує actions, редюсери й запити задля взаємодії з REST API або з іншими джерелами даних автоматично. RTK Query дає змогу обробляти стани завантаження, успішної відповіді й помилки автоматично.\",\"RTK Query — інструмент, щоб працювати із серверними запитами, який автоматизує багато процесів, як-от створення actions, обробку станів завантаження й помилки й керування кешуванням даних.\\nЯк працює RTK Query:\\n\\n- У RTK Query створюють сервіс з описом ендпойнтів API, і для кожного запиту actions і редюсери генерують автоматично.\\n\\n- Він керує станом запитів, включно зі станами завантаження й помилки, й може кешувати відповіді, щоб запобігти повторним запитам.\\n\\nПриклад використання:\\n\\nПереваги:\\n\\n- Автоматична генерація actions і редюсерів.\\n\\n- Обробка станів запитів без потреби керувати кожним запитом вручну.\\n\\n- Вбудоване кешування й оптимізація запитів, що зменшує навантаження на сервер і покращує продуктивність застосунку.\",\"import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\\n// Creating the API with the endpoints\\nconst api = createApi({\\n  reducerPath: 'api',\\n  baseQuery: fetchBaseQuery({ baseUrl: '/api/' }),\\n  endpoints: (builder) => ({\\n    getUsers: builder.query({\\n      query: () => 'users',\\n    }),\\n  }),\\n});\\n// Using the hook in a component\\nconst { data, error, isLoading } = useGetUsersQuery();\"],[2848,\"RTK Query допомагає інтегрувати запити до API в застосунок за допомогою автоматичної генерації actions і редюсерів. Ви створюєте сервіс із ендпойнтами, а потім використовуєте згенеровані хуки в компонентах, щоб виконувати запити й обробляти стани завантаження й помилки.\",\"RTK Query полегшує роботу із запитами до API, автоматизуючи багато процесів, як-от створення actions для запитів, обробку станів і кешування відповідей.\\nЯк використовувати RTK Query для запитів до API:\\n\\n- Спочатку ви створюєте сервіс із ендпойнтами, описуючи маршрути й запити.\\n\\n- Далі ви використовуєте згенеровані хуки в компонентах, щоб виконувати запити й працювати зі станом.\\n\\nПриклад використання:\\n\\nПереваги використання RTK Query:\\n\\n- Автоматичне створення actions для кожного запиту.\\n\\n- Керування станами завантаження й помилки з мінімальними зусиллями.\\n\\n- Кешування запитів, що покращує продуктивність.\",\"import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\\nconst api = createApi({\\n  reducerPath: 'api',\\n  baseQuery: fetchBaseQuery({ baseUrl: '/api/' }),\\n  endpoints: (builder) => ({\\n    getPosts: builder.query({\\n      query: () => 'posts',\\n    }),\\n  }),\\n});\\n// The hook for obtaining the data\\nconst { data, error, isLoading } = useGetPostsQuery();\"],[2849,\"Щоб оптимізувати Redux-застосунок, можна використати кілька технік. По-перше, варто мінімізувати кількість викликів `dispatch` й оновлень стану. По-друге, варто уникати надлишкових рендерів компонентів, використовуючи мемоїзацію, `reselect` або `React.memo`. Також корисно нормалізувати дані у сховищі, щоб полегшити їхнє видобування й керування ними. Використання middleware на кшталт `redux-thunk` допоможе керувати асинхронними операціями ефективніше.\",\"Щоб покращити продуктивність Redux-застосунку, важливо оптимізувати рендеринг компонентів і керування станом. Ось кілька ключових підходів:\\n\\n- Мінімізація змін стану: намагайтеся оновлювати лише ті частини стану, які справді змінюються. Уникайте глобальних змін стану, адже це може спричиняти повторний рендер кожного компонента, під'єднаного до Redux.\\n\\n- Мемоїзація за допомогою `reselect`: щоб оптимізувати обчислення, які можуть бути дорогими, використовуйте мемоїзацію. `Reselect` допомагає кешувати результати селекторів, запобігаючи повторним обчисленням, якщо вхідні дані не змінилися.\\n\\n- Використання `React.memo` й `useMemo`: ці хуки React дають змогу уникати непотрібних рендерів. Якщо компонент не змінився, `React.memo` дає змогу не рендерити його знову.\\n\\n- Нормалізація даних: зберігайте дані у форматі, який полегшує доступ і мінімізує потребу оновлювати весь стан. Наприклад, замість масиву об'єктів використовуйте об'єкти з унікальними ідентифікаторами, щоб видобувати й змінювати дані простіше.\\n\\n- Ліниве завантаження й розділення коду: завантажуйте лише ті частини застосунку, які потрібні, щоб прискорити початкове завантаження й зменшити навантаження на застосунок.\\n\\nПриклад нормалізації даних:\",\"// We normalize the array of data:\\nconst initialState = {\\n  users: {\\n    1: { id: 1, name: 'Alice' },\\n    2: { id: 2, name: 'Bob' }\\n  }\\n};\\n// Instead of this:\\nconst initialState = {\\n  users: [\\n    { id: 1, name: 'Alice' },\\n    { id: 2, name: 'Bob' }\\n  ]\\n};\"],[2850,\"Мемоїзація — техніка оптимізації, за якої результати функції зберігають і використовують знову, якщо вхідні дані не змінилися. У Redux мемоїзацію використовують за допомогою бібліотеки `reselect`, яка дає змогу кешувати результати селекторів й уникати обчислювати їх знову. Це особливо корисно в роботі з великими наборами даних, де обчислення можуть бути дорогими.\",\"Мемоїзація дає змогу уникати обчислювати функцію знову з тими самими аргументами, що значно прискорює роботу застосунку. У Redux мемоїзацію часто використовують у поєднанні з бібліотекою `reselect`, щоб покращити продуктивність, коли видобувають дані зі сховища.\\nКоли ми створюємо селектор за допомогою `reselect`, він запам'ятовує результати функції для певних вхідних даних. Якщо дані, передані в селектор, не змінилися, селектор повертає вже обчислений результат, що заощаджує ресурси й запобігає повторним обчисленням.\\nПриклад використання мемоїзації з `reselect`:\\n\\nУ цьому прикладі селектор `getFilteredUsers` кешуватиме результат фільтрації користувачів. Якщо `users` або `filter` не змінюється, поверне попередній результат без повторного обчислення.\\nОтже, мемоїзація допомагає зменшити кількість обчислень, покращуючи продуктивність, особливо в застосунках із великими обсягами даних.\",\"import { createSelector } from 'reselect';\\n// The selectors for extracting the data\\nconst getUsers = state => state.users;\\nconst getUserFilter = state => state.filter;\\n// The memoized selector\\nconst getFilteredUsers = createSelector(\\n  [getUsers, getUserFilter],\\n  (users, filter) => {\\n    return users.filter(user => user.name.includes(filter));\\n  }\\n);\"],[2851,\"Нормалізація даних у Redux — процес перетворення складних, вкладених структур даних на пласкішу форму, у якій кожне значення зберігають під унікальним ідентифікатором. Це важливо, адже це полегшує видобування даних, мінімізує дублювання й дає змогу оновлювати дані ефективніше. Наприклад, замість того щоб зберігати масив об'єктів із тими самими властивостями, можна використати об'єкт, у якому ключі — унікальні ідентифікатори.\",\"Нормалізація даних у Redux полягає у спрощенні структури сховища, аби уникати надлишкових даних і полегшити доступ до них. Коли дані не нормалізовані — наприклад, коли масив об'єктів із тими самими властивостями повторюється, — це призводить до надлишковості й до складності оновлень. Нормалізація розв'язує цю проблему, подаючи дані у вигляді пласкої структури, у якій кожний елемент можна знайти за унікальним ключем.\\nПриклад ненормалізованих даних:\\n\\nУ такому разі, якщо адреса змінюється для кількох користувачів, її доведеться оновити в кожному об'єкті, що призводить до дублювання даних і збільшує ймовірність помилок.\\nПриклад нормалізованих даних:\\n\\nУ цьому разі ми зберігаємо лише унікальні дані для кожного користувача й адреси, що полегшує оновлення. Якщо треба змінити місто, ми просто оновлюємо запис в `addresses`, не торкаючись масиву користувачів.\",\"const state = {\\n  users: [\\n    { id: 1, name: 'Alice', address: { city: 'NY' } },\\n    { id: 2, name: 'Bob', address: { city: 'LA' } },\\n  ]\\n};\\n\\nconst state = {\\n  users: {\\n    1: { id: 1, name: 'Alice', addressId: 101 },\\n    2: { id: 2, name: 'Bob', addressId: 102 }\\n  },\\n  addresses: {\\n    101: { city: 'NY' },\\n    102: { city: 'LA' }\\n  }\\n};\"],[2852,\"Щоб ефективно керувати станом у великих застосунках із Redux, важливо поділити стан на дрібніші частини й використовувати middleware для асинхронних операцій. Застосування `combineReducers` допомагає організувати логіку, а використання нормалізації даних робить сховище компактнішим і полегшує доступ до даних. Також варто оптимізувати продуктивність за допомогою мемоїзації, селекторів і мемоїзованих хуків на кшталт `React.memo`.\",\"Коли застосунок зростає, а стан стає складним, важливо мати стратегії, щоб ефективно керувати цим станом. Ось кілька рекомендацій задля роботи з великим застосунком із використанням Redux:\\n\\n- Поділ стану: використовуйте `combineReducers`, щоб організувати стан у дрібніші, незалежні частини. Це дає змогу підтримувати структурованіше й масштабованіше сховище. Наприклад, логіку можна поділити на редюсери для користувачів, товарів, замовлень тощо.\\n\\n- Нормалізація даних: коли застосунок керує великим обсягом даних, нормалізація стає ключовим чинником. Наприклад, замість того щоб зберігати масиви об'єктів із дубльованими даними, краще зберігати дані під унікальними ідентифікаторами. Це дає змогу легко оновлювати й отримувати дані без надлишкового навантаження.\\n\\n- Асинхронні операції: у великих застосунках часто доводиться працювати з асинхронними запитами. Задля цього краще використовувати middleware на кшталт `redux-thunk`, `redux-saga` або `RTK Query`, щоб ефективно керувати побічними ефектами й запитами до сервера. Це допомагає уникати засмічення компонента й полегшує обробку асинхронних операцій.\\n\\n- Оптимізація продуктивності: використовуйте мемоїзацію, щоб запобігти надлишковим рендерам. Задля цього можна застосувати селектори з `reselect`, які кешують результати обчислень. Також застосовуйте `React.memo` до компонентів, аби уникати непотрібних рендерів.\\n\\n- Використання Redux Toolkit (RTK): RTK полегшує налаштування Redux у застосунках, скорочуючи обсяг шаблонного коду й надаючи корисні функції на кшталт `createSlice` й `createAsyncThunk`, які допомагають спростити роботу зі станом й з асинхронними actions.\\n\\nПриклад використання `combineReducers`:\\n\\nПриклад використання `createSlice`:\\n\\nОтже, щоб керувати станом великого застосунку, важливо підтримувати структуру даних, оптимізувати рендеринг, використовувати асинхронні операції й належно організувати логіку за допомогою інструментів Redux Toolkit.\",\"import { combineReducers } from 'redux';\\nconst rootReducer = combineReducers({\\n  users: usersReducer,\\n  posts: postsReducer,\\n  comments: commentsReducer\\n});\\n\\nimport { createSlice } from '@reduxjs/toolkit';\\nconst userSlice = createSlice({\\n  name: 'users',\\n  initialState: [],\\n  reducers: {\\n    setUsers: (state, action) => {\\n      return action.payload;\\n    }\\n  }\\n});\\nexport const { setUsers } = userSlice.actions;\\nexport default userSlice.reducer;\"],[2853,\"Щоб обробляти авторизацію й автентифікацію з використанням Redux, стан звичайно зберігають у редюсері, який тримає дані на кшталт токена доступу, інформації про користувача й прапорця, що позначає статус авторизації. Після успішного входу токен можна зберегти у сховищі Redux, а на виході — вилучити. Також часто використовують middleware для асинхронних запитів, як-от авторизації через API.\",\"Обробка авторизації й автентифікації в застосунку з використанням Redux звичайно включає кілька стадій:\\n\\n- Зберігання даних про користувача в Redux: коли користувач входить, дані на кшталт токена авторизації або інформації про користувача зберігають у Redux. Це дає змогу керувати станом централізовано й отримувати доступ до цих даних у будь-якому компоненті застосунку.\\n\\n- Використання middleware для асинхронних actions: асинхронні операції, як-от запити до сервера задля авторизації, звичайно обробляють за допомогою middleware — наприклад, `redux-thunk` або `redux-saga`. Ці інструменти дають змогу надсилати запити й обробляти успішну або неуспішну відповідь, оновлюючи стан авторизації в Redux.\\n\\nПриклад редюсера для автентифікації:\\n\\nЗбереження токенів і безпека: важливо пам'ятати, що задля безпеки токени й інші чутливі дані не можна зберігати у сховищі Redux відкрито. Краще використовувати інші способи їх зберігати, як-от `localStorage` або `sessionStorage`, а дані зі сховища Redux можна синхронізувати з цими сховищами.\\nПриклад авторизації з використанням middleware:\",\"const initialState = {\\n  isAuthenticated: false,\\n  user: null,\\n  token: null,\\n  loading: false,\\n  error: null\\n};\\nconst authReducer = (state = initialState, action) => {\\n  switch (action.type) {\\n    case 'LOGIN_REQUEST':\\n      return { ...state, loading: true };\\n    case 'LOGIN_SUCCESS':\\n      return { ...state, loading: false, isAuthenticated: true, user: action.payload.user, token: action.payload.token };\\n    case 'LOGIN_FAILURE':\\n      return { ...state, loading: false, error: action.payload.error };\\n    case 'LOGOUT':\\n      return { ...state, isAuthenticated: false, user: null, token: null };\\n    default:\\n      return state;\\n  }\\n};\\n\\n// An example with redux-thunk for asynchronous authorization\\nconst loginUser = (credentials) => async (dispatch) => {\\n  try {\\n    dispatch({ type: 'LOGIN_REQUEST' });\\n    const response = await api.login(credentials);\\n    dispatch({ type: 'LOGIN_SUCCESS', payload: { user: response.data, token: response.token } });\\n  } catch (error) {\\n    dispatch({ type: 'LOGIN_FAILURE', payload: { error: error.message } });\\n  }\\n};\"],[2854,\"Щоб керувати станом багатокомпонентних форм за допомогою Redux, дані форми можна зберігати в глобальному стані. Кожний компонент форми можна пов'язати з частиною цього стану через `mapStateToProps` й `mapDispatchToProps`. Також корисно використовувати події, як-от зміну полів форми, щоб оновлювати стан через actions у Redux.\",\"Багатокомпонентними формами може бути складно керувати, особливо якщо кожний компонент обробляє частину даних форми. У такому разі Redux надає зручне рішення, щоб зберігати стан форми й керувати ним централізовано.\\n\\n- Структура стану форми: у редюсері створюють структуру, щоб зберігати всі значення форми. Це дає змогу оновлювати й отримувати стан форми централізовано й забезпечити узгодженість між компонентами.\\n\\n- Компоненти форми: кожний компонент форми можна пов'язати з частиною стану форми через `connect` або через хуки `useSelector` й `useDispatch`. Коли користувач вводить дані, компоненти надсилають actions, щоб оновити відповідні поля стану.\\n\\nПриклад редюсера для форми:\\n\\nКомпоненти форми:\\n\\nКерування надсиланням форми: після того як кожне поле форми заповнили, action задля надсилання даних можна пов'язати з Redux. Дані форми надсилатимуть через actions, які обробляють у редюсері.\\nПриклад action, щоб надіслати дані форми:\\n\\nВикористання Redux, щоб керувати багатокомпонентними формами, допомагає відстежувати стан кожного поля централізовано, полегшуючи синхронізацію даних і запобігаючи дублюванню логіки в компонентах.\",\"const initialState = {\\n  name: '',\\n  email: '',\\n  password: '',\\n};\\nconst formReducer = (state = initialState, action) => {\\n  switch (action.type) {\\n    case 'SET_FORM_FIELD':\\n      return { ...state, [action.payload.field]: action.payload.value };\\n    default:\\n      return state;\\n  }\\n};\\n\\nconst NameField = () => {\\n  const dispatch = useDispatch();\\n  const name = useSelector(state => state.form.name);\\n  const handleChange = (e) => {\\n    dispatch({ type: 'SET_FORM_FIELD', payload: { field: 'name', value: e.target.value } });\\n  };\\n  return <input type=\\\"text\\\" value={name} onChange={handleChange} />;\\n};\\nconst EmailField = () => {\\n  const dispatch = useDispatch();\\n  const email = useSelector(state => state.form.email);\\n  const handleChange = (e) => {\\n    dispatch({ type: 'SET_FORM_FIELD', payload: { field: 'email', value: e.target.value } });\\n  };\\n  return <input type=\\\"email\\\" value={email} onChange={handleChange} />;\\n};\\n\\nconst submitForm = (formData) => async (dispatch) => {\\n  try {\\n    await api.submitForm(formData);\\n    dispatch({ type: 'FORM_SUBMIT_SUCCESS' });\\n  } catch (error) {\\n    dispatch({ type: 'FORM_SUBMIT_FAILURE', payload: error });\\n  }\\n};\"],[2855,\"`useReducer` — хук React, який керує складним станом за допомогою редюсера (функції, яка обробляє дії). Його варто використовувати:\\n- Коли стан складний (безліч пов'язаних значень — наприклад, форма з валідацією).\\n- Коли логіка оновлення нетривіальна (багато умов, побічні ефекти).\\n- Щоб оптимізувати продуктивність (редюсери допомагають уникати зайвих повторних рендерів).\\n- Як спрощену альтернативу Redux (якщо глобальний стан вам не потрібний).\",\"1. Як працює `useReducer`?\\n`useReducer` приймає три аргументи:\\n- Редюсер — функцію вигляду `(state, action) => newState`, яка визначає, як стан має змінюватися у відповідь на дію.\\n- Початковий стан.\\n- (Необов'язково) функцію задля лінивої ініціалізації стану.\\n\\nВін повертає масив із двох елементів:\\n- Поточний стан.\\n- Функцію `dispatch`, яка надсилає дії в редюсер.\\n\\nПростий приклад лічильника:\\n\\nКоли варто використовувати `useReducer` замість `useState`?\\n`useState` відмінний для простого стану — наприклад, щоб зберігати єдине значення або примітивну структуру даних. Однак `useReducer` стає кращим вибором у таких випадках:\\n- Стан має складну структуру. Наприклад, якщо потрібно керувати формою з безліччю полів, валідацією й залежними значеннями.\\n- Логіка оновлення стану складна. Якщо зміни стану залежать від попереднього стану або потребують обробки безлічі умов, редюсер допомагає краще організувати код.\\n- Потрібно мінімізувати повторні рендери. `useReducer` дає змогу згрупувати кілька змін стану в одне оновлення, що може покращити продуктивність.\\n\\nПриклад складної форми з `useReducer`:\\n\\nКоли варто використовувати `useReducer` замість Redux?\\nRedux — інструмент задля керування глобальним станом застосунку, але він потрібний не завжди. `useReducer` може бути відмінною альтернативою в таких випадках:\\n- Стан локальний. Якщо стан потрібний лише всередині одного компонента або невеликої групи компонентів, `useReducer` буде простішим і зручнішим.\\n- Вам не потрібні додаткові можливості Redux. Наприклад, якщо ви не потребуєте middleware (як-от Redux Thunk або Saga), DevTools або зневадження з подорожами в часі.\\n- Ви хочете уникнути зайвої складності. Redux потребує налаштування стора, дій і редюсерів, що може бути надмірним для невеликих проєктів.\\n\\nКоли обирати Redux:\\n- Глобальний стан. Якщо стан має бути доступний у багатьох частинах застосунку.\\n- Складні побічні ефекти. Наприклад, асинхронні запити, які обробляють через middleware.\\n- Інструменти розробника. Redux DevTools надають потужні можливості зневадження.\\n\\nПідсумовуючи:\\n\\n- `useState` — для простого стану (наприклад, прапорців, лічильників).\\n- `useReducer` — для складного стану (форм, багатокрокових процесів).\\n- Redux — для глобального стану й складніших сценаріїв.\",\"import { useReducer } from 'react';\\n\\nfunction counterReducer(state, action) {\\n    switch (action.type) {\\n        case 'increment':\\n            return { count: state.count + 1 };\\n        case 'decrement':\\n            return { count: state.count - 1 };\\n        default:\\n            return state;\\n    }\\n}\\n\\nfunction Counter() {\\n    const [state, dispatch] = useReducer(counterReducer, { count: 0 });\\n\\n    return (\\n        <div>\\n            <p>Count: {state.count}</p>\\n            <button onClick={() => dispatch({ type: 'increment' })}>+</button>\\n            <button onClick={() => dispatch({ type: 'decrement' })}>-</button>\\n        </div>\\n    );\\n}\\n\\nfunction formReducer(state, action) {\\n    switch (action.type) {\\n        case 'setUsername':\\n            return { ...state, username: action.payload };\\n        case 'setPassword':\\n            return { ...state, password: action.payload };\\n        case 'validate':\\n            return { ...state, errors: validateForm(state) };\\n        case 'submit':\\n            return { ...state, isSubmitting: true };\\n        default:\\n            return state;\\n    }\\n}\\n\\nfunction Form() {\\n    const [state, dispatch] = useReducer(formReducer, {\\n        username: '',\\n        password: '',\\n        errors: {},\\n        isSubmitting: false,\\n   });\\n\\n    const handleSubmit = (e) => {\\n        e.preventDefault();\\n        dispatch({ type: 'validate' });\\n        if (Object.keys(state.errors).length === 0) {\\n            dispatch({ type: 'submit' });\\n        }\\n   };\\n\\n    return (\\n        <form onSubmit={handleSubmit}>\\n            <input\\n              value={state.username}\\n              onChange={(e) => dispatch({ type: 'setUsername', payload: e.target.value })}\\n            />\\n            {state.errors.username && <p>{state.errors.username}</p>}\\n            <button disabled={state.isSubmitting}>Submit</button>\\n        </form>\\n    );\\n}\"],[2856,\"Flux — архітектура, щоб керувати станом у застосунках. Дані потрапляють у стор так:\\n\\n- Компонент викликає action.\\n\\n- Dispatcher отримує action і передає його кожному стору.\\n\\n- Стор оновлює свої дані й сповіщає компоненти.\\n\\n- Компоненти перемальовуються з новими даними.\",\"Основні частини Flux\\n\\n- Action — об'єкт із типом (`type`) й даними (`payload`), який описує, що сталося (наприклад, `{ type: 'ADD_TODO', text: '...' }`).\\n\\n- Dispatcher — центральний «диспетчер», який передає action кожному стору.\\n\\n- Store — сховище даних (як стан у Redux). Слухає actions й оновлює себе.\\n\\n- View (React-компоненти) — відображає дані зі стору й запускає actions.\\n\\nЯк дані потрапляють у стор?\\n\\n- Користувач клікає кнопку в компоненті:\\n\\n- Компонент викликає action creator:\\n\\n- Dispatcher надсилає action кожному стору:\\n\\n- Компоненти підписані на зміни стору й оновлюються:\\n\\nFlux проти Redux\\n\\n- У Redux один стор, тимчасом як у Flux їх кілька.\\n\\n- У Redux немає Dispatcher; його заміняє редюсер.\\n\\n- Flux простіший для малих застосунків, Redux — для складних.\\n\\nПриклад архітектури Flux\\n\\n- `key` у React мають бути стабільними — випадкові значення ламають логіку оновлення.\\n\\n- Flux — однонапрямлений потік даних: Action → Dispatcher → Store → View.\\n\\n- Стор оновлюють лише через actions, що робить код передбачуваним.\",\"<button onClick={() => addTodo('Buy milk')}>Add</button>\\n\\nfunction addTodo(text) {\\n  AppDispatcher.dispatch({\\n    type: 'ADD_TODO',\\n    text: text\\n  });\\n}\\n\\n// An example of a store (TodoStore)\\nTodoStore.dispatchToken = AppDispatcher.register(action => {\\n  switch (action.type) {\\n    case 'ADD_TODO':\\n      _todos.push({ text: action.text, completed: false });\\n      TodoStore.emitChange(); // We notify the components\\n      break;\\n  }\\n});\\n\\nTodoStore.addChangeListener(this._onChange);\\n\\n// The Dispatcher\\nconst AppDispatcher = new Flux.Dispatcher();\\n// The Store\\nconst TodoStore = {\\n  _todos: [],\\n  emitChange() { /* Notifying the components */ },\\n  addChangeListener(callback) { /* The subscription */ }\\n};\\n// The Action\\nfunction addTodo(text) {\\n  AppDispatcher.dispatch({ type: 'ADD_TODO', text });\\n}\"],[2857,\"- Глобальні змінні — вони не запускають повторного рендера, і зміни важко відстежувати.\\n- Контекст — зручний, щоб передавати дані без prop drilling.\\n- State Manager (Redux, MobX) — передбачуваність, подорожі в часі (зневадження), масштабованість.\",\"1. Проблема з глобальними змінними\\n\\nПроблеми:\\n- React не дізнається, що змінна змінилася → повторного рендера немає.\\n- Тримати контроль над залежностями важко.\\n\\n2. Рішення: React Context\\nВін передає дані деревом компонентів без явного передавання пропсів.\\n\\nПриклад:\\n\\nПереваги:\\n- Ми уникаємо prop drilling (A → B → C → D).\\n- Локальний стан на рівні застосунку.\\n\\nНедоліки:\\n- Кожний споживач перерендерюється при зміні.\\n\\n3. State Manager (Redux, MobX, Zustand)\\nПриклад на Redux:\\n\\nЧому?\\n- Централізований стан — єдине джерело істини.\\n- Інструменти розробника — логування, скасування дій.\\n- Оптимізації — цілеспрямовані підписки на зміни.\\n\\nВисновок:\\n- Для невеликих проєктів достатньо контексту.\\n- Для складних — Redux/Zustand.\\n- Глобальні змінні — лише для статичних даних.\",\"let user = null;  \\n\\n// Component A  \\nuser = { name: 'Alice' };  \\n\\n// Component B  \\nconsole.log(user); // Sometimes current, sometimes not\\n\\nconst UserContext = createContext();  \\n\\nfunction App() {  \\n    const [user, setUser] = useState(null);  \\n    return (  \\n        <UserContext.Provider value={{ user, setUser }}>  \\n            <Header />  \\n        </UserContext.Provider>  \\n    );  \\n}  \\n\\nfunction Header() {  \\n    const { user } = useContext(UserContext);  \\n    return <div>{user?.name}</div>;  \\n}\\n\\n// The store  \\nconst store = configureStore({ reducer: userReducer });  \\n\\n// A component  \\nconst user = useSelector(state => state.user);\"],[2858,\"`enhancer` — функція, яка розширює можливості сховища Redux — наприклад, додає middleware або інструменти розробника.\",\"Особливості:\\n\\n- Визначення\\n\\n- `enhancer` — функція вищого порядку для `createStore`.\\n\\n- Приклади використання\\n\\n- Під'єднання `redux-devtools`.\\n\\n- Застосування middleware.\\n\\n- Синтаксис\\n\\nПриклад із DevTools:\\n\\nВисновок:\\nEnhancers дають змогу налаштувати сховище, не змінюючи логіки редюсерів.\",\"const store = createStore(reducer, enhancer);\\n\\nconst store = createStore(\\n  reducer,\\n  window.__REDUX_DEVTOOLS_EXTENSION__ && window.__REDUX_DEVTOOLS_EXTENSION__()\\n);\"],[2859,\"Можна використати черги, middleware або відкладені виклики (`setTimeout`, `Promise`), щоб керувати порядком dispatch.\",\"Способи:\\n\\n- Асинхронна затримка\\n\\n- Middleware\\n\\n- Ми обгортаємо `dispatch` у логіку з чергою.\\n\\n- Saga/Thunk\\n\\n- Ми керуємо порядком через ефекти або через ланцюжок промісів.\\n\\nПриклад middleware:\\n\\nВисновок:\\nПріоритизацію dispatch найчастіше роблять на рівні middleware або асинхронних actions.\",\"setTimeout(() => store.dispatch(action), 0);\\n\\nconst delayDispatch = store => next => action => {\\n  if (action.meta?.delay) {\\n    return setTimeout(() => next(action), action.meta.delay);\\n  }\\n  return next(action);\\n};\"],[2860,\"`redux-thunk` дає змогу надсилати функції задля асинхронної логіки; `redux-saga` дає змогу керувати складними потоками подій за допомогою генераторів.\",\"Redux Thunk:\\n\\n- Дає змогу надіслати функцію `(dispatch, getState) => {}`.\\n\\n- Простий і зрозумілий для малих проєктів.\\n\\nRedux Saga:\\n\\n- Працює через генератори.\\n\\n- Придатна для складних сценаріїв із побічними ефектами.\\n\\n- Її легко тестувати.\\n\\nПриклад Thunk:\\n\\nВисновок:\\nThunk — для простих асинхронних викликів, Saga — для складної бізнес-логіки й керування побічними ефектами.\",\"const fetchData = () => async dispatch => {\\n  dispatch({ type: 'loading' });\\n  const data = await api.get();\\n  dispatch({ type: 'success', payload: data });\\n};\"],[2861,\"Redux Toolkit забезпечує передбачуване керування станом із незмінними оновленнями. MobX використовує спостережувані об'єкти задля реактивного програмування. React Query спеціалізується на керуванні серверним станом і кешуванні.\",\"Redux Toolkit:\\n- Централізований стор стану\\n- Незмінні оновлення через редюсери\\n- Вбудована підтримка асинхронних операцій\\n- Інструменти розробника задля зневадження\\n\\nMobX:\\n- Реактивне програмування\\n- Автоматичне відстежування залежностей\\n- Мінімум шаблонного коду\\n- М'яка крива навчання\\n\\nReact Query:\\n- Спеціалізація на серверному стані\\n- Автоматичне кешування й інвалідація\\n- Фонові оновлення даних\\n- Пагінація й нескінченні запити\\n\\nПриклад на Redux Toolkit:\\n\\nКоли що використовувати:\\n- Redux Toolkit — для складного клієнтського стану\\n- MobX — для реактивних застосунків\\n- React Query — для роботи з API й кешування\",\"import { createSlice } from '@reduxjs/toolkit';\\n\\nconst counterSlice = createSlice({\\n  name: 'counter',\\n  initialState: 0,\\n  reducers: {\\n    increment: state => state + 1,\\n    decrement: state => state - 1\\n  }\\n});\"],[2862,\"React Context — вбудований у React механізм, щоб передавати дані деревом компонентів без потреби писати пропси на кожному рівні. Redux — незалежна бібліотека задля керування станом усього застосунку, яка надає строгі правила його зміни (через дії й редюсери) й потужні інструменти зневадження. Context розв'язує проблему «prop drilling», а Redux — проблему передбачуваного керування складним глобальним станом.\",\"Обидва інструменти допомагають працювати з даними, але роблять це на різних рівнях і з різними цілями.\\n\\nReact Context\\n- Що це: механізм, щоб передавати дані навпростець. Він дає змогу створити «контекст» (джерело даних) на верхньому рівні й споживати ці дані в будь-якому дочірньому компоненті, де б він не був, обходячи проміжні компоненти.\\n- Як його використовують: його створюють за допомогою `React.createContext()`. Провайдер (`<MyContext.Provider>`) обгортає частину дерева й передає значення вниз. Компоненти-споживачі використовують хук `useContext(MyContext)`, щоб отримати доступ до цього значення.\\n- Основна мета: уникнути «prop drilling» (передавання пропсів через безліч непричетних компонентів).\\n\\nRedux\\n- Що це: бібліотека задля керування станом застосунку, заснована на принципах Flux. Вона зберігає весь стан в єдиному незмінному сторі.\\n- Як його використовують: стан змінюють лише через «дії» (actions) й «редюсери» — чисті функції, які передбачувано обчислюють новий стан із попереднього й дії.\\n- Основна мета: забезпечити передбачуваний, централізований і зневаджуваний спосіб керувати складним станом, який активно використовують у різних частинах застосунку.\",null],[2863,\"Context не призначений, щоб часто оновлювати великі обсяги даних. Коли значення в контексті змінюється, React перерендерює кожний компонент, який його споживає, навіть якщо вони використовують лише ту частину даних, яка не змінилася. Redux розв'язує цю проблему за допомогою «підписок»: компонент перерендерюється лише тоді, коли змінюються саме ті дані, на які він підписаний. Це дає оптимізацію продуктивності у великих застосунках\",\"Хоча Context відмінно справляється з передаванням вниз статичних або рідко змінюваних даних (наприклад, теми UI або даних користувача), використання його для стану, який часто змінюється, має серйозні недоліки.\\n\\nПроблеми використання Context для глобального стану:\\n- Немає селекторів: компонент, який використовує `useContext`, перерендерюється на будь-яку зміну значення контексту, навіть якщо йому потрібна лише невелика частина цих даних. Механізму підписки лише на окреме поле немає.\\n- Оптимізація складна: щоб уникати зайвих повторних рендерів, доводиться вручну розділяти контексти на дрібніші (`UserContext`, `PostsContext`, `UiContext`) або використовувати складні обгортки з `React.memo`. Це збільшує складність коду.\\n- Логіка оновлення стану: у Context логіку оновлення стану (еквівалент редюсерів Redux) доводиться реалізовувати вручну, зазвичай за допомогою `useState` або `useReducer` усередині провайдера.\\n\\nОптимізації, які дає Redux:\\n- Підписка на конкретні дані: бібліотека `react-redux` надає хук `useSelector`, який дає компонентові змогу підписатися лише на одну конкретну частину стану у сторі. Компонент буде перерендерений лише тоді, коли саме ця частина змінилася.\\n- Стабільність посилань: за замовчуванням `useSelector` використовує строге порівняння (`===`), що запобігає зайвим повторним рендерам, якщо дані не змінилися.\\n- Єдине джерело істини (Single Source of Truth): архітектура Redux передбачувана й полегшує зневадження. Легко відстежити, яка дія призвела до зміни стану.\\n- Middleware: Redux надає потужний механізм middleware (наприклад, `redux-thunk`, `redux-saga`), щоб однаково обробляти побічні ефекти (асинхронні запити, логування тощо).\\n\\nВисновок: Context — відмінний інструмент для власної ніші (дані, які передають навпростець і які рідко змінюються). Redux — спеціалізована, оптимізована бібліотека задля керування складним станом великого застосунку, який часто змінюється, де критичні продуктивність і передбачуваність.\",null],[2864,\"Коли action надсилають у Redux, відбувається таке: action передають у сховище, далі через middleware (якщо воно є), далі в кореневий редюсер, який передає його кожному дочірньому редюсерові. Після того як стан оновили, викликають підписників (subscribe), які сповіщають React-компоненти про зміни. Компоненти перемальовуються з новими даними.\",\"Механізм dispatch у Redux являє собою передбачуваний потік даних через кілька стадій.\\nПовний процес dispatch:\\n\\n- Ініціація dispatch:\\n\\n- Виклик `store.dispatch(action)`\\n\\n- Action має бути простим JavaScript-об'єктом із полем `type`\\n\\n- Обробка в middleware:\\n\\n- Action проходить через ланцюжок middleware\\n\\n- Кожне middleware може змінити, журналювати або скасувати action\\n\\n- Thunk middleware обробляє асинхронні операції\\n\\n- Виклик редюсерів:\\n\\n- Сховище передає action кореневому редюсерові\\n\\n- Кореневий редюсер делегує обробку відповідним дочірнім редюсерам\\n\\n- Кожний редюсер отримує action, але обробляє лише ті типи, які йому відповідають\\n\\nПриклад потоку даних:\\n\\n- Оновлення стану:\\n\\n- Редюсери повертають новий стан\\n\\n- Сховище заміняє поточний стан новим\\n\\n- Посилання на об'єкти стану змінюються лише на справжніх змінах\\n\\n- Сповіщення підписників:\\n\\n- Сховище викликає кожну функцію-підписника\\n\\n- React-компоненти отримують оновлені пропси\\n\\n- Відбувається повторний рендер зачеплених компонентів\",\"// 1. Creating the action\\nconst action = { type: 'USER_LOGGED_IN', payload: { userId: 123 } };\\n\\n// 2. The dispatch\\nstore.dispatch(action);\\n\\n// 3. The middleware (the example of redux-thunk)\\nconst thunkMiddleware = store => next => action => {\\n  if (typeof action === 'function') {\\n    return action(store.dispatch, store.getState);\\n  }\\n  return next(action);\\n};\\n\\n// 4. The reducer\\nconst rootReducer = (state = {}, action) => {\\n  switch (action.type) {\\n    case 'USER_LOGGED_IN':\\n      return { ...state, user: action.payload };\\n    default:\\n      return state;\\n  }\\n};\"],[2865,\"Редюсер у Redux служить, щоб визначати, як стан застосунку змінюється у відповідь на actions. Це чиста функція, яка приймає поточний стан й action і повертає новий стан. Редюсери мають бути немутабельними — вони не змінюють початкового стану, а повертають новий об'єкт з оновленими даними.\",\"Редюсер — центральна концепція Redux, відповідальна за перетворення стану застосунку.\\nОсновні характеристики редюсерів:\\nЧистота функції:\\n\\n- Вони не мають мати побічних ефектів\\n\\n- Вони не мають змінювати своїх аргументів\\n\\n- Вони не мають виконувати асинхронних операцій\\n\\n- Вони мають повертати той самий результат для тих самих аргументів\\n\\nНемутабельність:\\n\\n- Вони завжди повертають новий об'єкт стану\\n\\n- Вони не змінюють наявних об'єктів і масивів\\n\\n- Вони використовують оператор розгортання або бібліотеки на кшталт Immer задля оновлень\\n\\nСтруктура редюсера:\\n\\nРоль в архітектурі Redux:\\nКерування станом:\\n\\n- Визначає можливі зміни стану\\n\\n- Забезпечує передбачуваність змін\\n\\n- Централізує логіку оновлення стану\\n\\nПоділ відповідальності:\\n\\n- Кожний редюсер відповідає за власну частину стану\\n\\n- Поєднання їх через combineReducers\\n\\n- Легкість тестування й зневадження\\n\\nПереваги підходу:\\n\\n- Передбачуваність змін стану\\n\\n- Легкість зневадження (time-travel debugging)\\n\\n- Простота тестування\\n\\n- Масштабованість застосунку\",\"// An example of a reducer\\nconst initialState = {\\n  items: [],\\n  loading: false,\\n  error: null\\n};\\n\\nconst itemsReducer = (state = initialState, action) => {\\n  switch (action.type) {\\n    case 'ITEMS_LOADING':\\n      return {\\n        ...state,\\n        loading: true,\\n        error: null\\n      };\\n    case 'ITEMS_LOADED':\\n      return {\\n        ...state,\\n        items: action.payload,\\n        loading: false\\n      };\\n    case 'ITEMS_ERROR':\\n      return {\\n        ...state,\\n        loading: false,\\n        error: action.payload\\n      };\\n    default:\\n      return state;\\n  }\\n};\"],[2866,\"Redux не може працювати без редюсерів — коли сховище створюють, кореневий редюсер завжди треба передати. Якщо ви передасте undefined або null як редюсер, Redux кине помилку на стадії, де сховище створюють. У режимі розробки Redux виконує додаткові перевірки й попереджає вас про неналежне налаштування.\",\"Redux має строгі вимоги до свого налаштування й явно вказує на проблеми з налаштуванням.\\nПроцес ініціалізації сховища:\\nСтворення сховища:\\n\\n- Функція `createStore` потребує обов'язкового параметра `reducer`\\n\\n- За відсутності редюсера помилка виникає на стадії, де функцію викликають\\n\\n- Redux не створює сховища за замовчуванням без явно зазначеного редюсера\\n\\nПриклади помилкових сценаріїв:\\n\\nВалідація в режимі розробки:\\nПеревірки Redux:\\n\\n- Валідація типу переданого редюсера (він має бути функцією)\\n\\n- Перевірка початкового стану на першому виклику\\n\\n- Попередження про можливі проблеми з налаштуванням\\n\\nПравильне налаштування:\\n\\nОбробка граничних випадків:\\nПорожній редюсер:\\n\\n- Редюсер може не обробляти жодних actions\\n\\n- Але він завжди має повертати стан\\n\\n- Початковий стан обов'язковий — через параметр за замовчуванням\\n\\nПоєднані редюсери:\\n\\n- `combineReducers` перевіряє, що кожний переданий редюсер — функція\\n\\n- Створює кореневий редюсер, який делегує actions\\n\\n- Навіть коли поєднують один редюсер, він має бути валідним\",\"// AN ERROR: the reducer has not been specified\\nconst store = createStore(); // TypeError\\n\\n// AN ERROR: the reducer is undefined\\nconst store = createStore(undefined); // An Error in development\\n\\n// AN ERROR: an incorrect reducer\\nconst store = createStore('not_a_function'); // An Error\\n\\n// A minimal working reducer\\nconst rootReducer = (state = {}, action) => {\\n  return state;\\n};\\n\\n// Creating the store with a valid reducer\\nconst store = createStore(rootReducer);\"],[2867,\"Перед обробкою в редюсерах action проходить через кожне middleware, установлене у сховищі. Middleware може модифікувати, журналювати, затримати або цілковито скасувати action. Також через middleware на кшталт redux-thunk або redux-saga можна виконувати побічні ефекти й асинхронні операції.\",\"Між надсиланням action й його обробкою в редюсерах відбувається кілька важливих стадій.\\nПроцес обробки action:\\n\\n- Надсилання action:\\n\\n- Виклик `store.dispatch(action)`\\n\\n- Початок процесу обробки\\n\\n- Ланцюжок middleware:\\n\\n- Action проходить через кожне middleware одне за одним\\n\\n- Кожне middleware отримує функцію `next`, щоб передати action далі\\n\\n- Middleware може виконувати над action різні операції\\n\\nПриклад ланцюжка middleware:\\n\\nТипи операцій у middleware:\\nМодифікація action:\\n\\n- Додавання додаткових даних\\n\\n- Перетворення структури action\\n\\n- Створення кількох actions з одного\\n\\nАсинхронні операції:\\n\\n- Виклики API перед тим, як action передадуть далі\\n\\n- Затримка dispatch\\n\\n- Умовний dispatch на основі поточного стану\\n\\nМоніторинг і журналювання:\\n\\n- Трасування actions задля зневадження\\n\\n- Метрики продуктивності\\n\\n- Обробка помилок\\n\\nПісля middleware:\\n\\n- Action передають у редюсери лише тоді, коли його не скасували\\n\\n- Кожне middleware має викликати `next(action)`, щоб продовжити ланцюжок\\n\\n- Результатом middleware може бути модифікований action\",\"// Simple logging middleware\\nconst loggerMiddleware = store => next => action => {\\n  console.log('Dispatching:', action);\\n  const result = next(action);\\n  console.log('Next state:', store.getState());\\n  return result;\\n};\\n\\n// Thunk middleware for asynchronous operations\\nconst thunkMiddleware = store => next => action => {\\n  if (typeof action === 'function') {\\n    return action(store.dispatch, store.getState);\\n  }\\n  return next(action);\\n};\\n\\n// Applying the middleware\\nconst store = createStore(\\n  rootReducer,\\n  applyMiddleware(thunkMiddleware, loggerMiddleware)\\n);\"],[2868,\"`rootReducer` передає кожний action УСІМ дочірнім редюсерам, незалежно від кількості редюсерів і від того, чи тип action збігається. Кожний редюсер отримує action і сам вирішує, чи йому потрібно оновити свій стан. У switch/case гілка default повертає поточний стан незмінним.\",\"Redux використовує патерн, за якого actions транслюють кожному редюсерові, а не обробляють за принципом першого збігу.\\nМеханізм combineReducers:\\nСтворення кореневого редюсера:\\n\\n- `combineReducers` створює функцію, яка викликає кожний дочірній редюсер\\n\\n- Кожний редюсер отримує ту саму копію action\\n\\n- Редюсери працюють незалежно одне від одного\\n\\nПриклад структури:\\n\\nОбробка action:\\nДля action `USER_UPDATE`:\\n\\n- `userReducer` обробляє action і повертає новий стан\\n\\n- `postsReducer` отримує той самий action, але повертає поточний стан (випадок default)\\n\\n- Кореневий редюсер поєднує результати\\n\\nДля action `POST_ADD`:\\n\\n- `userReducer` повертає поточний стан (випадок default)\\n\\n- `postsReducer` обробляє action і повертає новий стан\\n\\nПереваги підходу:\\nГнучкість:\\n\\n- Кілька редюсерів можуть відповідати на один тип action\\n\\n- Легко додавати нову функціональність, не змінюючи наявних редюсерів\\n\\n- Передбачуваність поведінки системи\\n\\nПродуктивність:\\n\\n- Redux оптимізований задля швидкого проходу через кожний редюсер\\n\\n- Більшість редюсерів швидко повертають стан у випадку default\\n\\n- У production використовують різні оптимізації\\n\\nРекомендації:\\n\\n- Тримайте редюсери простими й зосередженими на власній області\\n\\n- Використовуйте випадок default, щоб повернути стан незмінним\\n\\n- Уникайте складної логіки в редюсерах\",\"const userReducer = (state = {}, action) => {\\n  switch (action.type) {\\n    case 'USER_UPDATE':\\n      return { ...state, ...action.payload };\\n    default:\\n      return state; // The state unchanged, for the other actions\\n  }\\n};\\n\\nconst postsReducer = (state = [], action) => {\\n  switch (action.type) {\\n    case 'POST_ADD':\\n      return [...state, action.payload];\\n    default:\\n      return state; // The state unchanged, for the other actions\\n  }\\n};\\n\\nconst rootReducer = combineReducers({\\n  user: userReducer,\\n  posts: postsReducer\\n});\"],[2869,\"Middleware виконується після того, як `dispatch()` викликали, але перед тим, як action дійде до редюсерів. Воно сидить посередині процесу dispatch, між ініціацією action і фактичним оновленням стану. Кожне middleware в ланцюжку отримує action і вирішує, чи передати його далі, модифікувати чи скасувати.\",\"Middleware в Redux виконують у строго визначеній послідовності між надсиланням action й його обробкою в редюсерах.\\nПорядок виконання:\\n\\n- Надсилання action: `store.dispatch(action)`\\n\\n- Обробка в middleware: action проходить через увесь ланцюжок middleware\\n\\n- Досягнення редюсерів: після всього middleware action доходить до редюсерів\\n\\n- Оновлення стану: редюсери повертають новий стан\\n\\nДетальний процес middleware:\\n\\nКлючові аспекти:\\n\\n- Перед next: код виконується ПЕРЕД тим, як action передадуть наступному middleware чи редюсерам\\n\\n- Після next: код виконується ПІСЛЯ того, як усе наступне middleware й редюсери завершили свою роботу\\n\\n- Контроль потоку: middleware може цілковито зупинити передавання action далі\",\"// An example of a chain of middleware\\nconst middleware1 = store => next => action => {\\n  console.log('Middleware 1 before next');\\n  const result = next(action);\\n  console.log('Middleware 1 after next');\\n  return result;\\n};\\n\\nconst middleware2 = store => next => action => {\\n  console.log('Middleware 2 before next');\\n  const result = next(action);\\n  console.log('Middleware 2 after next');\\n  return result;\\n};\\n\\n// The order of execution on a dispatch:\\n// 1. \\\"Middleware 1 before next\\\"\\n// 2. \\\"Middleware 2 before next\\\" \\n// 3. The reducers handle the action\\n// 4. \\\"Middleware 2 after next\\\"\\n// 5. \\\"Middleware 1 after next\\\"\"],[2870,\"Щоб пріоритизувати dispatch, можна використати `createListenerMiddleware` із Redux Toolkit, який дає змогу відкласти виконання actions. Також можна використати підходи на основі Promise або власне middleware, яке накопичує actions і виконує їх у потрібному порядку. Найпростіший спосіб — надіслати останній action у колбеку, після того як попередні операції завершилися.\",\"Є кілька підходів, щоб забезпечити виконання actions у певному порядку.\\nМетоди пріоритизації:\\n1. Підхід із createListenerMiddleware:\\n\\n2. Підхід на основі Promise:\\n\\n3. Власна черга actions:\\n\\nПрактичний приклад:\\n\\nРекомендації:\\n\\n- Використовуйте офіційне `createListenerMiddleware` для складних сценаріїв\\n\\n- Для простих випадків достатньо `setTimeout` із затримкою 0\\n\\n- Уникайте блокувальних операцій у головному потоці\",\"import { createListenerMiddleware } from '@reduxjs/toolkit';\\n\\nconst listenerMiddleware = createListenerMiddleware();\\n\\n// A listener for a particular action\\nlistenerMiddleware.startListening({\\n  actionCreator: someAction,\\n  effect: async (action, listenerApi) => {\\n    // We wait for the other operations to finish\\n    await listenerApi.condition((action, currentState) => {\\n      return currentState.someCondition === true;\\n    });\\n    \\n    // Then we dispatch the final action\\n    listenerApi.dispatch(finalAction());\\n  }\\n});\\n\\n// A dispatch that is always performed last\\nconst dispatchLast = (action) => (dispatch, getState) => {\\n  return Promise.resolve().then(() => {\\n    dispatch(action);\\n  });\\n};\\n\\n// Using it\\nstore.dispatch(dispatchLast(myAction()));\\n\\nconst actionQueueMiddleware = store => next => action => {\\n  if (action.meta?.priority === 'last') {\\n    // We defer the execution until the next tick\\n    setTimeout(() => {\\n      next(action);\\n    }, 0);\\n    return;\\n  }\\n  return next(action);\\n};\\n\\n// Middleware for a deferred dispatch\\nconst deferredDispatchMiddleware = store => {\\n  let pendingActions = [];\\n  let isProcessing = false;\\n\\n  return next => action => {\\n    if (action.type === 'DEFERRED_ACTION') {\\n      pendingActions.push(action.payload);\\n      \\n      if (!isProcessing) {\\n        isProcessing = true;\\n        // We perform them in the next tick of the event loop\\n        setTimeout(() => {\\n          pendingActions.forEach(deferredAction => {\\n            store.dispatch(deferredAction);\\n          });\\n          pendingActions = [];\\n          isProcessing = false;\\n        }, 0);\\n      }\\n      return;\\n    }\\n    return next(action);\\n  };\\n};\"],[2871,\"Час кліку по кнопці в Redux найкраще журналювати за допомогою middleware. Middleware — точка, через яку проходить кожний action, перш ніж він дійде до редюсера. Усередині middleware можна перехопити потрібний вам action (наприклад, `'BUTTON_CLICKED'`) і журналювати поточний час (`console.log(Date.now())` або надіслати його в сервіс журналювання). Це централізований й узгоджений підхід.\",\"В архітектурі Redux дані течуть в одному напрямі: `View -> Action -> Reducer -> Store -> View`. Middleware надає потужний механізм, щоб розширити цей потік.\\nЧому middleware — найкраще місце?\\n\\n- Поділ відповідальності: логіка журналювання не забруднює ні компонентів (UI), ні редюсерів (логіки оновлення стану).\\n\\n- Централізація: ви можете журналювати кожний action в одному місці, а не шукати їх по всьому коду застосунку.\\n\\n- Доступ до повного action: middleware має доступ до об'єкта `action`, що дає змогу журналювати не лише час, а й payload.\\n\\nЯк це реалізувати?\\n\\n- Створіть власне middleware:\\njavascript\\n\\n- Під'єднайте middleware до сховища:\\njavascript\\n\\nАльтернативні (менш бажані) місця:\\n\\n- У компоненті (в обробнику кліку): порушує принцип поділу відповідальності, ускладнює тестування.\\n\\n- У редюсері: редюсери мають бути чистими функціями, а журналювання — побічний ефект.\\n\\nВисновок\\nЩоб журналювати actions, включно з часом кліків, використовуйте middleware Redux. Це стандартний підхід, який легко підтримувати, і найчистіший з архітектурного погляду.\",\"const loggerMiddleware = store => next => action => {\\n  // We log the time and the action BEFORE it is handled by the reducer\\n  if (action.type === 'BUTTON_CLICKED') {\\n    console.log('Button clicked at:', new Date().toISOString());\\n  }\\n  // We pass the action to the next middleware in the chain, or to the reducer\\n  return next(action);\\n};\\n\\nimport { createStore, applyMiddleware } from 'redux';\\nimport rootReducer from './reducers';\\n\\nconst store = createStore(\\n  rootReducer,\\n  applyMiddleware(loggerMiddleware) // and other middleware...\\n);\"],[2872,\"Щоб замемоїзувати виклик селектора в Redux, використовують бібліотеку Reselect. Вона дає змогу створювати «мемоїзовані» селектори, які обчислюють своє значення заново лише тоді, коли вхідні дані селектора (його аргументи) змінюються. Якщо аргументи залишилися тими самими, селектор повертає закешований результат, що запобігає дорогим обчисленням і надлишковим повторним рендерам компонентів.\",\"Мемоїзація — техніка оптимізації, яка кешує результати дорогих викликів функцій.\\nПроблема без мемоїзації\\nУявіть селектор, який фільтрує й сортує великий список:\\n\\nЯкщо компонент під'єднується до сховища за допомогою `connect`, цей селектор виконуватимуть на кожному оновленні стану Redux, навіть якщо це оновлення не пов'язане з `todos` або `visibilityFilter`.\\nРішення з Reselect\\nReselect надає функцію `createSelector`, щоб створювати мемоїзовані селектори.\\n\\n- Установіть Reselect: `npm install reselect`\\n\\n- Створіть мемоїзований селектор:\\njavascript\\n\\nЯк це працює\\nНа першому виклику `getVisibleTodos(state)` Reselect виконує функцію-перетворювач і кешує результат. На наступних викликах вона спочатку перевіряє, чи змінилися результати `getTodos(state)` й `getVisibilityFilter(state)`. Якщо ні, вона повертає закешоване значення.\\nВисновок\\nВикористовуйте Reselect, щоб мемоїзувати селектори, які виконують складні обчислення або похідні перетворення над станом. Це значно підвищує продуктивність, особливо у великих застосунках, скорочуючи кількість непотрібних обчислень і повторних рендерів задіяних компонентів.\",\"const getVisibleTodos = (state) => {\\n  // This computation is performed on EVERY call of the selector,\\n  // even if `state.todos` and `state.visibilityFilter` have not changed.\\n  const { todos, visibilityFilter } = state;\\n  return todos.filter(todo => {\\n    switch (visibilityFilter) {\\n      case 'SHOW_COMPLETED':\\n        return todo.completed;\\n      case 'SHOW_ACTIVE':\\n        return !todo.completed;\\n      default:\\n        return true;\\n    }\\n  });\\n};\\n\\nimport { createSelector } from 'reselect';\\n\\n// The simple selectors, which merely extract a piece of the state\\nconst getTodos = state => state.todos;\\nconst getVisibilityFilter = state => state.visibilityFilter;\\n\\n// The memoized selector\\nexport const getVisibleTodos = createSelector(\\n  [getTodos, getVisibilityFilter], // The array of input selectors\\n  (todos, visibilityFilter) => { // The transformer function\\n    // The expensive computation will be performed ONLY if todos or visibilityFilter has changed\\n    return todos.filter(todo => {\\n      switch (visibilityFilter) {\\n        case 'SHOW_COMPLETED':\\n          return todo.completed;\\n        case 'SHOW_ACTIVE':\\n          return !todo.completed;\\n        default:\\n          return true;\\n      }\\n    });\\n  }\\n);\"],[2873,\"Redux дає строгішу, передбачуванішу модель керування станом.\\nВін краще тримає оновлення й повторні рендери під контролем.\\nRedux масштабується краще за Context.\\nТому його частіше обирають для великих застосунків.\",\"Context і Redux розв'язують схожу задачу, але на різному рівні складності.\\nВизначення\\nRedux — централізований менеджер стану з явним потоком даних і строгими правилами зміни стану.\\nПроблеми з Context у великих застосунках\\nКоли застосунок зростає:\\n\\n- Context починає оновлюватися часто\\n\\n- важко тримати залежності під контролем\\n\\n- складно оптимізувати повторні рендери\\n\\n- логіка зміни стану розмазується\\n\\nПереваги Redux\\nRedux надає:\\n\\n- єдине джерело істини\\n\\n- явні `action`\\n\\n- передбачувані `reducer`\\n\\n- зручне зневадження й журналювання\\n\\nЗміни стану стають прозорими й такими, що їх можна відстежити.\\nКонтроль повторних рендерів\\nRedux:\\n\\n- дає змогу підписатися лише на потрібні вам дані\\n\\n- мінімізує надлишкові оновлення\\n\\n- краще придатний для продуктивних UI\\n\\nКоли Context усе ж кращий\\nContext залишається добрим вибором для:\\n\\n- теми\\n\\n- локалізації\\n\\n- поточного користувача\\n\\n- глобальних даних, які змінюються рідко\\n\\nКороткий висновок\\nRedux віддають перевагу у великих застосунках через його передбачуваність, масштабованість і контроль оновлень. Context зручний, але має архітектурні обмеження.\",null],[2874,\"Редюсер — функція, яка описує, як стан застосунку змінюється.\\nВона приймає поточний стан й action.\\nРедюсер завжди повертає новий стан.\\nПобічні ефекти всередині редюсера заборонені.\",\"Редюсер — серце Redux; саме він визначає логіку зміни стану.\\nВизначення\\nРедюсер — чиста функція вигляду `(state, action) => newState`, яка описує, як стан має змінитися у відповідь на action.\\nЯк працює редюсер\\nАлгоритм простий:\\n\\n- Redux передає поточний `state`\\n\\n- Redux передає `action`\\n\\n- Редюсер аналізує тип action\\n\\n- Повертають новий стан\\n\\nЧому редюсер має бути чистим\\nРедюсер:\\n\\n- не змінює `state` напряму\\n\\n- не викликає API\\n\\n- не працює з таймерами\\n\\n- завжди повертає той самий результат для тих самих вхідних даних\\n\\nЦе робить поведінку застосунку передбачуваною.\\nРоль редюсера в архітектурі\\nРедюсер:\\n\\n- централізує бізнес-логіку\\n\\n- полегшує тестування\\n\\n- робить зміни стану прозорими\\n\\nКороткий висновок\\nРедюсер — чиста функція, яка описує, як стан змінюється з часом. Це фундамент передбачуваності Redux.\",\"function counterReducer(state = 0, action) {\\n  if (action.type === 'increment') {\\n    return state + 1;\\n  }\\n  return state;\\n}\"],[2875,\"Redux Toolkit полегшує роботу з Redux.\\nВін зменшує обсяг шаблонного коду.\\nRedux Toolkit підтримує найкращі практики.\\nСьогодні це рекомендований спосіб використовувати Redux.\",\"Класичний Redux потребує багато повторюваного коду, що часто призводить до помилок.\\nВизначення\\nRedux Toolkit — офіційний набір інструментів, який полегшує налаштування й використання Redux.\\nОсновні відмінності\\nRedux Toolkit:\\n\\n- налаштовує `store` автоматично\\n\\n- використовує `createSlice`\\n\\n- дає змогу безпечно писати «мутабельний» код\\n\\n- включає корисне middleware за замовчуванням\\n\\nЧому «мутабельний» код безпечний\\nRedux Toolkit використовує `Immer`, який:\\n\\n- дає змогу писати код наче з мутаціями\\n\\n- створює немутабельні копії під капотом\\n\\nПроблеми класичного Redux\\nУ класичному підході:\\n\\n- багато `action type`\\n\\n- багато `switch`\\n\\n- висока ймовірність помилок\\n\\n- код важче підтримувати\\n\\nКоли використовувати Redux Toolkit\\nСьогодні:\\n\\n- Redux Toolkit використовують майже завжди\\n\\n- класичний Redux зустрічають рідко\\n\\n- Toolkit вважають стандартом\\n\\nКороткий висновок\\nRedux Toolkit робить Redux простішим, безпечнішим і сучаснішим. Це рекомендований підхід для нових проєктів.\",\"const slice = createSlice({\\n  name: 'counter',\\n  initialState: 0,\\n  reducers: {\\n    increment: state => state + 1\\n  }\\n});\"],[2876,\"Селектори викликають на будь-якій зміні сховища, адже Redux не знає, які дані справді змінилися.\\nСховище повідомляє своїх підписників про будь-яке оновлення стану.\\nСелектори самі вирішують, чи змінився потрібний їм фрагмент.\\nЦе звичайна поведінка Redux.\",\"Redux використовує модель широкого сповіщення, а не точкових подій.\\nВизначення\\nСелектор — функція, яка видобуває частину даних зі стану сховища Redux.\\nЯк працює оновлення сховища\\nНа кожному `dispatch`:\\n\\n- редюсер повертає новий стан\\n\\n- сховище сповіщає кожного підписника\\n\\n- кожний підписник викликає свої селектори знову\\n\\nRedux не аналізує, які частини стану змінилися.\\nЧому це влаштовано саме так\\nТакий підхід:\\n\\n- робить реалізацію Redux простішою\\n\\n- робить поведінку передбачуваною\\n\\n- переносить оптимізацію на рівень селекторів\\n\\nРоль мемоїзації\\nАби уникати надлишкових обчислень:\\n\\n- використовують мемоїзовані селектори\\n\\n- застосовують `reselect`\\n\\nМемоїзація дає змогу:\\n\\n- повернути старе значення\\n\\n- запобігти надлишковому повторному рендеру\\n\\nЗв'язок із React\\nУ React:\\n\\n- `useSelector` порівнює результати селектора\\n\\n- там, де вони рівні за посиланням, повторного рендера не відбувається\\n\\nКороткий висновок\\nСелектори викликають завжди, але повторний рендер залежить від результату. Оптимізації досягають мемоїзацією селекторів.\",null],[2877,\"Менеджери стану живуть поза React, адже вони не залежать від його життєвого циклу й їх можна використовувати взагалі без React. React лише підписується на зміни в цих сховищах. Такий підхід дає змогу відділити керування станом від відображення UI. Саме тому їх називають зовнішнім сховищем.\",\"React і менеджери стану розв'язують різні задачі.\\nЩо робить React\\nПерш ніж перелічувати, важливо зафіксувати його роль:\\n\\n- React відповідає за рендеринг UI.\\n\\n- React відповідає на зміни `state` й `props`.\\n\\n- React не керує глобальним станом застосунку.\\n\\nЩо робить менеджер стану\\n\\n- Зберігає стан поза компонентами.\\n\\n- Надає API, щоб читати й змінювати дані.\\n\\n- Сповіщає своїх підписників про зміни.\\n\\nReact у цьому процесі:\\n\\n- Не знає, як зберігають стан.\\n\\n- Не знає, хто його змінює.\\n\\n- Лише відповідає на сповіщення.\\n\\nЧому це архітектурно правильно\\n\\n- Поділ відповідальності\\n\\n- UI окремо, бізнес-логіка окремо.\\n\\n- Придатність до повторного використання\\n\\n- сховище можна використовувати поза React (наприклад, у тестах).\\n\\n- Кілька споживачів\\n\\n- одне сховище може обслуговувати кілька дерев React.\\n\\nВисновок\\nМенеджери стану вважають зовнішніми щодо React, адже вони — незалежне джерело стану, а React лише інтегрується з ними через підписки.\",\"store.setState(nextState);\"],[2878,\"Redux побудований на архітектурному патерні Flux з однонапрямленим потоком даних. Стан зберігають в єдиному сховищі; зміни відбуваються лише через actions і редюсери. Компоненти не змінюють стану напряму, а лише ініціюють події. Це робить поведінку застосунку передбачуваною й зручною задля зневадження.\",\"Redux — не просто бібліотека, а певна архітектурна модель.\\nВизначення\\nВизначення: Flux — архітектурний патерн з однонапрямленим потоком даних, у якому стан змінюють централізовано й передбачувано.\\nЯк Flux реалізовано в Redux\\n\\n- Action\\n\\n- Описує, що сталося\\n\\n- Звичайний об'єкт із `type` і з полем даних\\n\\n- Reducer\\n\\n- Чиста функція\\n\\n- Приймає `state` й `action`\\n\\n- Повертає новий `state`\\n\\n- Store\\n\\n- Єдине джерело істини\\n\\n- Зберігає весь стан застосунку\\n\\nОднонапрямлений потік даних\\n\\n- UI викликає `dispatch`\\n\\n- Action доходить до редюсера\\n\\n- Редюсер повертає новий стан\\n\\n- UI підписаний на зміни сховища й перемальовується\\n\\nТакий потік виключає «сховані» зміни стану.\\nЧому це важливо\\n\\n- Стан не можна змінити випадково\\n\\n- Поведінку легко відтворити\\n\\n- Редюсери простіше тестувати\\n\\nВисновок\\nRedux дотримується підходу Flux: однонапрямлені дані + чисті редюсери, що робить стан прозорим і керованим.\",\"dispatch({ type: \\\"user/login\\\", payload: user });\"],[2879,\"Time-travel debugging — змога «перемотувати» стан застосунку назад і вперед. Redux зберігає історію actions, а оскільки редюсери детерміновані, будь-який стан можна відтворити. Це дає змогу побачити, який action призвів до помилки. Звичайно це реалізують через Redux DevTools.\",\"Подорож у часі — прямий наслідок архітектури Redux.\\nВизначення\\nВизначення: time-travel debugging — техніка зневадження, за якої стан застосунку відтворюють, застосовуючи actions одне за одним.\\nЧому це взагалі можливо\\n\\n- Стан немутабельний\\n\\n- Кожний action створює новий стан\\n\\n- Редюсери — чисті функції\\n\\n- Той самий вхід → той самий вихід\\n\\n- Actions — події\\n\\n- Їх можна зберігати й відтворювати\\n\\nЯк це виглядає на практиці\\n\\n- Користувач клікає кнопку\\n\\n- Action з'являється в DevTools\\n\\n- Ви можете:\\n\\n- відкотитися до будь-якого кроку\\n\\n- подивитися на різницю стану\\n\\n- повторити ланцюжок actions\\n\\nЩо це дає розробникові\\n\\n- Пошук складних багів\\n\\n- Розуміння логіки застосунку\\n\\n- Змогу відтворити баг із журналу actions\\n\\nОбмеження\\n\\n- Великий стан → багато пам'яті\\n\\n- Побічні ефекти (API) не «перемотуються»\\n\\n- У production це звичайно вимкнено\\n\\nВисновок\\nTime-travel debugging працює, адже Redux робить стан детермінованим і відтворюваним, а не «магічним».\",null],[2880,\"Подорож у часі називають killer-фічею, адже вона радикально полегшує зневадження. Розробник бачить усю історію змін стану й може зрозуміти, де саме логіка пішла не так. Це особливо важливо у складних інтерфейсах із великою кількістю станів. Такий рівень прозорості рідко доступний в інших підходах.\",\"Redux цінують не лише за архітектуру, а й за інструменти.\\nЧому це справді «killer-фіча»\\n1. Повна прозорість стану\\n\\n- Кожна зміна видна\\n\\n- Зрозуміло, який action спрацював і коли\\n\\n- «Схованих» мутацій немає\\n\\n2. Відтворюваність багів\\n\\n- Послідовність actions можна зберегти\\n\\n- Баг можна відтворити в іншому середовищі\\n\\n- Спілкування в команді полегшується\\n\\n3. Прискорення розробки\\n\\n- Менше `console.log`\\n\\n- Швидший аналіз складних сценаріїв\\n\\n- Легше залучення нових розробників\\n\\n4. Архітектурна дисципліна\\n\\n- Вона змушує писати чисті редюсери\\n\\n- Вона вчить думати подіями, а не мутаціями\\n\\n- Вона робить логіку передбачуваною\\n\\nВисновок\\nПодорож у часі — killer-фіча Redux, адже вона перетворює стан із «чорної скриньки» на прозору, керовану історію, що значно підвищує якість і швидкість розробки.\",null],[2881,\"Redux і MobX розв'язують ту саму задачу — керування станом, — але роблять це по-різному. Redux заснований на явних подіях, немутабельності й передбачуваності. MobX ставить усе на реактивність й автоматичне відстежування залежностей. Redux частіше обирають для великих, складних застосунків, а MobX — задля швидкої, зручної розробки UI.\",\"Основна різниця між Redux і MobX — філософія керування станом.\\nВизначення\\nВизначення: Redux — орієнтоване на події сховище з однонапрямленим потоком даних; MobX — реактивна система стану з автоматичним відстежуванням залежностей.\\nЯк думає Redux\\nRedux змушує описувати, що сталося.\\n\\n- Стан немутабельний\\n\\n- Будь-яка зміна — через `action`\\n\\n- Усю логіку зосереджено в редюсерах\\n\\n- Оновлення UI — наслідок зміни сховища\\n\\nНаслідки:\\n\\n- Поведінку легко відтворити\\n\\n- Відмінне зневадження\\n\\n- Більше шаблонного коду\\n\\nЯк думає MobX\\nMobX зосереджується на даних і на їхньому використанні.\\n\\n- Стан можна мутувати напряму\\n\\n- Компоненти підписуються автоматично на дані, які вони використовують\\n\\n- Явного поділу на action / reducer немає\\n\\n- Зміни «проштовхують» реактивно\\n\\nНаслідки:\\n\\n- Менше коду\\n\\n- Швидкий старт\\n\\n- Ланцюжок змін важче відстежити\\n\\nКлючові відмінності на практиці\\n\\n- Передбачуваність\\n\\n- Redux: висока\\n\\n- MobX: залежить від вашої дисципліни\\n\\n- Зневадження\\n\\n- Redux: подорож у часі, історія подій\\n\\n- MobX: реактивні оновлення без явного журналу\\n\\n- Поріг входу\\n\\n- Redux: вищий\\n\\n- MobX: нижчий\\n\\n- Масштабування\\n\\n- Redux: добре для великих команд\\n\\n- MobX: відмінно для малих і середніх проєктів\\n\\nВисновок\\nRedux обирають, коли важливі контроль, передбачуваність і зневадження; MobX — коли потрібний швидкий, зручний реактивний UI з мінімумом шаблонного коду.\",\"dispatch({ type: \\\"counter/increment\\\" });\\n\\nstore.count++;\"],[2882,\"MobX побудований на патерні Observer і на принципах реактивного програмування. Стан оголошують як observable, а компоненти стають спостерігачами автоматично. Коли дані змінюються, MobX сам вирішує, які частини UI треба оновити. Розробникові не доводиться описувати зв'язки між станом і поданням вручну.\",\"MobX використовує реактивну модель, близьку до логіки електронних таблиць.\\nВизначення\\nВизначення: патерн спостерігача — патерн, у якому об'єкти сповіщають автоматично про зміни даних, на які вони підписані.\\nЯк це реалізовано в MobX\\n\\n- Observable\\n\\n- Дані, які спостерігають\\n\\n- Observer\\n\\n- Компоненти або функції, які використовують ці дані\\n\\n- Автоматичне відстежування\\n\\n- MobX сам запам'ятовує, які observable прочитали\\n\\n- `count` — observable\\n\\n- Компонент, який читає `count`, стає спостерігачем\\n\\n- Коли `count` змінюється, UI оновлюють автоматично\\n\\nЧим це відрізняється від підходу Flux\\n\\n- Явної події (`action`) немає\\n\\n- Централізованого редюсера немає\\n\\n- Зв'язки визначають під час виконання\\n\\nПлюси й мінуси патерну\\n\\n- Плюси\\n\\n- Мінімум коду\\n\\n- Інтуїтивна модель\\n\\n- Висока продуктивність завдяки точковим оновленням\\n\\n- Мінуси\\n\\n- Складні сценарії важче зневаджувати\\n\\n- Не завжди очевидно, звідки прийшла зміна\\n\\nВисновок\\nMobX заснований на Observer + реактивності, що робить його потужним, зручним інструментом, але він вимагає дисципліни, якщо застосунок має залишитися зрозумілим і таким, що легко підтримувати.\",\"const store = makeAutoObservable({\\n  count: 0,\\n  inc() {\\n    this.count++;\\n  },\\n});\"],[2883,\"`Thunk` — просте middleware, яке дає змогу писати асинхронну логіку прямо в actions. `Saga` — окремий шар логіки, заснований на генераторах, який керує побічними ефектами декларативно. `Thunk` простіше опанувати, але він гірше масштабується. `Saga` складніша, але вона краще придатна для складних сценаріїв і бізнес-логіки.\",\"Загальна ідея\\nRedux сам собою синхронний, тому задля асинхронної логіки використовують middleware.\\nRedux Thunk\\nThunk дає змогу, щоб action був функцією.\\n\\nХарактеристики:\\n\\n- Мінімальний поріг входу\\n\\n- Логіку й actions змішано\\n\\n- Добре для простих запитів\\n\\n- Складні сценарії важко тестувати\\n\\nRedux Saga\\nSaga використовує генератори, щоб описати ефекти.\\n\\nХарактеристики:\\n\\n- Чіткий поділ логіки й actions\\n\\n- Декларативний опис ефектів\\n\\n- Зручна для складних сценаріїв\\n\\n- Добре тестується\\n\\n- Вищий поріг входу\\n\\nКлючові відмінності в підході\\n\\n- Thunk імперативний\\n\\n- Saga декларативна\\n\\n- Thunk простіше читати початківцям\\n\\n- Saga масштабується краще\\n\\nВисновок\\n`Thunk` — швидкий, простий вибір для малих проєктів. `Saga` виправдана, коли логіка складна й асинхронна й потребує строгого контролю.\",\"const fetchData = () => (dispatch) => {\\n  dispatch(start());\\n  fetch(url)\\n    .then(r => r.json())\\n    .then(data => dispatch(success(data)));\\n};\\n\\nfunction* fetchDataSaga() {\\n  try {\\n    const data = yield call(api.fetch);\\n    yield put(success(data));\\n  } catch (e) {\\n    yield put(error(e));\\n  }\\n}\"],[2884,\"MobX складніше зневаджувати через його неявні залежності. Компоненти підписуються на observable-дані автоматично, й не завжди очевидно, що саме спричинило оновлення. На відміну від Redux, де потік даних строго детермінований, у MobX реактивність відбувається «магічно». Це ускладнює трасування змін.\",\"Ключова причина складності\\nMobX побудований на автоматичній реактивності.\\nЩо відбувається під капотом\\n\\n- Observable-дані відстежують автоматично\\n\\n- Компонент підписується на все, що він використовує\\n\\n- Будь-яка зміна спричиняє повторне обчислення залежних частин\\n\\nЧому це ускладнює зневадження\\n\\n- Явних actions як єдиної точки входу немає\\n\\n- Важко зрозуміти, яка зміна спричинила повторний рендер\\n\\n- Залежності формують динамічно\\n\\n- Поведінка може відрізнятися від ваших очікувань\\n\\nПорівняння з Redux (концептуально)\\n\\n- Redux:\\n\\n- явні actions\\n\\n- одне сховище\\n\\n- зрозумілий потік даних\\n\\n- MobX:\\n\\n- мутабельні дані\\n\\n- реактивні зв'язки\\n\\n- менше шаблонного коду, більше «магії»\\n\\nКоли MobX усе ж виправданий\\n\\n- Малі проєкти\\n\\n- Прототипи\\n\\n- Команди з добрим розумінням реактивності\\n\\nВисновок\\nУ MobX швидше розробляти, але складніше зневаджувати через його неявну реактивність. Redux простіше аналізувати й підтримувати у великих командах.\",null],[2885,\"Глобальний стан зберігає дані, які використовують у кількох частинах застосунку. Локальний стан придатний для UI-деталей певного компонента. Чим ширша область, у якій дані використовують, тим вища ймовірність, що їхнє місце — у глобальному сховищі. Надлишковий глобальний стан ускладнює підтримку. Рішення завжди ухвалюють на основі справжнього використання даних.\",\"Що таке глобальний стан\\nГлобальний стан — дані, доступні водночас кільком незалежним частинам застосунку. Його використовують, щоб синхронізувати поведінку різних компонентів.\\nОсновні критерії, щоб перенести дані в глобальний стан\\nПерш ніж зробити дані глобальними, звичайно оцінюють такі чинники:\\n\\n- Область використання\\n\\n- Дані потрібні на кількох екранах\\n\\n- Дані використовують компоненти без прямого ієрархічного зв'язку\\n\\n- Довговічність\\n\\n- Стан треба зберігати між навігаціями\\n\\n- Дані не прив'язані до життєвого циклу єдиного компонента\\n\\n- Семантика даних\\n\\n- Користувач\\n\\n- Права доступу\\n\\n- Глобальні налаштування\\n\\nЩо не варто зберігати в глобальному стані\\n\\n- Стан UI-елементів\\n\\n- Тимчасові прапорці й локальні перемикачі\\n\\n- Дані, які використовують лише в одному компоненті\\n\\nПриклад локального стану:\\n\\nТипова помилка\\nПоширена проблема — переносити в глобальний стан усе, що є, «на майбутнє». Це призводить до ускладнення логіки й до зростання зчеплення.\\nВисновок\\nГлобальний стан має містити лише дані, які справді спільні й значущі. Решту безпечніше й простіше зберігати локально.\",\"const [isOpen, setIsOpen] = useState(false)\"],[2886,\"Надлишковий глобальний стан ускладнює логіку застосунку. Код стає зчепленішим, а зміни — ризикованими. Складність зневадження й тестування зростає. Виникають надлишкові перемалювання компонентів. У результаті застосунок стає важче підтримувати й розвивати.\",\"Глобальний стан — потужний інструмент, але, коли його застосовують неналежно, він починає шкодити архітектурі.\\nОсновні проблеми з надлишковим глобальним станом\\n\\n- Зростання зчеплення\\n\\n- Компоненти починають залежати від спільного сховища\\n\\n- Зміна стану в одному місці зачіпає безліч екранів\\n\\n- Складність зневадження\\n\\n- Важко зрозуміти, хто змінив дані й чому\\n\\n- Логіка оновлення стану розмазується по проєкту\\n\\n- Проблеми з продуктивністю\\n\\n- Часті оновлення глобального стану\\n\\n- Надлишкові повторні рендери компонентів\\n\\n- Погіршення читності коду\\n\\n- Прості UI-сценарії потребують роботи зі сховищем\\n\\n- Виникає багато надлишкового шаблонного коду\\n\\nТиповий антипатерн\\nЗберігання в глобальному стані такого:\\n\\n- стану модальних вікон\\n\\n- фокусу полів введення\\n\\n- тимчасових прапорців інтерфейсу\\n\\nВисновок\\nГлобальний стан варто використовувати свідомо й обмежено. Чим ближче дані до UI, тим логічніше тримати їх локально.\",null],[2887,\"Mutations забезпечують єдиний, контрольований спосіб змінити стан. Якщо змінювати `state` напряму, стає важко відстежити джерело змін. Mutations роблять зміни синхронними й явними. Це важливо задля зневадження й задля підтримки застосунку. Такий підхід робить потік даних легшим для розуміння.\",\"Обмеження змін стану лише mutations — фундаментальний принцип Vuex.\\nПроблеми зі зміною стану напряму\\nЯкщо змінювати `state` напряму:\\n\\n- неможливо відстежити джерело зміни\\n\\n- єдиний потік даних ламається\\n\\n- зневадження ускладнюється\\n\\nРоль mutations\\nMutations розв'язують ці проблеми.\\nОсобливості:\\n\\n- кожну зміну описано явно\\n\\n- зміни синхронні\\n\\n- їх легко журналювати й відстежувати\\n\\nПриклад неправильного підходу:\\n\\nПравильний варіант:\\n\\nВигода для інструментів розробки\\n\\n- Vue Devtools показує історію mutations\\n\\n- баги простіше відтворити\\n\\n- стан стає передбачуваним\\n\\nВисновок\\nЗміна стану лише через mutations забезпечує прозорість, контроль і надійність керування станом.\",\"this.$store.state.user = user; // bad\\n\\nthis.$store.commit('setUser', user);\"],[2888,\"Actions використовують, щоб виконувати асинхронну логіку, як-от HTTP-запити або таймери. Вони не змінюють стану напряму, а викликають mutations. Це дає змогу відділити бізнес-логіку від зміни стану. Такий підхід робить код чистішим і зрозумілішим. Actions — стандартне місце для асинхронних операцій.\",\"Асинхронну логіку у Vuex виносять в actions, аби зберегти передбачуваність змін стану.\\nЧому асинхронність не можна робити в mutations\\nMutations мають бути:\\n\\n- синхронними\\n\\n- швидкими\\n\\n- передбачуваними\\n\\nАсинхронний код порушує ці принципи.\\nРоль actions\\nActions виконують усю асинхронну роботу.\\nВони можуть:\\n\\n- виконувати HTTP-запити\\n\\n- працювати з таймерами\\n\\n- викликати кілька mutations\\n\\n- містити бізнес-логіку\\n\\nПриклад:\\n\\nВзаємодія з компонентами\\nКомпоненти:\\n\\n- надсилають actions\\n\\n- не знають деталей реалізації\\n\\n- отримують дані зі `state`\\n\\nВисновок\\nActions служать шаром асинхронної й бізнес-логіки, тримаючи mutations простими й передбачуваними.\",\"actions: {\\n  async loadData({ commit }) {\\n    commit('setLoading', true);\\n    const data = await api.fetch();\\n    commit('setData', data);\\n    commit('setLoading', false);\\n  }\\n}\"],[2889,\"RTK Query варто використовувати напряму для більшості операцій, які отримують, кешують й інвалідують дані із сервера, оскільки він автоматично керує завантаженням, помилками й кешем. Нормалізацію даних у Redux слід застосовувати, коли потрібно виконувати складні, наскрізні оновлення між різними сутностями або реалізувати оптимістичні оновлення, які зачіпають кілька запитів. RTK Query ідеальний для типового CRUD, а нормалізація — для складних доменних моделей із тісними зв'язками.\",\"RTK Query — потужний інструмент для керування серверним станом, вбудований у Redux Toolkit. Він абстрагує логіку запитів, кешування, синхронізації й оновлення даних, істотно зменшуючи шаблонний код. Використовувати RTK Query напряму рекомендується для більшості сценаріїв роботи з API, особливо для стандартних CRUD-операцій (Create, Read, Update, Delete).\\nКоли використовувати RTK Query напряму\\n\\n- Просте отримання й кешування даних: RTK Query автоматично кешує відповіді, керує життєвим циклом підписки й запобігає дубльованим запитам.\\n- Автоматична інвалідація кешу: можна налаштувати автоматичне оновлення даних після мутацій (наприклад, після створення поста список постів позначають як застарілий).\\n- Стандартні UI-патерни: він надає хуки (useQuery, useMutation), які дають прапорці isLoading й isError, що ідеально для відображення стану завантаження в компонентах.\\n\\nКоли нормалізувати дані в Redux\\nНормалізація — процес організації даних у стані Redux як словників (об'єктів) за ключами ID з окремими масивами ID для збереження порядку. Вона корисна, коли дані мають складні взаємозв'язки.\\n\\n- Складні оновлення між сутностями: наприклад, коли користувача видаляють, зі стану потрібно також видалити всі його коментарі.\\n- Оптимістичні оновлення: коли ви хочете оновити UI миттєво й потім синхронізуватися із сервером, а це оновлення зачіпає кілька типів даних.\\n- Ефективні оновлення UI: нормалізація дає змогу селекторам і React-компонентам ефективно мемоізувати, оскільки посилання на незмінені об'єкти залишаються тими самими.\\n\\nВисновок: починайте з використання RTK Query напряму для всіх взаємодій із сервером — це покриває 90 % випадків. Переходьте до ручної нормалізації даних у Redux лише тоді, коли ваш застосунок потребує складних, наскрізних оновлень стану між різними сутностями, які складно виразити через автоматичну інвалідацію тегів RTK Query, або коли максимальна продуктивність оновлення пов'язаних даних критично важлива.\",\"// An example of using RTK Query directly\\nimport { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\\n\\nexport const api = createApi({\\n  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),\\n  endpoints: (builder) => ({\\n    getPosts: builder.query({ query: () => '/posts' }),\\n    addPost: builder.mutation({\\n      query: (newPost) => ({\\n        url: '/posts',\\n        method: 'POST',\\n        body: newPost,\\n      }),\\n      // Automatically refreshes the cache for getPosts\\n      invalidatesTags: ['Post'],\\n    }),\\n  }),\\n});\\n\\n// In a React component\\nconst { data: posts, isLoading } = api.useGetPostsQuery();\\nconst [addPost] = api.useAddPostMutation();\\n\\n// An example of a normalised structure in Redux\\n{\\n  posts: {\\n    ids: [1, 2, 3],\\n    entities: {\\n      1: { id: 1, title: 'Post A', authorId: 101 },\\n      2: { id: 2, title: 'Post B', authorId: 102 },\\n      3: { id: 3, title: 'Post C', authorId: 101 },\\n    }\\n  },\\n  users: {\\n    ids: [101, 102],\\n    entities: {\\n      101: { id: 101, name: 'Alice' },\\n      102: { id: 102, name: 'Bob' },\\n    }\\n  }\\n}\\n\\n// A selector that gets a post together with its author's details\\nconst selectPostWithAuthor = (state, postId) => {\\n  const post = state.posts.entities[postId];\\n  const author = state.users.entities[post.authorId];\\n  return { ...post, author };\\n};\"],[2890,\"Redux стає неефективним, коли застосунок невеликий і простий, а його використання додає надмірного шаблонного коду. Він також може сповільнювати роботу, якщо у сторі зберігають занадто багато даних, які часто змінюються, що призводить до частих повторних рендерів усіх підключених компонентів. Для простого локального стану краще використовувати вбудовані засоби React, такі як useState або Context API.\",\"Redux — потужна бібліотека керування станом, але вона не завжди оптимальний вибір. Її ефективність падає в певних сценаріях, і важливо розуміти ці межі, щоб не ускладнювати архітектуру без потреби.\\nКоли Redux додає надлишковості\\nГоловна критика Redux — велика кількість шаблонного коду. Для кожної зміни стану доводиться створювати екшени, редюсери й, можливо, thunk-и. У невеликому застосунку, де стан мінімальний і локалізований у кількох компонентах, ця складність невиправдана. Наприклад, щоб керувати станом форми або переключати модальне вікно, достатньо хуків React.\\nПроблеми продуктивності\\nRedux може стати вузьким місцем, якщо:\\n\\n- У сторі зберігають величезний обсяг даних, які часто оновлюють (наприклад, живі дані сенсорів). Кожне оновлення спричиняє повторний рендер усіх компонентів, підключених через `connect` або `useSelector`, навіть якщо вони використовують іншу частину стану.\\n- Ви зберігаєте у сторі дані, які не серіалізуються (наприклад, проміси або екземпляри класів), що суперечить принципам Redux й ускладнює зневадження.\\n- Логіка редюсерів стає занадто складною й повільною через глибоке копіювання великих об'єктів стану.\\nПрактичний приклад: простий стан форми\\nРозглянемо приклад керування формою входу. З Redux це забрало б багато коду:\\n\\nТа сама функціональність із `useState` займає кілька рядків усередині компонента, що для такого випадку значно простіше й продуктивніше.\\nАльтернативи й сучасні підходи\\nДля простого стану, спільного для компонентів одного рівня або на невеликій глибині, відмінно працює Context API від React. Для складніших сценаріїв з асинхронними операціями можна розглянути бібліотеки, такі як React Query (для серверних даних) або Zustand/Recoil, які пропонують легший API й у чомусь кращу продуктивність.\\nВисновок: Redux варто використовувати у великих застосунках зі складною бізнес-логікою, де потрібні централізований, передбачуваний стан, зручні інструменти зневадження (такі як Redux DevTools) і строга архітектура. Для невеликих проєктів, простого стану UI або високочастотних оновлень даних він часто стає надлишковим і неефективним.\",\"// actions.js\\nexport const setEmail = (email) => ({ type: 'SET_EMAIL', payload: email });\\nexport const setPassword = (pw) => ({ type: 'SET_PASSWORD', payload: pw });\\n\\n// reducer.js\\nconst initialState = { email: '', password: '' };\\nfunction formReducer(state = initialState, action) {\\n  switch(action.type) {\\n    case 'SET_EMAIL': return { ...state, email: action.payload };\\n    case 'SET_PASSWORD': return { ...state, password: action.payload };\\n    default: return state;\\n  }\\n}\\n\\n// In the component: dispatching actions, selectors...\"],[2891,\"Redux — бібліотека для керування станом застосунку. Action — звичайний об'єкт, який описує, що сталося (наприклад, 'USER_LOGGED_IN'). Reducer — чиста функція, яка приймає попередній стан й екшен і повертає новий стан. Store — єдиний централізований об'єкт, який зберігає весь стан застосунку й надає методи для його оновлення (dispatch) і підписки на зміни (subscribe). Разом вони утворюють передбачуваний цикл оновлення даних.\",\"Основні концепції Redux\\nRedux — бібліотека для керування станом у JavaScript-застосунках, яку найчастіше використовують із React. Її архітектура базується на трьох фундаментальних принципах: єдине джерело правди (store), стан доступний лише для читання, а зміни роблять лише через чисті функції (reducers).\\nAction\\nAction — звичайний об'єкт JavaScript, який описує намір змінити стан. Кожен екшен має мати тип (type), а також може нести додаткову інформацію (payload). Екшен сам не виконує зміни; він лише сигналізує, що в застосунку щось сталося (наприклад, користувач натиснув кнопку).\\n\\nReducer\\nReducer — чиста функція, яка визначає, як стан застосунку змінюється у відповідь на екшен. Вона приймає два аргументи: поточний стан й об'єкт екшена, і повертає новий стан. Важливо, щоб редюсер не мутував початкового стану, а повертав новий об'єкт. Redux може поєднувати кілька редюсерів, щоб керувати різними частинами стану.\\n\\nStore\\nStore — об'єкт, який усе поєднує. Він зберігає глобальний стан застосунку, дає змогу оновлювати його через метод dispatch(action), реєструє слухачів змін через subscribe(listener) і надає доступ до стану через getState(). Store створюють функцією createStore(rootReducer).\\n\\nРазом екшени, редюсери й store утворюють односпрямований потік даних: UI надсилає екшен, store передає екшен до редюсера, редюсер обчислює новий стан, store оновлюється й повідомляє своїх підписників, а UI перерендерюється на основі нового стану. Це робить зневадження й тестування передбачуваними.\\nВисновок: Redux із його екшенами, редюсерами й стором особливо корисний у середніх і великих застосунках, де складним станом потрібно керувати централізовано й де він має бути передбачуваним і легким для зневадження. Його варто застосовувати, коли передавання пропів углиб у React стає проблемою або коли стан потрібно синхронізувати між багатьма незалежними компонентами.\",\"// An example action creator that returns an action\\nconst addTodo = (text) => ({\\n  type: 'ADD_TODO',\\n  payload: { text, id: Date.now(), completed: false }\\n});\\n// Calling dispatch(addTodo('Learn Redux')) sends this object into the store.\\n\\n// An example reducer for a list of tasks\\nconst initialState = [];\\nfunction todosReducer(state = initialState, action) {\\n  switch (action.type) {\\n    case 'ADD_TODO':\\n      // Return a new array with the new task added\\n      return [...state, action.payload];\\n    case 'TOGGLE_TODO':\\n      return state.map(todo =>\\n        todo.id === action.payload.id\\n          ? { ...todo, completed: !todo.completed }\\n          : todo\\n      );\\n    default:\\n      return state; // If the action is not recognised, the state does not change\\n  }\\n}\\n\\nimport { createStore } from 'redux';\\nimport rootReducer from './reducers';\\n\\n// Creating the store with the root reducer\\nconst store = createStore(rootReducer);\\n\\n// Dispatching an action to change the state\\nstore.dispatch(addTodo('Understand the store'));\\n\\n// Subscribing to state changes (for example, to update the UI)\\nconst unsubscribe = store.subscribe(() => {\\n  console.log('State updated:', store.getState());\\n});\\n\\n// You can unsubscribe later\\n// unsubscribe();\"],[2892,\"Reducer має бути чистою функцією, щоб гарантувати передбачуваність змін стану. Чиста функція не має побічних ефектів і завжди повертає той самий результат для тих самих аргументів. Це полегшує зневадження, тестування й відтворення станів застосунку.\",\"Чому reducer має бути чистою функцією?\\nУ Redux reducer — функція, яка приймає поточний стан і дію й повертає новий стан. Вимога чистоти означає, що reducer не має змінювати переданий йому стан безпосередньо, не має виконувати побічних ефектів (запитів до API, мутацій DOM, викликів setTimeout) і має повертати новий об'єкт стану, а не модифікувати старий.\\n\\nОсновні причини\\n\\n- Передбачуваність: чиста функція завжди повертає той самий результат для тих самих вхідних даних. Це дає змогу відстежувати зміни стану й легко відтворювати баги.\\n- Тестованість: чисті функції легко тестувати — не потрібно створювати складних моків або середовищ.\\n- Відтворюваність: Redux DevTools можуть записувати й відтворювати послідовності дій, тому що reducer не має прихованих залежностей.\\n- Оптимізація: React може ефективно порівнювати попередній і новий стан (поверхневе порівняння), щоб вирішити про перемалювання.\\n\\nПриклад\\n\\nУ першому випадку React може не помітити зміни, оскільки посилання на об'єкт залишилося тим самим. У другому створюють новий об'єкт, і React належно оновлює UI.\\n\\nВисновок\\nЧистота reducer'а — не просто правило, а фундаментальний принцип, який забезпечує надійність і передбачуваність керування станом. Застосовуйте чисті функції всюди, де потрібне детерміноване перетворення даних, особливо в Redux й інших Flux-подібних архітектурах.\",\"// Wrong: a mutation of the state\\nfunction badReducer(state, action) {\\n  state.count += 1; // a mutation\\n  return state;\\n}\\n\\n// Right: we return a new object\\nfunction goodReducer(state, action) {\\n  return { ...state, count: state.count + 1 };\\n}\"],[2893,\"Функції-генератори в Redux Saga використовують для керування асинхронними операціями, як-от запити до API. Вони дозволяють призупиняти й відновлювати виконання, що робить код читабельнішим і тестованішим. Саги використовують yield, щоб чекати ефекти, а middleware їх обробляє. Це спрощує роботу з побічними ефектами в Redux.\",\"Для чого потрібні генератори в Redux Saga?\\nRedux Saga — middleware для керування побічними ефектами в Redux-застосунках. Функції-генератори — основа Saga, оскільки вони дозволяють писати асинхронний код у синхронному стилі. Генератори можуть призупиняти своє виконання за допомогою ключового слова `yield` і відновлювати його пізніше, що ідеально пасує обробці послідовних асинхронних дій.\\nЯк це працює?\\nКоли сага виконується, вона передає керування middleware через `yield`. Middleware обробляє ефект (наприклад, виклик до API) і повертає результат назад у генератор. Це робить код лінійним і легко читабельним, без колбеків або промісів.\\nПриклад коду\\n\\nУ цьому прикладі `call` призупиняє сагу, доки виклик до API не завершиться, а `put` надсилає дію в Redux-стор.\\nПереваги використання генераторів\\n\\n- Спрощення тестування: ефекти можна перевіряти без виконання реальних запитів.\\n- Читабельність: код виглядає синхронним, що полегшує розуміння логіки.\\n- Керування складними потоками: легко обробляти паралельні задачі, скасування й затримки.\\nВисновок: функції-генератори в Redux Saga застосовують для ефективного керування асинхронними операціями, роблячи код передбачуваним і тестованим. Це особливо корисно у великих застосунках із безліччю побічних ефектів.\",\"import { call, put, takeEvery } from 'redux-saga/effects';\\nimport { fetchUserApi } from './api';\\n\\nfunction* fetchUser(action) {\\n  try {\\n    const user = yield call(fetchUserApi, action.payload);\\n    yield put({ type: 'FETCH_USER_SUCCESS', payload: user });\\n  } catch (error) {\\n    yield put({ type: 'FETCH_USER_FAILURE', error });\\n  }\\n}\\n\\nfunction* watchFetchUser() {\\n  yield takeEvery('FETCH_USER_REQUEST', fetchUser);\\n}\"],[2894,\"Redux Saga — middleware-бібліотека для Redux, яка керує побічними ефектами, як-от асинхронними запитами або доступом до стора. Вона використовує генератори ES6, щоб писати саги — функції, які слухають дії й виконують логіку. Саги роблять код тестованішим і керованішим за thunk'и.\",\"Що таке Redux Saga?\\nRedux Saga — middleware для Redux, призначений, щоб керувати побічними ефектами в застосунках. Він дає змогу писати асинхронну логіку, як-от виклики API, таймери або доступ до стора, у вигляді саг — функцій-генераторів. Саги слухають задиспатчені дії й можуть запускати, призупиняти або скасовувати задачі, що робить їх потужним інструментом для складних потоків даних.\\n\\nЯк це працює?\\nRedux Saga використовує генератори ES6 (функції з `function*`) й ефекти на кшталт `call`, `put`, `takeEvery` і `takeLatest`. Ефекти — прості об'єкти, які middleware інтерпретує й виконує. Наприклад, `call` викликає асинхронну функцію, а `put` диспатчить нову дію в Redux-стор.\\n\\nПриклад коду\\n\\nУ цьому прикладі сага `watchFetchUser` слухає дію `FETCH_USER_REQUEST` і запускає `fetchUser`, яка викликає API й диспатчить успіх або невдачу.\\n\\nДе його застосовують?\\nRedux Saga часто використовують у великих React-застосунках, де потрібне складне керування асинхронними потоками — наприклад, у роботі з WebSocket'ами, з паралельними запитами або зі скасуванням операцій. Він особливо корисний, коли побічні ефекти потрібно тестувати в ізоляції.\\n\\nВисновок: Redux Saga варто застосовувати, коли в застосунку багато складних асинхронних сценаріїв, які потребують тонкого контролю, скасування або композиції, і коли важливі тестованість і читабельність коду.\",\"import { call, put, takeEvery } from 'redux-saga/effects';\\nimport { fetchUserApi } from './api';\\n\\nfunction* fetchUser(action) {\\n  try {\\n    const user = yield call(fetchUserApi, action.payload);\\n    yield put({ type: 'FETCH_USER_SUCCESS', payload: user });\\n  } catch (error) {\\n    yield put({ type: 'FETCH_USER_FAILURE', payload: error });\\n  }\\n}\\n\\nfunction* watchFetchUser() {\\n  yield takeEvery('FETCH_USER_REQUEST', fetchUser);\\n}\"],[2895,\"У React-застосунках задля керування станом використовують Redux, MobX, Zustand, Recoil і вбудований Context API. Redux популярний для великих проєктів із передбачуваним станом. MobX використовує реактивне програмування. Zustand — легка альтернатива. Context API придатний для простих випадків, без додаткових бібліотек.\",\"Огляд бібліотек керування станом у React\\nКерування станом — ключова задача в React-застосунках, особливо коли дані передають між безліччю компонентів. Вбудовані `useState` і `useReducer` придатні для локального стану, але глобальний або складний стан потребує спеціалізованих рішень.\\n\\nОсновні бібліотеки\\n\\n- Redux — передбачуваний стан через єдиний стор і чисті редюсери. Він використовує однонапрямлений потік даних. Він придатний для великих застосунків із безліччю взаємодій.\\n- MobX — реактивне керування, у якому стан складається зі спостережуваних об'єктів. Він автоматично оновлює компоненти при їхній зміні. Він зручний для застосунків із частими оновленнями даних.\\n- Zustand — мінімалістична бібліотека з простим API. Вона створює стор через хук і не потребує обгорток. Вона ідеальна для середніх проєктів.\\n- Recoil — експериментальна бібліотека від Facebook; вона використовує атоми й селектори. Вона добре інтегрується з Concurrent Mode у React.\\n- Context API — вбудований інструмент, щоб передавати дані деревом компонентів. Він придатний для простих випадків, але може спричиняти надлишкові повторні рендери.\\n\\nПриклад коду з Zustand\\n\\nВисновок\\nВибір бібліотеки залежить від масштабу проєкту й переваг команди. Redux залишається стандартом для великих застосунків, Zustand — задля простоти, а Context API — задля мінімуму залежностей. Важливо розуміти компроміси між продуктивністю й складністю.\",\"import { create } from 'zustand';\\n\\nconst useStore = create((set) => ({\\n  count: 0,\\n  increment: () => set((state) => ({ count: state.count + 1 })),\\n  decrement: () => set((state) => ({ count: state.count - 1 })),\\n}));\\n\\nfunction Counter() {\\n  const { count, increment, decrement } = useStore();\\n  return (\\n    <div>\\n      <button onClick={decrement}>-</button>\\n      <span>{count}</span>\\n      <button onClick={increment}>+</button>\\n    </div>\\n  );\\n}\"],[2896,\"Оптимістичні оновлення в RTK Query дають змогу оновлювати інтерфейс одразу, перед тим як надійде відповідь від сервера, що робить застосунок відгукливішим. Для цього використовують опцію `onQueryStarted` у мутації, де можна застосувати `patchQueryResult`, щоб тимчасово змінити кеш. Якщо запит завершується помилкою, зміни відкочують за допомогою `undo`. Це особливо корисно для операцій, які майже завжди успішні — наприклад, лайків або додавання до улюбленого.\",\"Що таке оптимістичні оновлення?\\nОптимістичні оновлення — техніка, за якої інтерфейс оновлюють одразу після дії користувача, не чекаючи на відповідь від сервера. Це створює відчуття миттєвої реакції й покращує UX. У разі помилки зміни відкочують, і користувач бачить актуальний стан.\\n\\nРеалізація в RTK Query\\nRTK Query надає вбудовану підтримку оптимістичних оновлень через колбек `onQueryStarted` у визначенні мутації. Усередині цього колбека можна використати `patchQueryResult`, щоб тимчасово змінити дані в кеші й потім відкотити їх при помилці.\\n\\nПриклад коду\\n\\nКлючові моменти\\n\\n- `updateQueryData` — функція, щоб змінювати кеш; вона повертає об'єкт із методом `undo`.\\n- Важливо обробляти помилки, щоб відкотити зміни й, можливо, показати повідомлення.\\n- Вона придатна для операцій, де ймовірність помилки низька — лайків, редагування тексту.\\n\\nВисновок\\nОптимістичні оновлення в RTK Query — потужний інструмент, щоб створювати відгукливі інтерфейси. Їх варто застосовувати в сценаріях, де користувач очікує миттєвого зворотного зв'язку, а помилки сервера рідкісні або їх можна обробити гарно.\",\"import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\\n\\nconst api = createApi({\\n  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),\\n  endpoints: (builder) => ({\\n    updatePost: builder.mutation({\\n      query: ({ id, ...patch }) => ({\\n        url: `posts/${id}`,\\n        method: 'PATCH',\\n        body: patch,\\n      }),\\n      onQueryStarted: async ({ id, ...patch }, { dispatch, queryFulfilled }) => {\\n        // The optimistic update\\n        const patchResult = dispatch(\\n          api.util.updateQueryData('getPost', id, (draft) => {\\n            Object.assign(draft, patch);\\n          })\\n        );\\n        try {\\n          await queryFulfilled;\\n        } catch {\\n          // The roll-back on an error\\n          patchResult.undo();\\n        }\\n      },\\n    }),\\n  }),\\n});\"],[2897,\"Основні альтернативи Redux: Context API для простих випадків, MobX із його реактивним підходом, Zustand із мінімумом шаблонного коду, Recoil від Facebook, Jotai з його атомарним станом. Вибір залежить від складності застосунку й переваг команди.\",\"Альтернативи Redux задля керування станом\\nRedux довго був стандартом задля керування станом у React, але його надлишковість і складність призвели до появи безлічі альтернатив. Кожна з них по-своєму розв'язує задачу керування станом, пропонуючи інший баланс між простотою, продуктивністю й масштабованістю.\\n\\nОсновні альтернативи\\n\\n- Context API — вбудований у React інструмент, щоб передавати дані деревом компонентів. Він придатний для простих застосунків із невеликою кількістю глобального стану. Приклад використання:\\n\\n- MobX — він використовує реактивне програмування, у якому стан складається зі спостережуваних об'єктів, а компоненти автоматично перемальовуються при їхній зміні. Приклад:\\n\\n- Zustand — мінімалістична бібліотека з простим API на основі хуків. Вона не потребує обгорток або провайдерів. Приклад:\\n\\n- Recoil — бібліотека від Facebook з атомарним станом, у якій кожний атом — незалежна одиниця. Вона придатна для складних залежностей між частинами даних.\\n- Jotai — схожа на Recoil, але з ще простішим API й меншим розміром.\\n\\nВисновок\\nВибір альтернативи Redux залежить від розміру проєкту й вимог до продуктивності. Для невеликих застосунків достатньо Context API; для середніх — Zustand або Jotai; для великих із реактивними даними — MobX або Recoil. Головне — не ускладнювати архітектури без потреби.\",\"const ThemeContext = React.createContext('light');\\nfunction App() {\\n  return (\\n    <ThemeContext.Provider value=\\\"dark\\\">\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nimport { observable, action } from 'mobx';\\nclass Store {\\n  @observable count = 0;\\n  @action increment() { this.count++; }\\n}\\n\\nimport create from 'zustand';\\nconst useStore = create((set) => ({\\n  count: 0,\\n  increment: () => set((state) => ({ count: state.count + 1 })),\\n}));\"],[2898,\"Коли його значення змінюється, React Context перерендерює всі компоненти-споживачі, навіть якщо вони використовують лише частину даних. Менеджери стану на кшталт Redux дають змогу використовувати селектори, які підписуються лише на певні частини стану. Це запобігає зайвим повторним рендерам і покращує продуктивність.\",\"Різниця між менеджером стану й контекстом\\nReact Context — вбудований механізм, щоб передавати дані вниз деревом компонентів без пропсів. Однак він має недолік: коли значення контексту змінюється, кожний компонент, який використовує цей контекст, перерендерюється, навіть якщо вони не використовують ту частину даних, яка змінилася. Це може призвести до проблем із продуктивністю у великих застосунках.\\n\\nМенеджери стану на кшталт Redux забезпечують гнучкіший підхід. Вони дають змогу створювати селектори — функції, які видобувають лише потрібну частину стану. Компоненти підписуються на результат селектора, а не на весь стан. Завдяки цьому повторний рендер відбувається лише тоді, коли змінюється саме та частина даних, від якої компонент залежить.\\n\\nПриклад із React Context\\n\\nПриклад із Redux і селекторами\\n\\nУ Redux селектори можна мемоїзувати (наприклад, за допомогою createSelector із Reselect), що додатково оптимізує обчислення. Context, навпаки, не надає вбудованих засобів мемоїзації або цілеспрямованої підписки.\\n\\nВисновок: використовуйте React Context для простих випадків, коли дані змінюються рідко або застосунок невеликий. Для складного стану з частими оновленнями й безліччю споживачів краще підходять менеджери стану із селекторами, оскільки вони забезпечують точніший контроль над повторними рендерами й продуктивністю.\",\"const ThemeContext = React.createContext();\\n\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Header />\\n      <Content />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Header() {\\n  const { theme } = useContext(ThemeContext);\\n  // When theme changes, both Header and Content will re-render\\n}\\n\\nimport { useSelector } from 'react-redux';\\n\\nfunction Header() {\\n  const theme = useSelector(state => state.theme);\\n  // The component will re-render only when state.theme changes\\n}\"],[2899,\"Context API придатний для простого передавання даних, які рідко змінюються — наприклад, теми або мови. Зовнішній менеджер стану (Redux, Zustand) потрібний за частих оновлень, складної логіки або великої кількості взаємопов'язаних частин стану. Context спричиняє повторний рендер усіх споживачів на будь-якій зміні, що знижує продуктивність. Зовнішні рішення оптимізують оновлення й надають інструменти задля зневадження.\",\"Коли Context API достатній\\nContext API у React призначений, щоб передавати дані деревом компонентів без явного просвердлювання пропсів. Він добре працює для статичних або рідко змінюваних значень, як-от теми дизайну, локалі користувача або даних аутентифікації. У цих сценаріях оновлення відбуваються нечасто, і продуктивність не страждає.\\n\\nКоли потрібний зовнішній менеджер стану\\nЯкщо стан оновлюється часто (наприклад, на кожному натисканні клавіші у формі) або має складну логіку з безліччю залежностей, Context може спричинити надмірні повторні рендери. Зовнішні бібліотеки на кшталт Redux або Zustand використовують підписки на окремі частини стану, що мінімізує перемалювання. Вони також надають middleware, devtools і строгу архітектуру для великих застосунків.\\n\\nПриклад порівняння\\n\\nВисновок\\nВикористовуйте Context API для глобальних даних, які рідко змінюються. Для динамічного стану з частими оновленнями або складною бізнес-логікою обирайте зовнішній менеджер стану, щоб зберегти продуктивність і підтримуваність коду.\",\"// Context - a re-render of all of the consumers on a change\\nconst ThemeContext = React.createContext('light');\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Header /> {/* it re-renders */}\\n      <Footer /> {/* it re-renders */}\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\n// Redux - only the subscribed component updates\\nconst selectTheme = (state) => state.theme;\\nfunction Header() {\\n  const theme = useSelector(selectTheme);\\n  return <div>{theme}</div>;\\n}\"],[2900,\"Redux використовує однонапрямлений потік даних. Коли користувач ініціює дію, викликають dispatch(action). Redux передає дію й поточний стан у редюсер, який повертає новий стан. Потім стор оновлюють, і підписані компоненти перемальовуються.\",\"Як працює цикл Redux\\nRedux — передбачуваний контейнер стану для JavaScript-застосунків. Його ключова особливість — однонапрямлений потік даних, який робить зміни стану передбачуваними й легкими для відстежування.\\n\\nШлях дії від диспатчу до оновлення стану\\n\\n- Дія: користувач або код ініціює дію, створюючи об'єкт дії з полем type й необов'язковими даними (payload).\\n- dispatch(action): виклик store.dispatch(action) надсилає дію до стора.\\n- Редюсер: стор передає поточний стан і дію в кореневий редюсер. Редюсер — чиста функція, яка приймає попередній стан і дію й повертає новий стан, не мутуючи початкового.\\n- Оновлення стора: стор заміняє поточний стан новим, повернутим редюсером.\\n- Повідомлення підписників: стор викликає всіх підписаних слухачів (наприклад, через connect або useSelector у React), що призводить до перемальовування компонентів.\\n\\nПриклад коду\\n\\nВисновок\\nЦикл Redux забезпечує строгу послідовність: дія → dispatch → редюсер → новий стан → оновлення UI. Це полегшує зневадження, тестування й підтримку великих застосунків, де важливо контролювати зміни стану.\",\"// An action creator\\nconst increment = () => ({ type: 'INCREMENT' });\\n\\n// A reducer\\nconst counterReducer = (state = { count: 0 }, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return { count: state.count + 1 };\\n    default:\\n      return state;\\n  }\\n};\\n\\n// The store\\nimport { createStore } from 'redux';\\nconst store = createStore(counterReducer);\\n\\n// The dispatch\\nstore.dispatch(increment());\\nconsole.log(store.getState()); // { count: 1 }\"]]");export{e as default};